// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святителю Іоанну, архієпископу Шанхайському і Сан-Франциському","e":"Akathist to St John, Archbishop of Shanghai and San Francisco","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, всему́ ми́ру істоча́яй оби́льния струї́ духо́внаго наставле́нія і ди́вних чуде́с мно́жество, восхваля́єм тя с любо́вію і зове́м ті:","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Ікос 1","ps":["А́нгела о́бразом яви́ тебі́ в послі́дняя времена́ всея́ тва́рі Созда́тель, да с ми́лостію Бо́жиєю пече́шися о лю́діх земни́х. Взира́юще же на доброді́телі твоя́, преблаже́нне Іоа́нне, вопіє́м ті си́це:","Ра́дуйся, с ра́нняго ді́тства благоче́стієм украше́нний;","ра́дуйся, со стра́хом і тре́петом во́лю Бо́жию іспо́лнивий.","Ра́дуйся, яви́вий благода́ть Бо́жию в та́йних благодія́ніїх;","ра́дуйся, би́строє дале́че су́щих стра́ждущих усли́шаніє.","Ра́дуйся, любвеоби́льноє поспіше́ніє бли́жнім свої́м во спасе́ніє;","ра́дуйся, ра́дованіє всім с ві́рою к тебі́ припа́дающим.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 2","ps":["Ви́дяще оби́льноє доброді́телей твої́х ізлія́ніє, святи́телю сла́вний Іоа́нне, просвіща́ємся ду́хом, я́ко бо живоно́сний істо́чник чуде́с Бо́жиїх, напоя́єши нас, ві́рно вопію́щих к Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум імі́яй преіспо́лненний любве́, ку́пно і богосло́вія, богому́дре Іоа́нне, і богопозна́нієм умудре́нний, і к стра́ждущим лю́дем любо́вію украше́нний, познава́ти і́стиннаго Бо́га нас научи́, да і ми во умиле́нії вопіє́м ті:","Ра́дуйся, непоколеби́мая тверди́не і́стини Правосла́вія;","ра́дуйся, драгоці́нний сосу́де Ду́ха Свята́го.","Ра́дуйся, честни́й обличи́телю неві́рія і лжеуче́нія;","ра́дуйся, ре́вностний ісполни́телю за́повідей Бо́жиїх.","Ра́дуйся, подви́жниче, не дая́й на ло́жі себі́ отдохнове́нія;","ра́дуйся, возлю́бленний па́стирю ста́да Христо́ва.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жия благи́й сиропита́тель і наста́вник ю́ношам яви́лся єси́, воспиту́я в стра́сі Бо́жиєм і приуготовля́я їх к служе́нію Бо́гові. Сего́ ра́ди ча́да твоя́ взира́ють на тя і, благодаря́ще, вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яше воі́стину, о́тче Іоа́нне, с небесе́ тебі́ піснь воспіва́єма би́ти, а не от землі́: ка́ко бо кто от челові́к возмо́гл би твої́х діл вели́чіє пропові́дати? Ми же, принося́ще Бо́гу, я́же і́мами, вопіє́м ті си́це:","Ра́дуйся, непреста́нною моли́твою покрива́яй ча́да твоя́;","ра́дуйся, охрани́телю ста́да твоєго́ кре́стним зна́менієм.","Ра́дуйся, любве́ вели́кия вмісти́лище, не взира́яй на язи́ков разли́чіє;","ра́дуйся, світи́льниче всесві́тлий і вселюби́мий.","Ра́дуйся, о́бразе моли́тви непреста́нния і милосе́рдія;","ра́дуйся, утіше́ній духо́вних пода́телю тре́бующим.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 4","ps":["Бу́рею напа́стей одолева́ємі: ка́ко досто́йно возмо́жем восхвали́ти чудеса́ твоя́, блаже́нне Іоа́нне? Я́ко проше́л єси́ до коне́ць вселе́нния, спасе́нія ра́ди па́стви твоєя́ і благовіствова́нія Єва́нгелія су́щим во тьмі. Благодаря́ще же Бо́га за апо́стольськія труди́ твоя́, воспіва́єм Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша бли́жнії і да́льнії вели́чіє чуде́с твої́х, Бо́жиєю ми́лостію да́же до на́шего вре́мене явля́ємих, ті́мже, в тебі́ Бо́гу прославля́ющемуся див'я́щеся, в стра́сі вопія́ху:","Ра́дуйся, просвіти́телю су́щих во тьмі неві́рія;","ра́дуйся, приведи́й люде́й твої́х с восто́ка да́льняго до за́пада.","Ра́дуйся, істо́чниче чуде́с, ізлива́ємих Бо́гом;","ра́дуйся, с любо́вію вразумля́яй заблу́ждших.","Ра́дуйся, ско́рий уті́шителю ка́ющихся о грісі́х свої́х;","ра́дуйся, путевождю́ гряду́щих путе́м пра́вим.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 5","ps":["Богодарова́нний світ яви́лся єси́, бу́ри всіх лю́тих разгоня́яй, су́щих на о́строві от ви́хрей смертоно́сних моли́твами твої́ми охраня́яй, святи́телю Іоа́нне, і кре́стним зна́менієм огражда́яй. Научи́ і нас, призива́ющих тя в по́мощ, чудотво́рче святи́й, к Бо́гу с дерзнове́нієм взива́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим мно́гую по́мощ твою́ в напа́стіх і обстоя́ніях, преблаже́нне о́тче Іоа́нне, дерзнове́нний бо хода́тай пред Престо́лом Бо́жиїм і ско́рий в біда́х помо́щник єси́. Того́ ра́ди і ми на твоє́ предста́тельство пред Бо́гом упова́єм і вопіє́м ті:","Ра́дуйся, стихі́й опа́сних прогони́телю;","ра́дуйся, моли́твою твоє́ю от нужд ізбавля́яй.","Ра́дуйся, а́лчущим хлі́ба при́сний пода́телю;","ра́дуйся, приуготовля́яй прося́щим ізоби́ліє.","Ра́дуйся, уті́шителю в ско́рбіх су́щих;","ра́дуйся, мно́гих па́дших от поги́белі ісхи́тивий.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 6","ps":["Пропові́дуя спасе́ніє, я́ко но́вий Мойсе́й гугни́вий, яви́лся єси́, ізводя́ лю́ди твоя́ із плі́на безбо́жних, преблаже́нне Іоа́нне. Ізба́ви і нас от рабо́ти гріхо́вния і враго́в неви́димих, да, ра́дующеся, вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́в пра́ведностію твоє́ю, соверши́л єси́ неісполни́моє, о до́брий па́стирю: преклони́л бо єси́ вла́сті мирськи́я сострада́ти о лю́діх твої́х. Того́ ра́ди с ни́ми ку́пно і ми благода́рственно вопіє́м ті:","Ра́дуйся, па́стирю до́брий, па́стві твоє́й, пресе́льником, ти́хоє приста́нище угото́вавий;","ра́дуйся, о ді́тіх і боля́щих найпа́че попече́ніє імі́вий.","Ра́дуйся, усе́рдно тя призива́ющим ві́рно помога́яй;","ра́дуйся, я́ко в немощні́м тілесі́ твоє́м си́ла Бо́жия незави́стно соверша́шеся.","Ра́дуйся, отрази́телю нападе́нія нечести́вих;","ра́дуйся, помрачи́телю лжі і прояви́телю і́стини.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 7","ps":["Хотя́ досто́йно просла́вити дре́вніх святи́х за́пада, отпа́дшаго от і́стини, возстанови́л єси́ почита́ніє їх в Це́ркві Правосла́вной, о люби́телю святи́х восто́ка і за́пада. Днесь с ни́ми на небесі́ моли́ о нас, пою́щих на землі́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго ви́дим тя ізбра́нника Бо́жия, і́же вку́пі со святи́телі дре́внія Га́ллії яви́лся єси́ в послі́дняя времена́, я́ко єди́н от сих, вдохновля́я па́ству твою́ соблюда́ти правосла́вную ві́ру, я́коже сі́ї на за́паді іспові́даху. Сохрани́ і нас во ві́рі сей пребива́ти, вопію́щих ті:","Ра́дуйся, но́вий Марти́не во воздержа́нії, по́двизіх і чудесі́х твої́х;","ра́дуйся, но́вий Ге́рмане во іспові́данії твоє́м правосла́вния ві́ри.","Ра́дуйся, но́вий Іла́ріє в боже́ственном богосло́вії;","ра́дуйся, но́вий Григо́ріє в почита́нії і прославле́нії уго́дников Бо́жиїх.","Ра́дуйся, но́вий Фа́всте і́ночеським усе́рдієм;","ра́дуйся, но́вий Кеса́ріє в тве́рдой любві́ ко пра́вилом Це́ркве Бо́жії.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 8","ps":["Стра́нноє виді́ніє предста́ ті: в землі́ но́вій встре́тил єси́ па́ству твою́ би́вшую, смуща́єму скорбми́ мно́гими, но я́ко ди́вний па́стир наста́вил єси́ ю поуче́нієм, терпі́нієм і пра́ведностію твоє́ю, і це́рков Бо́жия Ма́тере, я́же всіх скорб'я́щих Ра́дость єсть, воздви́гл єси́: ми же, удивля́ющеся терпі́нію і смире́нію твоєму́, благода́рно вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́ преда́в Христу́, бил єси́ ді́латель виногра́да Єго́, богоно́сне о́тче, не ві́дал бо єси́ поко́я до конця́ многострада́льнаго живота́ твоєго́. Помози́ і нам, недосто́йним, в ді́ланіїх на́ших і в на́шем приліжа́нії во ві́рности Христу́, да, сла́в'яще, вопіє́м ті:","Ра́дуйся, претерпі́вий до конця́ і дости́гший спасе́нія;","ра́дуйся, пред іко́ною Богома́тере умре́ти сподо́бивийся.","Ра́дуйся, посреді́ гоне́нія непра́веднаго му́жественний пра́вди храни́телю;","ра́дуйся, соверши́вий служе́ніє своє́ до конця́ і кончи́ну приє́мий сідя́, я́ко ієра́рх.","Ра́дуйся, по сме́рті уті́шивий па́ству чуде́сним свої́м возвраще́нієм;","ра́дуйся, мно́гих чуде́с пода́телю к ра́ці твоє́й с ві́рою і любо́вію притека́ющим.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє восхожде́нієм твоєя́ душі́ в небе́сния оби́телі возра́довася, ми же, удивля́ющеся твої́м чудесе́м на землі́, ді́йством Свята́го Ду́ха явля́ємим, воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не возмо́гуть ізобрази́ти по достоя́нію свя́тости житія́ твоєго́, о пра́ведні о́тче Іоа́нне, поне́же дом благода́ті неізрече́ннаго Бо́га бил єси́, ми же не мо́жем умолча́ти, чудеси́, явле́ну на́шему малові́рному ві́ку, див'я́щеся, і прославля́єм тя си́це:","Ра́дуйся, боже́ственних наставле́ній пала́то;","ра́дуйся, смире́нним ді́ланієм а́нгели сослужи́телі себі́ сотвори́вий.","Ра́дуйся, обріти́й ві́чноє і нерукотво́рноє жили́ще на небесі́х;","ра́дуйся, враче́бниці, в не́йже всяк неду́г от Бо́га врачу́ється.","Ра́дуйся, моли́твеннаго по́двига храни́лище;","ра́дуйся, освяще́нний хра́ме Ду́ха Свята́го.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, і́же всіх Спаси́тель, но́ваго свята́го посла́ нам і чрез него́ із те́мних глуби́н гріхо́вних воззва́ ни. Сли́шаще же єго́, нас призива́юща, ми, недосто́йнії, взива́єм к Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ всім прибега́ющим к твоєму́ небе́сному заступле́нію, о́тче Іоа́нне, ті́мже і нас от де́монських нападе́ній огражда́й, в біда́х і ну́ждах, стужа́ющих нам на землі́, помога́й, да с ві́рою тебі́ взива́єм:","Ра́дуйся, осле́пших прозрі́ніє;","ра́дуйся, си́лою моли́тви жизнь на сме́ртном о́дре су́щим подава́яй.","Ра́дуйся, богооткрове́нноє вразумле́ніє в см'яте́нії і сомне́ніїх су́щим;","ра́дуйся, спаси́тельная вла́го, ороша́ющая в зно́йной печа́лі погиба́ющих.","Ра́дуйся, си́рим і оста́вленним оте́чеськоє заступле́ніє;","ра́дуйся, святи́й учи́телю і́щущих і́стини.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 11","ps":["Пі́ніє непреста́нноє ко Пресвяті́й Тро́йце, преблаже́нне о́тче Іоа́нне, ми́слію, сло́вом і доброде́ланієм прине́сл єси́: мно́гим разумі́нієм і́стинния ві́ри Бо́жія повелі́нія уясни́л єси́, ві́рою, наде́ждою і любо́вію наставля́я нас в Тро́йці Єди́ному Бо́гу воспіва́ти: Аллилу́я."]},{"h":"Ікос 11","ps":["Светода́тельна світи́льника Правосла́вія су́щим во мра́ці неві́дінія зрим тя, ста́да Христо́ва до́брий па́стирю. Та́ко і по успе́нії твоє́м явля́єши і́стину не ві́дущим єя́, просвіща́я ду́ші ві́рних, вопію́щих ті такова́я:","Ра́дуйся, просвіще́ніє му́дростію Бо́жиєю су́щих в неві́рії;","ра́дуйся, ра́дуго ти́хия ра́дости кро́тких.","Ра́дуйся, гро́ме, устраша́яй во грісі́ упо́рствующих;","ра́дуйся, мо́лніє, є́ресі пожига́ющая.","Ра́дуйся, одожде́ніє догма́тов Правосла́вія;","ра́дуйся, ороше́ніє богоми́слія.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті от Бо́га, ві́дуще сію́ с благогові́нієм і благода́рностію приє́млем, к заступле́нію твоєму́ чу́дному притека́юще, о всехва́льне о́тче Іоа́нне, твоя́ же чудеса́ прославля́юще, взива́єм к Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще хвалу́ Бо́гу, небе́сний сонм святи́х ра́дується, я́ко не оста́ви Госпо́дь па́дший і безве́рний мир, но яви́л єсть всемогу́щую си́лу Свою́ на тебі́, кро́тком і смире́нном служи́телі, о блаже́нне о́тче Іоа́нне, і ми, со всі́ми святи́ми ра́дующеся, чтим тя си́це:","Ра́дуйся, но́вая звіздо́ пра́ведности, на небесі́ возсія́вшая;","ра́дуйся, но́вий проро́че, по́сланний пред коне́чним воцаре́нієм зла.","Ра́дуйся, я́коже Іо́на о возме́здії за гріхи́ предреки́й;","ра́дуйся, я́коже Крести́тель всіх к моли́тві і покая́нію призива́вий.","Ра́дуйся, я́коже Па́вел мно́го терпі́вий ра́ди Єва́нгелія і пропові́данія ві́ри;","ра́дуйся, апо́столе но́вий, свої́ми чудеси́ вселя́яй в нас благогові́йний тре́петь і ві́ру.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 13","ps":["О пресві́тлий і преди́вний уго́дниче Бо́жий, святи́телю о́тче наш Іоа́нне, утіше́ніє всім, в ско́рбіх су́щим, ни́нішнєє на́ше моли́твенноє прийми́ приноше́ніє, да моли́твами твої́ми от геє́нни о́гненния ізба́вимся і богоприя́тним твої́м хода́тайством сподо́бимся во ві́ки воспіва́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела о́бразом яви́ тебі́ в послі́дняя времена́ всея́ тва́рі Созда́тель, да с ми́лостію Бо́жиєю пече́шися о лю́діх земни́х. Взира́юще же на доброді́телі твоя́, преблаже́нне Іоа́нне, вопіє́м ті си́це:","Ра́дуйся, с ра́нняго ді́тства благоче́стієм украше́нний;","ра́дуйся, со стра́хом і тре́петом во́лю Бо́жию іспо́лнивий.","Ра́дуйся, яви́вий благода́ть Бо́жию в та́йних благодія́ніїх;","ра́дуйся, би́строє дале́че су́щих стра́ждущих усли́шаніє.","Ра́дуйся, любвеоби́льноє поспіше́ніє бли́жнім свої́м во спасе́ніє;","ра́дуйся, ра́дованіє всім с ві́рою к тебі́ припа́дающим.","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, всему́ ми́ру істоча́яй оби́льния струї́ духо́внаго наставле́нія і ди́вних чуде́с мно́жество, восхваля́єм тя с любо́вію і зове́м ті:","Ра́дуйся, святи́телю о́тче Іоа́нне, в біда́х ско́рий помо́щниче."]},{"h":"Молитва","ps":["О святи́телю о́тче наш Іоа́нне, па́стирю до́брий і тайнови́дче душ челові́чеських! Ни́ні у Престо́ла Бо́жия за нас мо́лишися, я́коже і сам посме́ртне ізре́кл єси́: «А́ще і умро́х, но жив єсьм». Умоли́ всеще́драго Бо́га проще́ніє нам во грісі́х дарова́ти, да бо́дренно воспря́нем, і Бо́гу возопіє́м о дарова́нії нам ду́ха смире́нія, стра́ха Бо́жия і благоче́стія во вся́чеських путеіх жи́зні на́шея, я́ко ми́лостивий сиропита́тель і іску́сний наста́вник на землі́ бив, ни́ні бу́ди нам путеводи́тель і в сму́тах церко́вних Христо́во вразумле́ніє. Усли́ши стена́ніє см'яте́нних ю́ношей на́шего лихолі́тія, обурева́ємих біснова́нієм вселука́вим, і при́зри на уни́ніє ізнемога́ющих па́стирей от утісне́нія тлетво́рнаго ду́ха ми́ра сего́ і том'я́щихся в нераді́нії пра́здном і ускори́ на моли́тву, сле́зно вопіє́м ті, о те́плий моли́твенниче; посіти́ нас си́рих, по всему́ лицю́ вселе́нния разсі́янних і во оте́чествії су́щих, во тьмі страсте́й блужда́ющих, но сла́бою любо́вію ко сві́ту Христо́ву влеку́щихся і жду́щих твоєго́ оте́чеськаго наставле́нія, да благоче́стію нави́кнем і наслі́дници Ца́рствія Небе́снаго яви́мся, іді́же ти пребива́єши со всі́ми святи́ми, сла́в'яще Го́спода на́шего Ісу́са Христа́, Єму́же честь і держа́ва, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О святи́телю чу́дне Іоа́нне, толи́ко распространи́л єси́ се́рдце своє́, я́ко неті́сно вміща́ється в нем мно́жество почита́ющих тя челові́к от разли́чних племе́н і наро́дов! При́зри на убо́жество слове́с на́ших, оба́че от любве́ тебі́ приноси́моє, і помози́ нам, уго́дниче Бо́жий, поне́ отни́ні очища́ти себе́ от вся́кия скве́рни пло́ті і ду́ха, рабо́тающе Го́сподеві со стра́хом і ра́дующеся Єму́ с тре́петом. І что возда́ми тебі́ за ра́дость о́ную, ю́же ощути́хом, зря́ще в хра́мі святі́м мо́щі твоя́ святи́я і прославля́юще па́м'ять твою́; воі́стину, не і́мами, чим возда́ти, то́чію а́ще на́чнем себі́ ісправля́ти, бива́юще но́ві вмі́сто ве́тхих. Сея́ благода́ті обновле́нія бу́ди нам хода́тай, свя́те Іоа́нне, помози́ нам в не́мощіх, ісціли́ болі́зні, уврачу́й стра́сті моли́твами твої́ми; преста́вленний же от сего́ вре́меннаго во іно́є житі́є ві́чноє, в не́же наста́ви тя Пречи́стая Влади́чиця, Одиги́трія разсі́янія ру́ськаго, чудотво́рною Своє́ю іко́ною Коренно́ю-Ку́рською, Єя́же спу́тник ти яви́лся єси́ в день преставле́нія своєго́, ра́дуєшися ни́ні в ли́ці святи́х, сла́в'ящих Єди́наго в Тро́йці сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["Попече́ніє твоє́ о па́стві в стра́нствії єя́, / се проо́браз і моли́тв твої́х, за мир весь при́сно возноси́мих. / Та́ко ві́руєм, позна́вше любо́в твою́, / святи́телю і чудотво́рче Іоа́нне! / Весь от Бо́га освяще́н священноді́йствієм пречи́стих Та́їн, / ї́миже сам при́сно укріпля́єм, поспіша́л єси́ ко стра́ждущим, ціли́телю отра́днійшій. // Поспіши́ і ни́ні в по́мощ нам всім се́рдцем чту́щим тя."]},{"h":"Кондак, глас 4","ps":["Се́рдце твоє́ обє́млеть всіх любо́вію / моля́щих ті ся, Іоа́нне святи́телю, / і помина́ющих по́двиг житія́ твоєго́. / Безболі́зненно же ле́гкоє преставле́ніє твоє́ бисть, // Одиги́трії Пречи́стия ві́рний служи́телю."]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче наш Іоа́нне, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Нилу Селігерському, Столобенському чудотворцю","e":"Akathist to our Venerable Father Nilus of Stolobny, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нному от пеле́н во во́їнство Христо́во і вписанному от ю́ности в кни́гу живота́ ві́чнаго, ди́вному в чудесі́х, преподо́бному отцю́ на́шему Ни́лу, всі, насища́ющіїся чрез него́ подава́ємих неоску́дно Бо́жиїх дарова́ній, соше́дшеся воспоє́м єму́, я́ко хода́таю і моли́твеннику о душа́х на́ших, во весе́лії глаго́люще:","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгела Госпо́дь Своєго́ посла́ к тебі́, преподо́бне о́тче, возвісти́ти, єгда́ узрі́ твоє́ мудрова́ніє о небе́сних, даби́ преше́л єси́ із пре́жнія пусти́ні во о́ную, в не́йже подвиза́лся єси́; ти же ні мі́ста, ні страни́ о́ния ві́дая, но па́че на Посла́вшаго тя Го́спода упова́я і ві́руя, я́ко пернатий поте́кл єси́ в ню. Ми же, ча́да твоя́, а́ки на путі́ тя сріта́юще, приветствуєм, си́це возглаша́юще:","Ра́дуйся, послуша́нія нам о́браз оста́вивий;","Ра́дуйся, любве́ ра́ди Христо́ви вся кра́сная ми́ра сего́ за уме́ти вміни́вий.","Ра́дуйся, Мелхиседеку подо́бен яви́вийся;","Ра́дуйся, я́ко ти роди́телей земни́х утаї́л єси́ от нас, да Небе́сному Отцю́ в синовство́ причтешися.","Ра́дуйся, я́ко за лише́ніє сро́дства і дру́жества стяжа́л єси́ с небе́сними содру́жество;","Ра́дуйся, преподо́бне, возненави́дівий ми́ра сего́ вся́коє наслажде́ніє.","Ра́дуйся, я́ко за сіє́ восприя́л єси́ небе́сния жи́зні учрежде́ніє;","Ра́дуйся, преподо́бне, послужи́вий Го́споду преподо́бієм і пра́вдою.","Ра́дуйся, за сіє́ от Него́ почте́нний че́стію і сла́вою ві́чною;","Ра́дуйся, в по́двизіх дневни́х і ночних тече́ніє жи́зні вре́менния соверши́вий.","Ра́дуйся, в невече́рнім дні Ца́рствія Бо́жия при́сно пребива́яй;","Ра́дуйся, тіх благи́х, ї́хже о́ко не ви́ді і у́хо не сли́ша, ві́чний наслі́дниче.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дів пока́занноє ті Бо́гом мі́сто, преподо́бне о́тче Ни́ле, возра́довался єси́ о красоті́ єго́; от ра́дости же, я́ко не презрі́ Госпо́дь Бог трудо́в твої́х, сія́ благода́рним гла́сом восклицял єси́: О Тро́йце Пресвята́я, єди́на в Божестві́ в тріє́х Ли́цях неразді́льная, Бо́же О́тче Всемогу́щий, Бо́же Си́не Єдиноро́дний, Бо́же Душе́ Уті́шителю, світоза́рний ми́ру сві́те, наста́вниче і промисли́телю всіх спасе́нія, да́руй мні до конця́ жи́зні моєя́ на сем мі́сті ви́ну воспіва́ти Тебі́ піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум весь углубле́н імі́я, преподо́бне о́тче, в поуче́нії о блаже́нній ві́чності і в ню водвори́тися жела́я, непреста́нно со Дави́дом вопи́л єси́: уви́ мні, я́ко прише́льствіє моє́ продолжи́ся, би́ша бо сле́зи моя́ мні, я́ко хліб, день і ноч. Ми же таково́му мудрова́нію твоєму́ див'я́щеся, вопіє́м:","Ра́дуйся, преподо́бне, земно́є мудрова́ніє Боже́ственній во́лі повину́вий;","Ра́дуйся, жела́ніє твоє́ ко Влади́ці, Христу́ Го́споду, вся́чеськи утвержде́ніє імі́вий.","Ра́дуйся, крила́ми Богоми́слія сі́ті вра́жія сокруши́вий;","Ра́дуйся, вся єго́ зло́бная на тя умишле́нія до конця́ посрами́вий.","Ра́дуйся, оста́вивий привре́менния імі́нія і возлюби́вий нищету́ Христо́ву;","Ра́дуйся, я́ко ни́ні за сіє́ дости́гл єси́ к ві́чному і неістощи́мому Єго́ бога́тству.","Ра́дуйся, во умерщвле́нії страсте́й да́же до конця́ жи́зні твоєя́ неуси́пно бодрствовавий;","Ра́дуйся, сме́ртію вре́менною к ві́чному безсме́ртію преше́дий.","Ра́дуйся, за глубо́коє смире́ніє во ві́чния крони вознесе́нний;","Ра́дуйся, в непристу́пній сла́ві получи́вий прича́стіє.","Ра́дуйся, вся́кия доброді́телі себі́ самаго́ о́браз нам яви́вий;","Ра́дуйся, я́ко за сіє́ ни́ні во Ца́рствії Небе́снім ве́лій нарече́н єси́.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 3","ps":["Си́льна і непреоборима тебі́ показа́л єси́, преподо́бне о́тче, дре́внему врагу́ і завистнику блаже́нства на́шего: єгда́ бо зря тебе́ он, я́ко день от дне лі́ствицю доброді́телей к небесі́ нези́блему утвержда́єши, і челові́к пло́тян, но я́ко а́нгел безпло́тний житіє́ прохо́диши, уми́сли от благослове́ннаго ті Бо́гом мі́ста отдалити, разли́чними привиді́нії устраша́ше тя; ти же вся єго́ кова́рства, а́ки паучинния сі́ті, бо́дренною моли́твою разгна́л єси́, я́ко не смі́ти єму́ і іздале́ча на тя взира́ти, єгда́ сли́ша тя пою́ща: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я несумні́нную наде́жду о спасе́нії твоє́м, преподо́бне о́тче Ни́ле, ко ісхо́ду от жи́зні сея́ всегда́ гото́в бил єси́, і ви́ну імі́я в па́м'яті смерть, пре́жде о́ния многотру́дному своєму́ ті́лу мі́сто свої́ма рука́ма ізготовил єси́. Ми же, ча́да твоя́, а́ки надгро́бную піснь поє́м ті, си́це глаго́люще:","Ра́дуйся, труди́ твоя́ і по́двиги і́ночеськия ізміни́вий ві́чним упокоє́нієм;","Ра́дуйся, страсте́й мглу істребивий.","Ра́дуйся, облече́нний ни́ні в ри́зу безстра́стія;","Ра́дуйся, а́нгельськи на землі́ житіє́ пожи́вий.","Ра́дуйся, ко гра́ду нетлі́ннаго Еде́ма преше́дий;","Ра́дуйся, предстоя́нія у стра́шнаго Престо́ла Влади́чня сподо́бивийся во сла́ві ві́чній.","Ра́дуйся, усе́рдно возлюби́вий за́повіді Христа́ Го́спода;","Ра́дуйся, я́ко друг че́стен і сам от Него́ возлю́блен єси́.","Ра́дуйся, мно́гі ско́рбі с вели́ким благодаре́нієм претерпі́вий;","Ра́дуйся, в неізглаго́ланную ра́дость Го́спода своєго́ восприятий.","Ра́дуйся, я́ко дарова́ся тебі́ от Бо́га во благослове́ніїх прославля́єму би́ти;","Ра́дуйся, я́ко сла́ва твоя́ от челові́к всегда́ ублажа́ється.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рею помишле́ній неві́рних о тебі́, преподо́бне о́тче, неістовії челові́ци см'ято́шася, мня́ще, а́ки би не ра́ди любве́ Христо́ви толь жесто́кий пусти́нний путь проходи́л єси́, но вину́ уєдине́ннаго житія́ твоєго́ непщева́ху би́ти стяжа́ніє імі́нія, чесо́ ра́ди і окра́сти тя уми́слиша; но вмі́сто ча́ємаго сокро́вища обріто́ша єди́н о́браз Пречи́стия Богома́тере с Предві́чним Младе́нцем, на ру́ку Єя́ держи́мим, Господом Ісу́сом, к Нему́же ти денно і но́щно воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шим і ві́руєм, преподо́бне о́тче Ни́ле, я́ко Бог тебі́, лю́б'ящему Єго́, да́рствуєть толи́кая воздая́нія, ї́хже о́ко не ви́ді і у́хо не сли́ша, і я́же на се́рдці челові́ку не взидо́ша. Жела́юще же і ми твої́ми богоприя́тними моли́твами та́яжде получи́ти, вопіє́м ті:","Ра́дуйся, жела́нія твоєго́ соверше́нноє получи́вий ісполне́ніє;","Ра́дуйся, на є́же ві́рою взира́л єси́, ни́ні лицом к лицю́ непристу́пнаго Божества́ сла́ву созерца́єши.","Ра́дуйся, я́ко отту́ду неізрече́нния ра́дости і весе́лія почерпа́єши ісполне́ніє;","Ра́дуйся, я́ко ктому́ не приключи́ться что тебі́ жела́ти і хоті́ти во ві́ки.","Ра́дуйся, я́ко ктому́ не прирази́ться к душе́ твоє́й прило́г вра́жиїх наві́тов і іскуше́ній;","Ра́дуйся, я́ко кора́бль твой упра́вил єси́ на мі́сто воі́стину до́броє.","Ра́дуйся, я́ко стал єси́ їм, а́ки на гора́х Арара́тських, на са́мих гора́х небе́сних;","Ра́дуйся, я́ко ктому́ уже́ он не бої́ться потопле́нія.","Ра́дуйся, я́ко ум твой укріпле́н єсть во ві́ки благода́тним укріпле́нієм;","Ра́дуйся, я́ко обогати́лся єси́ преізоби́льно дара́ми Боже́ственними.","Ра́дуйся, я́ко до возглаше́нія арха́нгельських труб і́маши душе́вноє Боговиді́ніє;","Ра́дуйся, я́ко єгда́ по возглаше́нію їх ме́ртвії от гробо́во воскре́снуть, і ти воста́неши с ті́лом сим к лицезренію Бо́жию.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная я́ко звізда́ яви́лся єси́, преподо́бне, во о́строві Селиге́ра єзе́ра; і́бо вся окре́стная страни́ да́нною ті от Со́лнця пра́вди, Христа́ Бо́га, благода́тію озаря́єши, і на мо́рі стра́стнаго сего́ житія́ обурева́ємих наставля́єши посо́бієм моли́тв твої́х на путь спасе́нія, к небе́сному оте́честву веду́щ, і науча́єши єди́німи усти́ і єди́нім се́рдцем с тобо́ю воспіва́ти в Тро́йці сла́вимому Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діл єси́, преподо́бне, я́ко в ми́рі сем вся́чеськая суть суєта́ і вся тлі́нію прича́стна: прехо́дить бо мир і по́хоть єго́; уразумі́л же єси́, я́ко творя́ і во́лю Бо́жию, то́ю єди́н пребива́єть во ві́ки; сего́ ра́ди, бі́гая ми́ра і сро́дник твої́х, вседу́шно потща́лся єси́ благоугоди́ти преві́чному Бо́гу. Ті́мже за толи́коє твоє́ усе́рдіє усли́ши нас, при́сно глаго́лющих тебі́ сицева́я:","Ра́дуйся, о́рле небопа́рний, крила́ми Богоми́слія возлеті́вий зрі́ти немерца́ющую сві́тлость Со́лнця пра́вди, Ісу́са Христа́;","Ра́дуйся, у́ме чисті́йший, не оскверни́вийся пре́лестьми мирськи́ми.","Ра́дуйся, кри́не чи́стаго обоня́нія;","Ра́дуйся, по́стников воздержа́ніє.","Ра́дуйся, благоче́стія сто́лпе непобори́мий;","Ра́дуйся, честно́є духо́вноє сокро́вище.","Ра́дуйся, сві́тлоє доброді́телей прия́телище;","Ра́дуйся, дража́йший сосу́де благода́тнаго сокрове́нія.","Ра́дуйся, скорб'я́щих ра́досте і утіше́ніє;","Ра́дуйся, путеше́ствующих путеводи́телю.","Ра́дуйся, безме́здний врачу́ болі́зней вся́ких;","Ра́дуйся, ско́рий засту́пниче оби́димих.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дуєть са́моє мі́сто пусти́нноє, преподо́бне о́тче Ни́ле, на не́мже до конця́ жи́зні твоєя́ подвиза́лся єси́, какови́ бя́ху твої́ труди, по́двизі і терпі́ніє, я́ко во всю жизнь твою́ не імі́л єси́ ні кого́же соскорб'я́щаго і утіша́ющаго тя в терпі́нії, но па́че отвсю́ду належаху ті озлобле́нія, воздвиза́ємая от врага́ неви́димаго; не терп'я́ бо завистник богоуго́днаго житія́ твоєго́ зрі́ти, ні́когда наусти подо́бних себі́ келію твою́ сожещи́ і с тобо́ю, но ти, я́коже на него́ самаго́, та́ко і на вся єго́ злоко́зненния сі́ті, імі́л єси́ поражающ ка́мик, я́ко Дави́д на Голія́фа, непреста́нную ко Го́споду Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ всему́ ми́ру доброді́телей твої́х просвіще́ніє, преподо́бне о́тче, о ни́хже благодаря́ще, прославля́єм Отця́ Небе́снаго, да́вшаго ті толи́кую благода́ть вели́чія Своєго́, і тебі́, я́ко те́плому о нас моли́твеннику, ра́достная воспіва́єм си́це:","Ра́дуйся, усе́рдний ісполни́телю Бо́жиїх велі́ній;","Ра́дуйся, терпі́нієм твої́м удиви́вий а́нгелов і челові́ков.","Ра́дуйся, притекающим под кров твой сла́дкоє упокоє́ніє;","Ра́дуйся, ізнемога́ющим от трудо́во возстановле́ніє.","Ра́дуйся, істо́чниче чуде́с оби́льний;","Ра́дуйся, во вся́ких ну́ждах призива́ющим тя ско́рий помо́щниче.","Ра́дуйся, надеющимся на тя защище́ніє непости́дноє;","Ра́дуйся, всім притекающим к тебі́ приста́нище небу́рноє.","Ра́дуйся, хотя́щим твоєму́ непоро́чному житію́ послі́довати укріпи́телю;","Ра́дуйся, сві́щниче, горя́й сві́том благоче́стія.","Ра́дуйся, путевождю во тьмі неві́рія блудящим;","Ра́дуйся, пода́телю ра́зума бу́їїм.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́, преподо́бне, от зді́шняго ві́ка преста́витися преле́стнаго, на всяк день ісходя́ слезил і рида́л єси́ над гробо́м твої́м, не а́ки боя́ся сме́рті, я́же такови́м уго́дником Бо́жиїм, я́ко ти єси́, єди́ним єсть прохожденієм от трудо́в на упокоє́ніє, от скорбе́й і болі́зней на ві́чную ра́дость і весе́ліє; но па́че жела́я разріши́тися от юз плотськи́х і предста́ти Престо́лу Бо́га Вседержи́теля со Арха́нгели і А́нгели, і вку́пі с ни́ми торже́ственно воспіва́ти піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ва вся яви́шася тебі́, преподо́бне, єгда́ разлучи́лся єси́ повелі́нієм Госпо́днім от привре́менних: не́бо но́во, земля́ но́ва і град Ієрусали́м нов предуготован от Бо́га, я́ко неві́ста укра́шенная му́жу своєму́, в него́же с неізрече́нним весе́лієм восприялся єси́ в сожи́тіє ві́чноє А́нгелом і всім святи́м. Ми же, о такові́м твоє́м преселе́нії веселя́щеся, уми́льно глаго́лем си́це:","Ра́дуйся, єди́наго Бо́га в тріє́х Ли́цях сподо́бивийся лицезрі́нія;","Ра́дуйся, в число́ прия́тий і́стинних Єго́ поклонников.","Ра́дуйся, я́ко не ктому́ с земни́ми, но і с небе́сними си́лами на Престо́лі непристу́пния сла́ви Сідя́щему поє́ши: Свят, Свят, Свят Госпо́дь Савао́ф;","Ра́дуйся, я́ко от Него́ почерпа́єши преізоби́льная благода́ті ісполне́ніє.","Ра́дуйся, і на землі́ Бо́гом собра́ннаго твоєго́ стада́ бо́дрий храни́телю;","Ра́дуйся, всім подражающим житію́ твоєму́ свято́му наста́вниче.","Ра́дуйся, я́ко укріпля́єши посліду́ющих ті к мужественному со враго́м боре́нію;","Ра́дуйся, я́ко хода́тайствуєши їм вінці́, досто́йния трудо́в і по́двигов, от Христа́ Бо́га.","Ра́дуйся, наде́ждо їм ізві́стная, я́ко не всу́є тещи́ і ні вотще́ труди́тися їм подоба́єть;","Ра́дуйся, я́ко і в тече́нії слу́жиши їм прохла́дою і утіше́нієм.","Ра́дуйся, я́ко сам пра́ви стезі́ Госпо́дні соді́лал єси́;","Ра́дуйся, я́ко і всіх ті́миже стезя́ми ше́ствовати науча́єши.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє сли́шаніє во у́шію на́шею обно́ситься о тебі́, преподо́бне о́тче Ни́ле: се бо толи́к дар імі́л єси́ во пло́ті от Бо́га, я́ко є́же і вта́йні соді́янноє от челові́к разумі́л єси́, і окаля́нна гріхо́вною нечистото́ю а́біє обличи́л єси́, поуча́я не твори́ти того́ бо́ліє. Ми же, сицево́му твоєму́ прозрі́нію див'я́щеся, прославля́єм Бо́га, прославляющего такови́я ві́рния Своя́ раби́, і вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́, єли́ко мо́щно, повину́л єси́ во́лі Бо́жієй, преподо́бне о́тче; ті́мже і от Бо́га вся єли́ка жела́л, восприя́л єси́, от нас же, я́ко оте́ць і наста́вник наш, усли́ши і прийми́ похва́льноє сіє́ пі́ніє:","Ра́дуйся, преподо́бне, я́ко душа́ твоя́ свята́я по жела́нію твоєму́ ни́ні в небе́сних ски́ніях обріта́ється;","Ра́дуйся, я́ко во мзду приє́млеть упокоє́ніє і отра́ду.","Ра́дуйся, я́ко во страні́ о́наго весе́лія неізрече́нную сла́дость вкуша́єши;","Ра́дуйся, я́ко той сла́дости челові́ку сме́ртному не літь єсть і глаго́лати.","Ра́дуйся, я́ко тоя́ добро́ти і бла́гости о́ко челові́чо не ви́ді і у́хо не сли́ша;","Ра́дуйся, я́ко с преізобилієм па́че жела́нія і хоті́нія получи́л єси́ утіше́нія.","Ра́дуйся, ті́хже благи́х і нам хода́таю при́сний;","Ра́дуйся, от твої́х благода́тних даро́в і нам пода́телю незави́стний.","Ра́дуйся, я́ко промишля́єши о на́шем спасе́нії;","Ра́дуйся, я́ко ти пече́шися о доброді́тельнім на́шем соверше́нії.","Ра́дуйся, я́ко тобо́ю ум наш в Богоми́слії науча́ється;","Ра́дуйся, я́ко тобо́ю мрак неві́дінія прогоня́ється.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́ко сло́во к похвале́нію ангелоподо́бнаго житія́ твоєго́ недово́льно зрим би́ти, преподо́бне о́тче: ка́ко бо мо́жем того́ по достоя́нію ублажи́ти, єго́же Сам Бог ди́вно прославля́єть? Ті́ло бо єго́, на землі́ тлі́нію неприча́стноє, чуде́с ріки́ істоча́єть, вся́кия ціли́ть болі́зні і бі́си прогоня́єть, душа́ же єго́ свята́я с два́десять чети́рми ста́рці поє́ть ві́чно в небесі́ Сідя́щему на Престо́лі: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й краснословесних не мо́жеть би́ти та́ко дійстви́тельно, є́же би возбуди́ти какова́го грі́шника к покая́нію, я́коже твоє́ си́льно і ді́йственно бисть, преподо́бне, єди́но ма́ніє: єгда́ бо узрі́л єси́ гряду́ща к тебі́ челові́ка, углі́бнувша в плотськи́х нечистота́х, а́біє затвори́л єси́ от него́ око́нце келії твоєя́, не а́ки гнуша́яся грі́шника, но явля́я, коль мерзи́ть Ду́ху Свято́му душа́, пови́нная гріху́; то́йже умили́вся пока́яся і обіща́ся ктому́ ду́шу і ті́ло чи́сто соблюда́ти. Ми же, ра́дующеся, я́ко імі́єм тя о покая́нії на́шем усе́рднаго промисли́теля, взива́єм ті такова́я:","Ра́дуйся, наш і́стинний наста́вниче;","Ра́дуйся, я́ко чесо́му учи́л єси́, та і сам нелі́ностно твори́л єси́.","Ра́дуйся, я́ко за сіє́ ве́лій во Ца́рствії Небе́сном нарече́н єси́;","Ра́дуйся, я́ко удостоєн єси́ вни́ти в число́ ді́вствующих і посліду́ющих А́гнцю на горі́ Сіо́нстій.","Ра́дуйся, сто́лпе благоче́стія і утвержде́ніє;","Ра́дуйся, тве́рдоє правосла́вія пра́вило.","Ра́дуйся, вся за́повіді Госпо́дні соверше́нно сохрани́вий;","Ра́дуйся, Христа́ ра́ди вся оста́вивий і вся в Нем обріти́й.","Ра́дуйся, я́ко по́льзою твої́х діл, а́ки пресладкими плоди́, ві́рних душі́ пита́єши;","Ра́дуйся, я́ко в мі́ру доброді́телей твої́х теку́щих наставлявши.","Ра́дуйся, житію́ нестяжательному Христа́ ра́ди научи́вийся;","Ра́дуйся, за́повідь Христо́ву: “Не мо́жете рабо́тати Бо́гу і мамонне”, до́брі іспо́лнивий.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, преподо́бне, вся́чеськи о тілесі́ небре́гл єси́: не імі́яше бо о́но у тебе́ во всю жизнь твою́ упокоє́нія ні сіді́нієм, ні на землі́ лежа́нієм; но вмі́сто упокоє́нія бя́ху тіле́сную сла́бость поддерживающе жезли́, і та́ко путь многоско́рбнаго житія́ сего́ соверши́л єси́; чесо́ ра́ди ті́ло твоє́ оста́вил єси́ нам нетлі́нно і многочуде́сно в подража́ніє твої́х по́двигов, душе́ю же предста́л єси́ Престо́лу Влади́чню, с ли́ки Святи́х воспіва́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ яви́лся єси́, преподо́бне о́тче Ни́ле, во іскуше́ніїх вра́жиїх нас утвержда́ющая; я́коже бо дре́вле ізра́їльтяном повелі́ Бог вознести́ змію́ в пусти́ні на дре́во, да уязвеннії от зміє́в, на ню взира́юще, ісціля́ються; та́ко і ти предложи́л єси́ себе́ нам, да єгда́ кото́рий брат по наві́ту вра́жию каково́ю-ли́бо стра́стію побіжде́н бу́деть, а́біє взира́л би на твоє́ чудеси́ обогащенноє ті́ло і ісцелевался: і́бо і ти такову́ю же плоть і ті́мже страсте́м подлежащую імі́л єси́, я́коже і ми, но благода́тію Бо́жиєю побіди́тель всіх страсте́й яви́лся єси́. Сего́ ра́ди торжеству́юще па́м'ять твою́, воспіва́єм си́це:","Ра́дуйся, преподо́бне, дре́вняго врага́ человікоуби́йцю дия́вола со всі́ми єго́ хитростьми́ посрами́вий;","Ра́дуйся, во всю жизнь твою́ малі́йшаго угожде́нія пло́ті не яви́вий.","Ра́дуйся, ні каковияже дру́жби с ми́ром не імі́вий;","Ра́дуйся, пресла́вную над о́ним побі́ду одержа́вий.","Ра́дуйся, возду́шная мита́рства кня́зя тьми безбі́дно проше́дий;","Ра́дуйся, ла́янія ми́сленних псов не сли́шавий.","Ра́дуйся, я́ко супоста́ть наш дия́вол не обрі́те, что на тя клевета́ти;","Ра́дуйся, я́ко вся єго́ си́ла на воздусіх прише́ствієм твої́м посрами́ся і уничижи́ся.","Ра́дуйся, я́ко восходя́ща тя в небе́сноє оте́чество сріто́ша небе́снії А́нгели і Арха́нгели;","Ра́дуйся, я́ко узрі́вше тя всі Святі́ї возра́довашася.","Ра́дуйся, я́ко сподо́бился єси́ усли́шати прелюбе́зний сей глаго́л: “Прийди́, си́не благослове́нний, наслі́дуй угото́ванноє ті Ца́рство”;","Ра́дуйся, сего́ вожделі́ннаго жре́бія і нам при́сний хода́таю.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє всеприятноє приноси́л єси́ Бо́гу, преподо́бне о́тче Ни́ле, па́че жертв і всесожже́ній, от се́рдця сокруше́нна і смире́нна, пла́менем любве́ воспаряющеє в моли́тві, я́же ви́ну восхожда́ше во у́ші Го́спода Савао́фа, я́ко і тебі́ самаго́ си́льна яви́ся вознести́ на не́бо і поста́вити пред Престо́лом Сла́ви Єго́, іді́же ві́чно воспіва́єши Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́та безвино́внаго прича́стієм наслади́вийся, преподо́бне о́тче Ни́ле, світи́льник ми́сленний яви́лся єси́ нам, блудящим во гріхо́вній тьмі, наставля́яй пра́вими стезя́ми ше́ствовати ко сві́ту самобитному, Христу́ Бо́гу на́шему. Ми же, єли́ко мо́щно, ше́ствующе по тебі́, я́ко предводители і руководце на́шем, благода́рственная восклиця́єм си́це:","Ра́дуйся, церко́вний неугаси́мий світи́льниче;","Ра́дуйся, ко сві́ту Бо́гу Отцю́ в синовство́ причте́нний.","Ра́дуйся, ко сві́ту Бо́гу Си́ну бра́тство благода́тію Єго́ стяжа́вий;","Ра́дуйся, от сві́та Бо́га Ду́ха Свята́го восприя́вий обруче́ніє живота́ ві́чнаго.","Ра́дуйся, я́ко вся, єли́ка хо́щеши, от о́наго триіпоста́снаго сві́та заімствуєши;","Ра́дуйся, я́ко і нас благода́тним сві́том просвіща́єши.","Ра́дуйся, я́ко ра́ди твої́х за нас пред Престо́лом Бо́жиїм моли́тв, і ми при ісхо́ді от жи́зні сея́ наді́ємся ізбіжа́ти зрі́нія мра́чнаго лиця́ де́монськаго;","Ра́дуйся, я́ко при твоє́м світі́нії і ми безбі́дно прийти́ упова́єм до гори́ небе́сния.","Ра́дуйся, я́ко тебі́, нас руководствующа, устраши́ться князь тьми, не терп'я́ зрі́ти сві́тлости лиця́ твоєго́;","Ра́дуйся, я́ко от сві́та твоєго́ вся просте́ртия на нас сі́ті єго́, а́ки паучи́на, ісче́знуть.","Ра́дуйся, я́ко ми, тобо́ю руководи́ми, наді́ємся прийти́ ко о́ному незаходи́мому сві́ту, Христу́ Го́споду;","Ра́дуйся, я́ко тобо́ю наставля́ємі, і ми ві́руєм би́ти прича́стници сла́ви Єго́.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть не преста́й ізлива́ти, преподо́бне о́тче Ни́ле, на мі́сто, іді́же по́стничеськаго житія́ твоєго́ тече́ніє соверши́л єси́, і іді́же пре́жде кончи́ни твоєя́ возвісти́л єси́ ду́хом проро́чеським би́ти іночествующим вселе́нію: се бо, по предрече́нію твоєму́, ми зді всели́хомся, зді і поко́й наш. Ти же, я́ко оте́ць і наста́вник, укрепляй ни і помога́й нам до конця́ жи́зні на́шея душеспаси́тельную піснь воспіва́ти Го́споду Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ і́ночеськия по́двиги, ублажа́єм бді́нія, непреста́нния моли́тви, пост, смире́ніє і терпі́ніє, преподо́бне о́тче Ни́ле; но оба́че ві́ми, я́ко, а́ще би і тмочисле́нними устна́ми могли́ тя ублажи́ти, ні коєже сло́во дово́льно бу́деть на похвалу́ твої́х пресла́вних доброді́телей. То́йже бо Єди́н си́лен тя по достоя́нію просла́вити і ублажи́ти, І́же глаго́леть: “Прославляющия М'я просла́влю”. І ни́ні у́бо, я́ко торжественний побіди́тель враго́в спасе́нія, прославляйся і сіди́ на Престо́лі с двоюнадесятьми ста́рці, от нас же чад твої́х, а́ще і ма́лоє, оба́че прийми́ приноше́ніє сіє́:","Ра́дуйся, готовнейший защи́тниче во обидах су́щим;","Ра́дуйся, крі́пкий щиті́ от льсти́ваго і клеветливаго язи́ка.","Ра́дуйся, отвратителю от грі́шников пра́веднаго гні́ва Бо́жия;","Ра́дуйся, ка́ющихся грі́шников ско́рий пред Бо́гом засту́пниче.","Ра́дуйся, в послі́дней біді́ сме́ртной па́че наде́жди помо́щниче;","Ра́дуйся, до́брий па́стирю ове́ць Христо́вих.","Ра́дуйся, я́ко моли́твами твої́ми восп'яща́єши дре́внему человікоуби́йці дия́волу в козніх єго́ проти́ву рабо́в Бо́жиїх;","Ра́дуйся, я́ко, ї́хже он мни́ться імі́ти во своє́й вла́сті, і тіх історгаєши.","Ра́дуйся, я́ко посо́бієм твої́х моли́тв безнадежнії і отча́яннії надежни бива́ють;","Ра́дуйся, я́ко тебі́, їх руководствующу, і они́ Ца́рствіє Небе́сноє улучи́ти ча́ють.","Ра́дуйся, я́ко тебі́, їх защища́ющу, вра́жия стрі́ли тіх не уязвля́ють;","Ра́дуйся, я́ко при твоє́й по́мощі они́ са́мі врага́ устраша́ють.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 13","ps":["О вели́кий уго́дниче Христо́в, преподо́бне о́тче Ни́ле! Во мно́гих потре́бних нам недостаточни єсьми́, оба́че мно́гая і ну́ждная оста́вивше, о єди́нім тебі́ ни́ні мо́лим і про́сим: хода́тайствуй і моли́ о нас Го́спода на́шего Бо́га, да в день всеми́рнаго суда́ сподо́бит ни десна́го стоя́нія і сопричте́ть ли́ку торжеству́ющих воспіва́ти ві́чно Єму́ піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела Госпо́дь Своєго́ посла́ к тебі́, преподо́бне о́тче, возвісти́ти, єгда́ узрі́ твоє́ мудрова́ніє о небе́сних, даби́ преше́л єси́ із пре́жнія пусти́ні во о́ную, в не́йже подвиза́лся єси́; ти же ні мі́ста, ні страни́ о́ния ві́дая, но па́че на Посла́вшаго тя Го́спода упова́я і ві́руя, я́ко пернатий поте́кл єси́ в ню. Ми же, ча́да твоя́, а́ки на путі́ тя сріта́юще, приветствуєм, си́це возглаша́юще:","Ра́дуйся, послуша́нія нам о́браз оста́вивий;","Ра́дуйся, любве́ ра́ди Христо́ви вся кра́сная ми́ра сего́ за уме́ти вміни́вий.","Ра́дуйся, Мелхиседеку подо́бен яви́вийся;","Ра́дуйся, я́ко ти роди́телей земни́х утаї́л єси́ от нас, да Небе́сному Отцю́ в синовство́ причтешися.","Ра́дуйся, я́ко за лише́ніє сро́дства і дру́жества стяжа́л єси́ с небе́сними содру́жество;","Ра́дуйся, преподо́бне, возненави́дівий ми́ра сего́ вся́коє наслажде́ніє.","Ра́дуйся, я́ко за сіє́ восприя́л єси́ небе́сния жи́зні учрежде́ніє;","Ра́дуйся, преподо́бне, послужи́вий Го́споду преподо́бієм і пра́вдою.","Ра́дуйся, за сіє́ от Него́ почте́нний че́стію і сла́вою ві́чною;","Ра́дуйся, в по́двизіх дневни́х і ночних тече́ніє жи́зні вре́менния соверши́вий.","Ра́дуйся, в невече́рнім дні Ца́рствія Бо́жия при́сно пребива́яй;","Ра́дуйся, тіх благи́х, ї́хже о́ко не ви́ді і у́хо не сли́ша, ві́чний наслі́дниче.","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нному от пеле́н во во́їнство Христо́во і вписанному от ю́ности в кни́гу живота́ ві́чнаго, ди́вному в чудесі́х, преподо́бному отцю́ на́шему Ни́лу, всі, насища́ющіїся чрез него́ подава́ємих неоску́дно Бо́жиїх дарова́ній, соше́дшеся воспоє́м єму́, я́ко хода́таю і моли́твеннику о душа́х на́ших, во весе́лії глаго́люще:","Ра́дуйся, преподо́бне о́тче Ни́ле, Столобенський чудотво́рче."]},{"h":"Молитва","ps":["О вели́кий уго́дниче, пресла́вний чудотво́рче, собра́нного зді о тебі́ ста́да Христо́ва бо́дрий па́стирю і оби́телі сея́ Бо́гом да́нний нача́льниче, Ни́ле всеблаже́нне! Душе́ю на Небесі́ Престо́лу Бо́жию предстоя́й і Тро́їчния сла́ви наслажда́яйся, ті́лом же на землі́ в Боже́ственном хра́мі сем почива́яй і от него́ да́нною ті сви́ше благода́тію разли́чная істоча́яй чудеса́, при́зри ми́лостивим о́ком на предстоя́щия честні́й твоє́й ра́ці лю́ди і прося́щия си́льния твоєя́ по́мощі. Се бо ми в безмі́рних согріше́ніях оскверни́вшіїся і в ти́ні страсте́й при́сно валя́ющіїся, пра́ведний гнів Бо́жий на себі́ наведо́хом і вся́кия ми́лости недосто́йни сотвори́хомся; ті́мже і не смі́юще возвісти́ оче́с на́ших к висоті́ Небе́сній, ніже́ вознести́ моле́бний глас, се́рдцем сокруше́нним і ду́хом смире́нним тебі́ в хода́тайство і посо́біє призива́єм. Ти у́бо, я́ко стяжа́вий дерзнове́ніє, воздви́гни го́ре преподо́бния твоя́ ру́ці, я́коже іногда́ чу́дний о́ний Мойсе́й Богови́дець Амали́ка побіжда́яй, і просте́р ко Го́споду Творцю́ всіх і Бо́гу те́плую свою́ моли́тву, іспроси́ Це́ркві благостоя́ніє, возду́ха благорастворе́ніє, землі́ плодоно́сіє. Ізба́ви же всіх, ві́рою несумні́нною к Бо́гу приходя́щих і многоціле́бния мо́щі твоя́ благогові́йно почита́ющих, от вся́ких бід душе́вних і тіле́сних, от всіх томле́ній і прило́гов дия́вольських. Бу́ди печа́льним уті́шитель, неду́гующим врач, напа́ствуємим помо́щник, наги́м покрови́тель, вдови́цям засту́пник, си́рим защи́тник, младе́нцем пита́тель, ста́рим укріпи́тель, стра́нствующим путево́ждь, пла́вающим ко́рмчий і ісхода́тайствуй всім, крі́пкия по́мощі твоєя́ усе́рдні тре́бующим, вся я́же ко спасе́нію поле́зная. Я́ко да твої́ми моли́твами наставля́ємі, путь на землі́ маловре́меннаго житія́ на́шего безбі́дні соверши́м, улучи́м же на Небесі́ несконча́ємий поко́й і просла́вим ку́пно с тобо́ю всіх благи́х Да́теля, єди́наго в Тро́йці сла́вимаго Бо́га Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва (перед гробницею преподобного)","ps":["О преподо́бне і богоблаже́нне, па́стирю і нача́льниче, о́тче Ни́ле! Ти у́бо, я́ко імі́я ко Влади́ці Христу́ дерзнове́ніє і ко Пречи́стій Єго́ Ма́тері, Пресвято́й Богоро́дице, бу́ди моли́твенник і помо́щник і хода́тай о нас, недосто́йних рабі́х твої́х, живу́щих во святі́й оби́телі сей, є́йже ти нача́льник богоізбра́нной дружи́ні бра́тству сему́, і о приходя́щих с ві́рою к цільбоно́сним моще́м твої́м. Бу́ди помога́я і заступа́я от зла́го на́шего сопроти́вника, я́ко, да твої́ми моли́твами пребива́ющії на мі́сті сем і приходя́щії с ві́рою к ра́ці моще́й твої́х і на вся́ком мі́сті призива́ющії тя на по́мощ невреди́ми бу́дем от бісо́в і злих челові́к, сла́ву і благодаре́ніє возсила́юще Отцю́, Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко світи́льник всесві́тел, / яви́лся єси́ во о́строві Селиге́ра є́зера, / преподо́бне о́тче Ни́ле, / ти бо крест Христо́в от ю́ности своєя́ на ра́мо взем, / усе́рдно Тому́ послі́довал єси́, / чистото́ю Бо́гові прибли́жився, / отону́дуже і чуде́с дарова́нієм обогати́лся єси́. / Тім і ми, притека́юще к ра́ці моще́й твої́х, уми́льно глаго́лем: / о́тче преподо́бне, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Оте́чества, преподо́бне, удали́вся, / в пусти́ню всели́лся єси́, / і на о́стров Селиге́ра є́зера возше́д, / жесто́ко житіє́ показа́л єси́, / і, мно́гих доброді́тельми удиви́в, / дарова́нія чуде́с от Христа́ прия́л єси́. / Помина́й нас, чту́щих па́м'ять твою́, да зове́м ті: // ра́дуйся, Ни́ле о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Ни́ле, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче а́нгелов."]}],"notes":[]},{"u":"Акафіст святій мучениці Татіані","e":"Akathist to the Holy Martyr Tatiana","secs":[{"h":"Кондак 1","ps":["Ізбра́нній неві́сті Христа́, Вседержи́теля тва́рі, похвапная пі́нія воспису́єм, чистоту́ житія́ твоєго́ ді́вственнаго восхваля́юще і лобиза́юще честна́я страда́нія Твоя́; ти бо ни́ні лику́єши в чертогі небе́снім твоєго́ Жениха́ Христа́. Помина́й прославля́ющих тя пі́нії си́ми, да зове́м ті:","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ тя із дре́вняго Ри́ма, да піснопоє́ши житіє́м твої́м свято́є і́м'я Бо́жиє, от літ ді́тства твоєго́ воспита́на бисть в стра́сі Бо́жії і доброді́теліх, сего́ ра́ди зове́м ті:","Ра́дуйся, ю́нице сладкоблагоуханная;","ра́дуйся, Боже́ственноє Писа́ніє возлюби́вшая.","Ра́дуйся, благоче́стіє в себі́ воспита́вшая;","ра́дуйся, богобоязненному роди́телю внимавшая.","Ра́дуйся, от него́ сі́мена ві́ри прия́вшая;","ра́дуйся, в стра́сі Бо́жії воспитанная.","Ра́дуйся, па́че всіх благ ві́чная бла́га возлюби́вшая.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 2","ps":["Ви́дящи богобоязненний роди́тель твой житіє́ твоє́, всечестна́я, наслади́ся дарова́ній Боже́ственних в тебі́, па́че бо знатности своєя́ і вла́сті консульськия любля́ше Христа́, всяк день хвалу́ Єму́ поя́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум небе́сний тебі́ дарова́ся, єгда́ дости́гла єси́ ю́ности твоєя́ і восхоті́ тогда́ житіє́ твоє́ проводи́ти в ді́встві і цілому́дрії. Христо́с же Бог, укріпля́я тя в сих доброді́теліх, прия́т тя в небе́сная селе́нія. Сего́ ра́ди прийми́ от нас пі́нія сія́:","Ра́дуйся, пти́ці, паря́щая в Небеса́;","ра́дуйся, ді́вство і целому́дріє бисть твої́ крилі́.","Ра́дуйся, Бо́га предпочетшая ми́ру;","ра́дуйся, ю́ность свою́ Христу́ посвятившая.","Ра́дуйся, ла́стовице Боже́ственнаго са́да;","ра́дуйся, то́кмо ко Христу́ любо́вію пламені́ющая.","Ра́дуйся, служившая Єму́ день і нощ.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 3","ps":["Си́ла Боже́ственния любве́ в тебі́ соді́ла тя служительницей Христу́, бисть бо ізбра́на і поста́влена на сла́вноє служе́ніє дияконисси, і отто́лі, служа́щи Це́ркві в ра́дості ве́лієй, возглаша́ше непреста́нно: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́ющи ре́вность о Це́ркві Бо́жієй, в но́вом зва́нії подвиза́лася єси́, труди́ і по́двиги усугубляя і подо́бно безтіле́сним А́нгелом служа́ бли́жнім во Христі́. Ми же, отягченнії гріхми́, си́це глаго́лем ті:","Ра́дуйся, моли́твою услаждавшая житіє́ твоє́;","ра́дуйся, в зва́нії дияконисси послужи́вшая.","Ра́дуйся, в темни́цях у́зников посещавшая;","ра́дуйся, їм у́зи врачевавшая і украшавшая.","Ра́дуйся, добропобедноє по́стничества пра́вило;","ра́дуйся, ко креще́нію жен приуготовлявшая.","Ра́дуйся, благода́ті креще́нія споспі́шнице;","ра́дуйся, бі́дних і вдови́ць окормлявшая.","Ра́дуйся, в біді́ і несчастії отра́ду нося́щая","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 4","ps":["Бу́рю злих напа́стей претерпі́ нечести́вий цар Антони́н Іліогабал, єгда́ ті́ло єго́, влекомо по гра́ду, с поруганієм вве́ржено бисть в реку́ Тибр, во́їном же возведшим на ца́рство Ри́мськоє Алекса́ндра Севи́ра. Ти же, всесла́вная му́ченице, пострада́ла за Христа́ во дні єго́ ца́рствія, піснопоя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще і ви́дяще я́ко млад єсть цар Алекса́ндр Севи́р, нечести́вії консули притесняху христия́н, злочести́вий і зверонравний єпа́рх Ульпіян уби́йство галилеян помисля, повелі́ кла́нятися ри́мським богам. Бисть бо страх ве́лій тогда́ і потече́ я́ко вода́ кров му́чеников. Ти же, всеблага́я Татіа́но, не убоя́лася єси́ стра́ха челові́чеськаго; сего́ ра́ди ми с любо́вію восклиця́єм ті:","Ра́дуйся, заблужде́нію царя́ Алекса́ндра Севи́ра посмеявшаяся;","ра́дуйся, Христа́ і і́долов не сочета́вшая в поклоне́нії.","Ра́дуйся, то́кмо єди́ному Христу́ послужи́вшая;","ра́дуйся, і́доли я́ко сатану́ вміни́вшая.","Ра́дуйся, Ульпіянова стра́ха не убоявшаяся;","ра́дуйся, сочета́нію со Христо́м себі́ приуготовлявшая.","Ра́дуйся, правові́рія цівни́це;","ра́дуйся, стра́ха сме́ртнаго низложительнице.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 5","ps":["Боже́ственний світ осія́ житіє́ твоє́, свята́я му́ченице, єгда́ приспі́ вре́м'я страда́ній твої́х. Ти бо, облече́нная сві́том, взошла єси́ в горни́ло страда́ній і бисть ра́достни ра́ни твоя́ сме́ртния. А́нгели бо служа́ху тебі́ і восклиця́ху непреста́нно Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя чи́стоє житіє́ твоє́, вожди́ язи́честії я́ша тя я́ко християнку і ведо́ша в язи́чеський храм на поклоне́ніє. Ти же вознесе́ моли́тву Христу́ Бо́гу, і паде́ Аполло́н, бог язи́чеський, обвалися ка́пище і́дольськоє, і мно́зі ідолопоклонници смерть прия́ша. Ми же, чту́ще си́лу моли́тви твоєя́, глаго́лем:","Ра́дуйся, Аполлону не поклонившаяся;","ра́дуйся, си́лу моли́тви стяжа́вшая.","Ра́дуйся, моли́твой і́доли сокруши́вшая;","ра́дуйся, тобо́ю бо ка́пище просі́деся.","Ра́дуйся, тобо́ю бо ідолопоклонници посрами́шася;","ра́дуйся, тобо́ю бо научи́шася поклоня́тися Єди́ному Бо́гу.","Ра́дуйся, страх поколеба́вшая;","ра́дуйся із Аполлона бі́са ізгнавшая.","Ра́дуйся, тень бі́са і рида́ніє дия́вольськоє показа́вшая.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 6","ps":["Пропові́дуєть житіє́ твоє́ ве́лію любо́в ко Христу́ і по́двиги. Ти бо по́двигами і моли́твою низложи́ла єси́ і́дольськоє зломи́сліє. Ти бо моли́твою посрами́ла мучи́телі, когтьми желі́зними терзающих ті́ло твоє́, ізнемого́ша бо мучи́телі і возопи́ша: Терпи́м бо са́мі же́стокая муче́нія за праведницю сію́. Ти же лику́юще поя́ше: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ світ Христо́во во во́їніх, мучивших тя, єгда́ уві́роваша в і́стиннаго Бо́га возопи́ша ті: Прості́ ни, служи́тельнице і́стиннаго Бо́га, прості́, і́бо ність на́шея во́лі на страда́ніє твоє́. І от того́ часа́ бисть ча́да Бо́жия. Ми же, восхваля́юще чудеса́ ми́лости Бо́жия, зове́м:","Ра́дуйся, страда́нієм ко Христу́ возводя́щая;","ра́дуйся, А́нгелами охраняємая.","Ра́дуйся, за свої́х мучи́телей молившаяся;","ра́дуйся, сві́том Христо́вим озари́вшая во́їни.","Ра́дуйся, приве́дшая їх во во́їнство небе́сноє;","ра́дуйся, осм во́їнов страда́нієм за Христа́ вінча́вшая.","Ра́дуйся, моли́твою твоє́ю їм о́чі отве́рзшая,","ра́дуйся, муче́нія своя́ на мучи́телей перенесшая.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 7","ps":["Хотя́ воврещи́ на поклоне́ніє і́долом, тя ведо́ша в суди́лище і муче́нієм преда́ша беззако́ннії язи́чници. Ти же яви́лася здра́ва і ці́ла, лице́ же твоє́ бисть сві́тло і ра́достно, і стра́хом об'ят бисть судія́ нечести́вий, повелі́ па́ки і па́ки преда́ти тя го́рким мученіїм. Тя же охраняше А́нгели, служи́телі Бо́га, пою́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго чу́да бисть свиді́телі, я́ко сосця́ твоя́ урезанная істочиста вмі́сто кро́ве млеко́ і ті́ло твоє́ обнаже́нноє муче́ній ра́ди і ноже́м секомоє, істочи́ благоуха́ніє. Раз'ярився нечести́вий мучи́тель і повелі́ крестообра́зно на землі́ распростре́ти тя і би́ти жезли́ желі́зними. Ми же, чудя́щеся страда́нієм твої́м, рцем ті похвали́ такови́я:","Ра́дуйся, Христу́ сорасп'ятая до́блественне;","ра́дуйся, мучи́телей устрашившая і удиви́вшая.","Ра́дуйся, к ізнеможе́нію їх приве́дшая;","ра́дуйся, цівни́це му́жества ві́ри.","Ра́дуйся, я́ко ті́ло твоє́ істочи́ благоуха́ніє не́ба;","ра́дуйся, урезанними сосці́ воскормившая со́нми му́чеников за Христа́.","Ра́дуйся, я́ко і ни́ні благоуха́єши моли́твою к Бо́гу;","ра́дуйся, не оставля́ющая нас своє́ю по́мощію.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до ви́дим на тебі́, всеблаже́нная, ка́ко в темни́ці но́щію моля́щеся і воспіва́юще Христу́ хвали́, небе́снаго сві́та сподо́бися озаре́нія і А́нгелов Бо́жиїх ку́пно славословленіє прийма́ше. Та́ко і ни́ні в ра́йських селе́ніїх со А́нгели піснопоє́ши: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь рачи́тель зло́би бисть єпа́рх, єгда́ па́ки узрі́ тя здра́ву і сві́тлу, ізведену із темни́ці на суди́лище, хоті́ша лаською соблазни́ти тя на поклоне́ніє і́долом. Ти же, ві́дая си́лу моли́тви твоєя́, в храм Діяни напра́ви но́зі твоя́, устреми́ся же біс із боги́ні злочести́вия і возопи́ша: Го́ре мні, го́ре! Ка́мо бігу́; огнь бо сніда́єть м'я. Сего́ ра́ди, побіди́тельнице бісо́в, вопіє́м ті ра́достно:","Ра́дуйся, ле́сти єпа́рха не внявшая;","ра́дуйся, в храм Діяни вошедшая.","Ра́дуйся, моли́твою низведшая с не́ба огнь і ка́пище Діяни разруши́вшая;","ра́дуйся, моли́тви вели́кий пла́меню.","Ра́дуйся, я́ко бі́си присутствія твоєго́ трепета́ху і біжа́ху;","ра́дуйся, крестним зна́менієм безстра́шно себі́ осенявшая.","Ра́дуйся, в моли́тві о́чі к не́бу возводившая;","ра́дуйся, лучі́ благода́ті от не́ба іспросившая.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє удиви́ся си́лі моли́тви твоєя́, єгда́ мно́жество не ві́дящих Бо́га падо́ша і сме́ртний страх прия́ша, опаленнії огне́м, і восхвали́ша Бо́га, ди́внаго во святи́х свої́х, пі́снею: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многоглаголивії не мо́гуть восхвали́ти тя по достоя́нію, сла́вная му́ченице Христо́ва. Кто бо возмо́жеть вели́чіє страда́ній твої́х ізрещи́? Кто по́двиги твоя́ воспоє́ть досто́йно? То́кмо надеясь на неізрече́нную ми́лость твою́, дерза́єм принести́ ті сія́ похвали́:","Ра́дуйся, сла́дость христия́нських серде́ць;","ра́дуйся, нам принося́щая ми́лость от Бо́га.","Ра́дуйся, моли́тві науча́ющая нас усе́рдно;","ра́дуйся, проше́нієм на́шим внемлющая.","Ра́дуйся, я́ко ско́ро проше́нія прино́сиши Бо́гу;","ра́дуйся, я́ко го́рких муче́ній ізбавля́єши.","Ра́дуйся, благоуха́нная ві́тве ра́йськая;","ра́дуйся, черто́гов О́тчих жительнице.","Ра́дуйся, Ца́рствія Небе́снаго наслі́днице.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 10","ps":["Спаси́тельнаго твоєго́ по́двига зря́ще тече́ніє, восхваля́єм страда́нія твоя́, ти бо претерпі́ бичеванія, крестообразноє к по́лу пригвожде́ніє, ті́ла ізсіче́ніє, сосцов вириваніє, біє́ніє і осмія́ніє, в темни́ці заключе́ніє і іни́я злострада́нія. Ни́ні же, вінце́м Ца́рствія Небе́снаго вінча́вшися, со всі́ми святи́ми взива́єши: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ і адама́нт тверд била́ єси́, єгда́ на растерза́ніє звіре́м ведена явля́єшися, лев бо у ног твої́х ласкашеся і не растерза́ша тя, но єгда́ хотя́ху от'яти льва, сей а́біє разсвирі́пі і разтерза сановника Євме́нія, указу́я си́лу христия́нськую. Сего́ ра́ди глаго́лем в стра́сі:","Ра́дуйся, звіре́й в а́гнцев претворя́ющая;","ра́дуйся, моли́твою їх ум'ягча́ющая.","Ра́дуйся, за смерть Євменієву мучимая;","ра́дуйся, на дре́ві повешенная.","Ра́дуйся, желі́зними когтьми стружаємая;","ра́дуйся, во волхвова́нії оклеветанная.","Ра́дуйся, нас клевети́ ізбавля́ющая;","ра́дуйся, от зла́го волхвова́нія нас сохраня́ющая.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 11","ps":["Пі́ніє непреста́нноє вознося́ ко Го́споду, била́ єси́ вмісти́лищем си́ли і сла́ви Бо́жия. Сего́ ра́ди мо́лим тя: умоли́ Го́спода за нас грі́шних, свята́я му́ченице Татіа́но, да ниспо́слеть і нам чудеса́ ми́лости Своєя́, песнопоющим ни́ні: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельная свіща́ бисть во страда́нії твоє́м, свята́я му́ченице, озаря́я сві́том се́рдця язи́чеськия, да обря́щуть тобо́ю і́стиннаго Бо́га, да водворя́ться їх душі́ в селе́ніїх ра́йських. Сего́ ра́ди уми́льно восклиця́єм ті:","Ра́дуйся, носительнице сві́та благода́тнаго;","ра́дуйся, со́лнце лежа́щих во злі.","Ра́дуйся, ти бо нас сві́том озаря́єши;","ра́дуйся, ти бо нас к блаже́нству веде́ши.","Ра́дуйся, в ка́пищі Зевса заключе́нная;","ра́дуйся, єго́ низложи́вшая і разсипавшая.","Ра́дуйся, власо́в лишившаяся;","ра́дуйся, я́ко язи́чници ми́сляху, я́ко во власіх твої́х ча́ри обріта́ються.","Ра́дуйся, і по остриже́нії власо́в чудотворящая си́лою Христо́вою.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 12","ps":["Благода́ть от Бо́га получи́вши, к сме́ртному часу́ пришла́ єси́, єгда́ бисть в ка́пищі Зевса заключе́на, і поутру, єгда́ прийдо́ша язи́честії жреци́, ви́дівше Зевса пове́ржена, а тя лику́ющу, па́ки ведо́ша тя на суди́лище, і бисть смерть твоя́ от усіче́нія ме́чнаго. Ти же, сла́вная му́ченице, гото́в'ящися к селе́нієм небе́сним, взива́ла єси́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ усіче́ніє ме́чноє, восхваля́єм отше́ствіє твоє́ во вожделі́нноє оте́чество, іді́же ни́ні ти лику́єши со А́нгели і со всі́ми святи́ми во сла́ві невече́рней. Сего́ ра́ди прийми́ от нас словеса́ сія́:","Ра́дуйся, мече́м усеченная за Христа́;","ра́дуйся, с роди́телем твої́м пострада́вшая.","Ра́дуйся, вінце́в му́ченичеських сподо́бившаяся;","ра́дуйся, со Христо́м сочетавшаяся.","Ра́дуйся, со Апо́столи ликующая;","ра́дуйся, со святи́ми му́ченики хвалу́ Бо́гу вознося́щая.","Ра́дуйся, не лишившая нас ра́дости твоєя́;","ра́дуйся, на́ші се́рдця зажигающая Боже́ственним огне́м.","Ра́дуйся, і́долов на́ших попирающая;","ра́дуйся, начертавшая нам сла́ву Христа́.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 13","ps":["О, всесла́вная і великоімени́тая му́ченице Христо́ва Татіа́но, ді́вства і чистоти́ сосу́д злати́й! Ни́ні ми́лостивно при́зри на моля́щіяся ті і прилі́жно просящия твоєго́ моли́твеннаго у Бо́га предста́тельства. Да́руй нам чистоту́ ті́ла і душі́, ізба́ви нас муче́ній гріхо́вних, да ви́ну Го́споду зове́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць ізбра́ тя із дре́вняго Ри́ма, да піснопоє́ши житіє́м твої́м свято́є і́м'я Бо́жиє, от літ ді́тства твоєго́ воспита́на бисть в стра́сі Бо́жії і доброді́теліх, сего́ ра́ди зове́м ті:","Ра́дуйся, ю́нице сладкоблагоуханная;","ра́дуйся, Боже́ственноє Писа́ніє возлюби́вшая.","Ра́дуйся, благоче́стіє в себі́ воспита́вшая;","ра́дуйся, богобоязненному роди́телю внимавшая.","Ра́дуйся, от него́ сі́мена ві́ри прия́вшая;","ра́дуйся, в стра́сі Бо́жії воспитанная.","Ра́дуйся, па́че всіх благ ві́чная бла́га возлюби́вшая.","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Кондак 1","ps":["Ізбра́нній неві́сті Христа́, Вседержи́теля тва́рі, похвапная пі́нія воспису́єм, чистоту́ житія́ твоєго́ ді́вственнаго восхваля́юще і лобиза́юще честна́я страда́нія Твоя́; ти бо ни́ні лику́єши в чертогі небе́снім твоєго́ Жениха́ Христа́. Помина́й прославля́ющих тя пі́нії си́ми, да зове́м ті:","Ра́дуйся, благоуха́нний цві́те ді́вства, сла́вная му́ченице Татіа́но."]},{"h":"Молитва","ps":["О свята́я му́ченице Татіа́но! Неві́сто Сладча́йшаго Жениха́ твоєго́ Христа́, а́гнице А́гнця Боже́ственнаго, голуби́це цілому́дрія! Страда́ньми, я́ко оде́ждами ца́рськими оді́янная, к лико́м Небе́сним сопричте́нная, лику́ющая ни́ні во сла́ві ві́чній! От дній млади́х Бо́гу обеща́вшаяся свята́я служи́тельнице Це́ркве, целому́дріє соблю́дшая і па́че всіх благ Го́спода возлюби́вшая! Тебі́ ми мо́лимся і тебі́ ми про́сим: внемли́ проше́нієм на́шим серде́чним, і не отверга́й моле́ній на́ших! Да́руй чистоту́ ті́ла і душі́, вдохни́ любо́в к Боже́ственним і́стинам, на путь доброді́телей веди́ нас, А́нгельськоє охране́ніє іспроси́ у Бо́га нам. На́ші ра́ни і язви́ тіле́сния сотвори́ безболі́зненни, в злострада́нії терпі́ніє да́руй. Гріхо́вния я́зви уврачу́й. Ю́ность на́шу огради́, ста́рость безболі́зненну і безбе́дну да́руй, в сме́ртнім ча́сі помози́! Помина́й на́ші ско́рби, і отраду́ да́руй! Посіти́ нас, су́щих в темни́ці гріха́: на покая́ніє наста́ви ско́ро, возжжи́ пла́мень моли́тви! Не оста́в нас си́рих! Да сла́в'яще страда́нія твоя́, возсила́єм хвалу́ Го́споду сил, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["А́гнцю Пречи́стому і Па́стирю послі́дуя, / а́гнице слове́сная Татіа́но / ми́сленних звіре́й не убоя́лася єси́, / но зна́менієм кре́стним вооружи́вшися, / до конця́ тіх низложи́ла єси́, / і вошла́ єси́ в Небе́сную огра́ду, // іді́же пом'яни́ і нас, му́ченице Христо́ва многому́драя."]},{"h":"Інший тропар, глас 4","ps":["Всечестна́я благоче́стія учреди́тельнице, / прехва́льная і всеблаже́нная му́ченице Татіа́но, / сосу́дом ді́вства і чистоти́ яви́вшаяся / і неве́стой Христо́вой наре́кшаяся, / страда́ній кровми́ украси́вшеся, / возлеті́ла єси́ в не́бі в Небе́сний черто́г, // ті́мже чту́щия тя помина́й."]},{"h":"Кондак, глас 4","ps":["Сві́тло во страда́нії твоє́м возсія́ла єси́, страстоте́рпице, / от крове́й твої́х преіспещре́на, / і, я́ко кра́сная голуби́ця, к Небесі́ возлеті́ла єси́, Татіа́но: // ті́мже моли́ при́сно за чту́щия тя."]},{"h":"Величання","ps":["Велича́єм тя, свята́я му́ченице Татіа́но, і чтим честна́я страда́нія твоя́, я́же за Христа́ претерпі́ла єси́."]}],"notes":[]},{"u":"Акафіст святій блаженній Ксенії Петербурзькій","e":"Akathist to the Holy Blessed Xenia of Petersburg","secs":[{"h":"Кондак 1","ps":["Ізбра́нная уго́днице Христо́ва, свята́я блаже́нная Ксе́ніє, хвале́бноє пі́ніє ті прино́сим, чту́ще терпі́ніє твоє́ і злострада́ніє во́льноє; ти же, іму́щи дерзнове́ніє ко Го́споду, во вся́ких біда́х і напа́стіх заступа́й нас, грі́шних, взива́ющих к тебі́:","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Ікос 1","ps":["Равноа́нгельськи на землі́ пожила́ єси́, блаже́нная ма́ти, по успе́нії му́жа твоєго́, без приуготовле́нія христия́нськаго внеза́пу сконча́вшагося, отве́ргла єси́ жизнь мирську́ю, моля́щи Бо́га супру́га твоєго́ ду́шу поми́ловати, по́двиг юро́дства на себі́ прия́вши, стяжа́ла єси́ соверше́нство духо́вноє. Того́ ра́ди усли́ши от нас похвали́ сія́, тебі́ возноси́мия:","Ра́дуйся, Христо́ва уго́дниця, в ми́рі надми́рно пожи́вшая;","ра́дуйся вся прило́ги ми́ра, пло́ті і дия́вола побіди́вшая.","Ра́дуйся, нищету́ во́льную на всю жизнь ізбра́вшая;","ра́дуйся, сокро́вище на Небесі́ імі́ти возжела́вшая.","Ра́дуйся, житіє́м твої́м Андре́ю, Христа́ ра́ди юро́дивому, ра́вная;","ра́дуйся, от всіх люде́й правосла́вних люби́мая і сла́вимая.","Ра́дуйся, о часі́ сме́ртнім по́мнити нас призива́ющая;","ра́дуйся, бли́жняго ду́шу па́че ми́ра сего́ люби́ти нас науча́ющая.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дяще стра́нноє житіє́ твоє́, блаже́нная, я́ко во цві́те мла́дости твоєя́ во оде́жду му́жа твоєго́ усо́пшаго облекла́ся єси́, і́менем єго́ нарекла́ся єси́, себе́ уме́ршую би́ти глаго́лющи, дом же твой і вся блага́я земна́я оста́вивши, скита́лицю себі́ сотвори́ла єси́, сро́дниці твої́ безу́мную тя би́ти мня́ху, лю́діє же боголюби́вії воспі́ша: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум, от Бо́га ті дарова́нний, в безу́мії мни́мом сокри́ла єси́, блаже́нная Ксе́ніє; в суєті́ же гра́да вели́каго, а́ки пусти́нниця, пребива́ла єси́, моли́тви своя́ к Бо́гу вознося́щи непреста́нно. Ми же, див'я́щеся житію́ твоєму́, воспіва́єм ті си́це:","Ра́дуйся, крест тя́жкий юро́дства, от Бо́га ті да́нний, на ра́мо своє́ прия́вшая;","ра́дуйся, мни́мим безу́мієм сія́ніє благода́ті сокри́вшая.","Ра́дуйся, і́менем му́жеським наре́кшися, не́мощі же́нськия отреши́вшаяся;","ра́дуйся, печа́лі і ско́рби кро́тці терпе́вшая.","Ра́дуйся, все імі́ніє твоє́ бі́дним лю́дем разда́вшая;","ра́дуйся, жили́ще Ду́ху Свято́му в се́рдці твоє́м угото́вившая.","Ра́дуйся, всім прибега́ющим к тебі́ благо́є утіше́ніє;","ра́дуйся, от сме́рти внеза́пния ізбавле́ніє.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою, сви́ше ті дарова́нною, благода́тію і му́жеством, зной і сту́жу лю́тую претерпіва́ла єси́, всено́щно моля́щися і покло́ни творя́щи; ті́мже і просла́влена бисть свя́тость твоя́, блаже́нная Ксе́ніє, во Оте́честві на́шем многострада́льнім і во всем ми́рі правосла́внім, да зове́м с тобо́ю Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́ла єси́, о ма́ти блаже́нная, не́бо покро́в і зе́млю ло́же своє́, о ті́лі, во оде́жду ве́тхую облече́ннем, небрегла́ єси́, моли́тви же к Бо́гу пла́менні возноси́ла єси́, сего́ ра́ди воспіва́єм ті си́це:","Ра́дуйся, вік твой земни́й без кро́ва прове́дшая;","ра́дуйся, Небе́снаго кро́ва взиска́вшая і того́ улучи́вшая.","Ра́дуйся, по вся дні но́щію в по́ли моли́вшаяся;","ра́дуйся, покло́ни земни́я на вся страни́ сві́та та́мо твори́вшая.","Ра́дуйся, град Петро́во всено́щним бді́нієм от бід огражда́вшая;","ра́дуйся, гнів Бо́жий от него́ мно́гажди отвраща́вшая.","Ра́дуйся, благода́тію Ду́ха Свята́го чуде́сно согріва́ємая;","ра́дуйся, хлад лю́тий душ на́ших моли́твою твоє́ю растаява́ющая.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́рю жите́йськую, во гра́ді Петро́ві м'яту́щуюся, кро́тостію і незло́бієм препобежда́ла єси́, ма́ти блаже́нная, безстра́стіє же посреді́ ми́ра су́єтнаго стяжа́ла єси́ і та́ко, Ду́хом Святи́м просвеща́ємая, взива́ла єси́ Пода́телю тишини́ серде́чния Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша лю́діє дар прозрі́нія чу́дний, тобо́ю явле́нний, свята́я ма́ти, і удиви́шася. Се, жені́ ні́коєй рекла́ єси́: возьми́ п'ята́к, зді цар на коні́, поту́хнеть. Та же не ве́дающи, я́ко ти запале́ніє до́ма єя́ прозре́ла єси́, притече́ во своя́ сі і узри́ дом свой во огні́ горя́щ, і а́біє по моли́тві твоє́й пла́мень огня́ угасе́. Мно́зі же стра́ждущії к по́мощі твоє́й прибіга́ху, ю́же стяжа́вше, та́ко взива́ша ті:","Ра́дуйся, дар прозрі́нія смире́нієм кра́йнім стяжа́вшая;","ра́дуйся, дар сей на по́льзу і спасе́ніє стра́ждущим явля́вшая.","Ра́дуйся, свіще́ негаси́мая, к Бо́гу в моли́твах горі́вшая;","ра́дуйся, ві́рою твоє́ю пла́менною запале́ніє домо́в угаша́вшая.","Ра́дуйся, гряду́щия ско́рби людські́я, а́ки настоя́щия, зре́вшая;","ра́дуйся, врач безме́здний і милосе́рдий лю́дем би́вшая.","Ра́дуйся, я́ко і нас, немощни́х во ві́рі, укріпля́єши;","ра́дуйся, я́ко сія́нієм свя́тости твоєя́ лю́ди правосла́вния озаря́єши.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́ся свя́тость твоя́ на тве́рди гра́да Петро́ва, уго́днице Бо́жия, заре́ю своє́ю сердца́ просвіща́ющая: уже́ бо лю́дем, в безу́мії гріха́ погиба́ющим, путь спасе́нія указа́ла єси́, к покая́нію їх наставля́ющи, во є́же вопи́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще по́двиги твоя́ моли́твенния, терпі́ніє хла́да і зно́я вели́коє, лю́діє осла́бити жела́ху злострада́нія твоя́; ти же оде́жду і вся, і́ми приноси́мая, ни́щим раздава́ла єси́, нищету́ свою́, а́ки сокро́вище, храня́щи. Сего́ ра́ди сли́шиши от нас сицева́я:","Ра́дуйся, бога́тство твоє́ то́кмо в любві́ к Бо́гу і бли́жнім полага́вшая;","ра́дуйся, нічто́же земно́є імі́вшая і всіх духо́вно богати́вшая.","Ра́дуйся, ми́лостивим твої́м се́рдцем стра́ждущим сострада́вшая;","ра́дуйся, по́мощ їм чрез до́брих люде́й посила́вшая.","Ра́дуйся, чу́ждая ми́ру, в ми́рі живу́щим бла́го твори́вшая;","ра́дуйся, ві́ка сего́ суєму́дрія отверга́тися научи́вшая.","Ра́дуйся, пла́кати с пла́чущими нас подвига́ющая;","ра́дуйся, от тя́жкаго сна гріхо́внаго пробужда́ющая.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 6","ps":["Пропове́дана бисть свя́тость житія́ твоєго́, блаже́нная, жи́телем гра́да твоєго́, єгда́ ти, о младе́нці, єще́ не ро́ждшемся, пеку́щися, жені́ до́брій, в до́мі, тобо́ю дарова́нном, жи́вшей, рекла́ єси́: Бог тебі́ си́на посла́, теки́ на кла́дбищі Смоле́нськоє. Та́я же, со тща́нієм прите́кши, сироту́, рожде́нна ма́терію, внеза́пу на путі́ пострада́вшею і сконча́вшеюся, в дом свой прия́ла єсть; вся же лі́та житія́ своєго́, тебі́ благодаря́ще, сія́ семя́ благода́тная Бо́гу Человіколю́бцю взива́ше: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єсть сла́ва по́двигов твої́х, блаже́нная ма́ти Ксе́ніє, єгда́ но́щію на верх хра́ма Смоле́нськаго ка́меніє, тая́щися, носи́ла єси́, до́му Пречи́стій возгради́тися посо́бствующи. Ни́ні же всі моля́щіїся во святі́м хра́мі сем і во всем ми́рі Бо́жиєм, взира́юще на о́браз твой, воспіва́ють ті такова́я:","Ра́дуйся, та́йно твори́ти добро́ науча́ющая;","ра́дуйся, к по́двигом благоче́стія всіх призива́ющая.","Ра́дуйся, строї́телем хра́мов Бо́жиїх помога́ющая;","ра́дуйся, святи́ню церко́вную возлюби́вшая.","Ра́дуйся, в ді́ліх благи́х усе́рдноє поспіше́ніє;","ра́дуйся, трудо́в на́ших на путі́ спасе́нія облегче́ніє.","Ра́дуйся, под кро́вом Бо́жия Ма́тере по́двиги твори́вшая і та́ко почи́вшая;","ра́дуйся, с Не́ю ни́ні на Небесі́х о нас Христа́ моля́щая.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хотя́ще судьби́ людські́я во блага́я устро́їти, повелі́ла єси́ ді́ві кро́тцей на Охту́ тещи́, проре́кши, я́ко «муж твой та́мо жену́ погреба́єть». Та же, а́ще і недоуміва́шеся, оба́че не ослу́шася глаго́ла твоєго́, і та́мо вдовця́ мла́да, над гро́бом жени́ рида́вшаго, сре́тила єсть і утіше́ніє в моли́тві єму́ подаде́. Лі́ту же мину́вшу, о́на венча́стася, і та́ко мно́гая лі́та в любві́ і согла́сії пожи́вше, чад свої́х наставля́ху тебе́, свята́я ма́ти, чти́ти, Бо́гу же воспіва́ти піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до показа́ла єси́, блаже́нная, посреді́ скве́рни людські́я ду́шу твою́, юро́дством сокри́тую, в кро́тості а́нгельстій соблю́дши. Научи́ і нас, ма́ти Ксе́ніє, і ма́лия до́ли скорбе́й твої́х не терп'я́щих і в ро́поті на Бо́га і бли́жняго дні на́ші іждива́ющих, вся сви́ше посила́ємая в терпі́нії сноси́ти, да взира́юще на по́двиги твоя́, чи́стим се́рдцем зове́м ті си́це:","Ра́дуйся, ми́ру злохла́дному благода́тную му́дрость яви́вшая;","ра́дуйся, нищети́ духо́вния блаже́нство вкуси́вшая.","Ра́дуйся, о́браз терпі́нія і благосе́рдія нам подаю́щая;","ра́дуйся, смире́нієм і покая́нієм от бід ізбавля́тися науча́ющая.","Ра́дуйся, с моли́твою і любо́вію діте́й благословля́вшая;","ра́дуйся, прикоснове́нієм руку́ твоє́ю чуде́сно їх ісцеля́вшая.","Ра́дуйся, уни́ніє тя́жкоє, ду́шу сокруша́ющеє, от нас отводя́щая;","ра́дуйся, наде́ждою несумні́нною на ми́лость Бо́жию окриля́ющая.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нниця бездо́мная протекла́ єси́ путь ско́рбний житія́ твоєго́ в сто́льнем гра́де Оте́чества на́шего, ма́ти блаже́нная, взиску́ющи гра́да ви́шняго, Ієрусали́ма Небе́снаго; ни́ні же в нем со А́нгели і всі́ми святи́ми поє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся в моли́твах ко Творцю́ пребива́ющи, ма́ти свята́я, до успе́нія твоєго́, от страда́ній і по́двигов к жи́зні блаже́ней і ві́чній невозбра́нно прешла́ єси́. Сего́ ра́ди, преклоня́юще колі́на серде́ць на́ших, благогові́йноє пі́ніє ті прино́сим:","Ра́дуйся, во оби́теліх го́рніх с ли́ки святи́х лику́ющая;","ра́дуйся, і нас, тебі́ моля́щихся, та́мо не забива́ющая.","Ра́дуйся, чудеса́ неісче́тная по успе́нії твоє́м яви́вшая;","ра́дуйся, сме́ртно боля́щих, врачми́ оста́вленних, ісцеля́вшая.","Ра́дуйся, в пія́нстві ги́бнущих устраше́ніє і ісправле́ніє;","ра́дуйся, мі́ста служе́нія лиши́вшимся благо́є поспіше́ніє.","Ра́дуйся, вдови́ць і жен, супру́гом оста́вленних, покрови́тельнице;","ра́дуйся, стра́нников і безприю́тних пита́тельнице.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 9","ps":["Вся́кия утоли́ болі́зні, блаже́ная ма́ти Ксе́ніє, на тя наді́ющихся і к по́мощі твоє́й усе́рдно притека́ющих: я́коже помина́вших пре́жде ду́шу твою́ ра́ди душі́ своєя́ спасе́нія, по заві́ту твоєму́, та́ко і ни́ні пом'яни́ всіх, прославля́ющих тя, Бо́гу же, в тебі́ ди́вно просла́вленному, вопію́щих непреста́нно: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я суєму́дренния разумі́ти не мо́гуть, ка́ко ти безу́мієм свої́м безу́міє ми́ра сего́ обличи́ла єси́ і не́мощію своє́ю си́льния і крі́пкия посрами́ла єси́: не ві́дають бо в тебі́ си́ли і прему́дрости Бо́жия. Ми же, тя почита́юще, с любо́вію зове́м ті си́це:","Ра́дуйся, Боже́ственнаго Ду́ха селе́ніє;","ра́дуйся, ве́ліє к Бо́гу дерзнове́ніє.","Ра́дуйся, у усипа́льници твоєя́ моля́щимся явля́ющаяся і їм помога́ющая;","ра́дуйся, земле́ю і єле́єм от нея́ мно́гія освяти́вшая і от неду́г ісціли́вшая.","Ра́дуйся, я́ко одержи́мих страстьми́ от ги́белі спаса́єши;","ра́дуйся, я́ко отверга́тися себі́ нас науча́єши.","Ра́дуйся, любве́ і смире́нія путь во спасе́ніє нам указу́ющая;","ра́дуйся, во хра́мі Бо́жиєм с на́ми незри́мо пребива́ющая.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасти́ лю́ди хотя́щи, блаже́нная ма́ти Ксе́ніє, при́сно да́руєши їм заступле́ніє твоє́ чу́дноє. Се ді́ву благочести́вую с вдови́цею ма́терію єя́, в кану́н вінча́нія у гробни́ци твоєя́ усе́рдно моли́вшуюся, от бра́ка спасла́ єси́ со злоді́єм, і́же ра́тнаго челові́ка уби́, і́м'я же і чин єго́ себі́ присво́ї. В день то́йже уби́йця о́ний внеза́пу обличе́н бисть і, у́жасом об'я́т, іспові́да пред всі́ми, я́ко си́ла Бо́жия сироту́ от бра́ка с ним ізба́ви, ми же, див'я́щеся си́лі моли́тв твої́х, нас спаса́ющих, воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ неруши́мая, преблаже́нная ма́ти, і дом правосла́вних. Не оста́ви і ни́ні супру́ги разлуче́нния, помози́ роди́телем, за гріхи́ своя́ о ча́діх сле́зи пролива́ющим, научи́ ю́ноши і ді́ви в чистоті́ себі́ храни́ти і всіх нас святи́ню уз семе́йних почита́ти, да єди́німи усти́ воспіва́єм ті та́ко:","Ра́дуйся, дів благочести́вих от бра́ка неві́рнаго ізбавля́ющая;","ра́дуйся, спу́тника жи́зні до́браго їм обрісти́ помога́ющая.","Ра́дуйся, сро́дник вражду́ющих благо́є примире́ніє;","ра́дуйся, слез ді́тських осуше́ніє.","Ра́дуйся, от убіє́нія младе́нцев во чре́ві жена́м гро́зноє преще́ніє;","ра́дуйся, на ка́мені любве́ і ві́ри домо́в устроє́ніє.","Ра́дуйся, супру́гов, сме́ртію разлуче́нних, утіше́ніє;","ра́дуйся, в жи́зні безсме́ртній ві́чноє їх соєдине́ніє.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє прино́сять ті, ма́ти блаже́нная, лю́діє правосла́внії, от бід і болі́зней моли́твами твої́ми ізба́вленнії; і ни́ні, а́ще попу́стить нам Всепра́ведний Госпо́дь ско́рби гріх на́ших ра́ди, со слеза́ми к тебі́ припаде́м, упова́юще на ми́лостивоє твоє́ о нас к Бо́гу предста́тельство, да воспоє́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная луча́ во мра́ці житія́ сего́, путь ко Сві́ту Непристу́пному освіща́ющая, яви́лася єси́, богому́драя Ксе́ніє, чуде́с мно́жеством просія́вши. В лю́тую же годи́ну гоне́ній безбо́жних ві́рнії от часо́вни твоєя́ не отступи́ша, но, презрі́вше і страх сме́ртний, с ві́рою і упова́нієм к тебі́ притека́ху, се́рдцем воспіва́юще си́це:","Ра́дуйся, безнаде́жних наді́яніє;","ра́дуйся, в бе́здні отча́янія погиба́ющих спасе́ніє.","Ра́дуйся, уни́женних і гони́мих покрови́тельнице;","ра́дуйся, от клевети́ і суда́ непра́веднаго защи́тнице.","Ра́дуйся, оби́димих і обездо́ленних утіше́ніє;","ра́дуйся, оби́дящих гро́зноє вразумле́ніє.","Ра́дуйся, гра́да свята́го Петра́ засту́пнице;","ра́дуйся, ча́дом землі́ Украї́нськия ма́ти і пита́тельнице.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть утіше́ній оби́льно ізлива́єши, блаже́нная Ксе́ніє, всім чту́щим па́м'ять твою́ і к заступле́нію твоєму́ притека́ющим. Ті́мже і ми, грі́шнії, на тя по Бо́зі наде́жду на́шу возлага́єм і мо́лимся тебі́ усе́рдно: не оста́ви нас во обстоя́ніїх ско́рбних, умоли́ Го́спода сил, да не отпаде́м от ві́ри правосла́вния, в не́йже тобо́ю утвержда́єми, зове́м Єму́ ві́рно: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще мно́гая твоя́ чудеса́, блаже́нная ма́ти Ксе́ніє, восхваля́єм тя, я́ко те́плую на́шу засту́пницю і ско́рую предста́тельницю. Улуча́юще же от тебе́ по́мощ благода́тную, неуста́нно воспіва́єм ті си́це:","Ра́дуйся, сві́том кро́тости твоєя́ вся конці́ землі́ озари́вшая;","ра́дуйся, житіє́м твої́м по́стничеським горди́ню дия́вольськую посрами́вшая.","Ра́дуйся, до́му ца́рському поможе́ніє і благослове́ніє;","ра́дуйся, ми́ра Бо́жія в сердця́ ві́рних насажде́ніє.","Ра́дуйся, о спасе́нії Оте́чества на́шего при́сно моля́щаяся;","ра́дуйся во Оте́чество Небе́сноє нам путь указу́ющая.","Ра́дуйся, по Богоро́дице в ско́рбіх і печа́ліх на́ше утіше́ніє;","ра́дуйся, по Бо́зі гріхо́в на́ших проще́ніє і ві́чноє спасе́ніє.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 13","ps":["О свята́я блаже́нная ма́ти Ксе́ніє, в житії́ твоє́м крест тя́жкий поне́сшая. Прийми́ от нас, грі́шних, моле́ніє сіє́, тебі́ приноси́моє, огради́ нас моли́твами твої́ми от наві́тов духо́в тьми, от бід і напа́стей, умоли́ Всеще́драго Бо́га пода́ти нам си́лу і крі́пость, да взе́мше крест свой, вослі́д Христу́ гряде́м, пою́ще Єму́ с тобо́ю вове́ки: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Равноа́нгельськи на землі́ пожила́ єси́, блаже́нная ма́ти, по успе́нії му́жа твоєго́, без приуготовле́нія христия́нськаго внеза́пу сконча́вшагося, отве́ргла єси́ жизнь мирську́ю, моля́щи Бо́га супру́га твоєго́ ду́шу поми́ловати, по́двиг юро́дства на себі́ прия́вши, стяжа́ла єси́ соверше́нство духо́вноє. Того́ ра́ди усли́ши от нас похвали́ сія́, тебі́ возноси́мия:","Ра́дуйся, Христо́ва уго́дниця, в ми́рі надми́рно пожи́вшая;","ра́дуйся вся прило́ги ми́ра, пло́ті і дия́вола побіди́вшая.","Ра́дуйся, нищету́ во́льную на всю жизнь ізбра́вшая;","ра́дуйся, сокро́вище на Небесі́ імі́ти возжела́вшая.","Ра́дуйся, житіє́м твої́м Андре́ю, Христа́ ра́ди юро́дивому,","ра́вная; ра́дуйся, от всіх люде́й правосла́вних люби́мая і сла́вимая.","Ра́дуйся, о часі́ сме́ртнім по́мнити нас призива́ющая;","ра́дуйся, бли́жняго ду́шу па́че ми́ра сего́ люби́ти нас науча́ющая.","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нная уго́днице Христо́ва, свята́я блаже́нная Ксе́ніє, хвале́бноє пі́ніє ті прино́сим, чту́ще терпі́ніє твоє́ і злострада́ніє во́льноє; ти же, іму́щи дерзнове́ніє ко Го́споду, во вся́ких біда́х і напа́стіх заступа́й нас, грі́шних, взива́ющих к тебі́:","Ра́дуйся, Ксе́ніє блаже́нная, моли́твеннице о душа́х на́ших."]},{"h":"Молитва","ps":["О свята́я всеблаже́нная ма́ти Ксе́ніє! Под кро́вом Всеви́шняго жи́вшая, відо́мая і укрепля́ємая Богома́терію, глад і жа́жду, хлад і зной, поноше́нія і гоне́нія претерпі́вшая, дар прозорли́вости і чудотворе́нія от Бо́га прия́ла єси́ і под сі́нію Всемогу́щаго поко́їшися. Ни́ні Свята́я Це́рков, я́ко благоуха́нний цвіт, прославля́єть тя. Предстоя́ще на мі́сті погребе́нія твоєго́, пред о́бразом твої́м святи́м, я́ко живі́й ті, су́щей с на́ми, мо́лимся тебі́: прийми́ проше́нія на́ша і принеси́ їх ко Престо́лу милосе́рдаго Отця́ Небе́снаго, я́ко дерзнове́ніє к Нему́ іму́щая. Іспроси́ притека́ющим к тебі́ ві́чноє спасе́ніє, на блага́я ді́ла і начина́нія на́ша ще́дроє благослове́ніє, от вся́ких бід і скорбе́й ізбавле́ніє. Предста́ни святи́ми твої́ми моли́твами пред Всеми́лостивим Спаси́телем на́шим о нас, недосто́йних і грі́шних. Помози́, свята́я блаже́нная ма́ти Ксе́ніє, младе́нці сві́том свята́го креще́нія озари́ти і печа́тію да́ра Ду́ха Свята́го запечатлі́ти, о́троки і отрокови́ці во ві́рі, че́стности, богобоя́зненности воспита́ти і успе́хи в уче́нії їм дарова́ти; боля́щия і неду́гующия ісціли́, семе́йним любо́в і согла́сіє низпосли́, мона́шествующих по́двигом до́брим подвиза́тися удосто́й і от поноше́ній огради́, па́стирі в крі́пості Ду́ха Свята́го утверди́, лю́ди і страну́ на́шу в ми́рі і безм'яте́жії сохрани́, о лише́нних в предсме́ртний час причаще́нія Святи́х Христо́вих Та́їн умоли́. Ти на́ша наде́жда і упова́ніє, ско́роє усли́шаніє і ізбавле́ніє, тебі́ благодаре́ніє возсила́єм і с тобо́ю сла́вим Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 7","ps":["Нищету́ Христо́ву возлюби́вши, / безсме́ртния трапе́зи ни́ні наслажда́єшися, / безу́мієм мни́мим безу́міє ми́ра обличи́вши, / смире́нієм кре́стним си́лу Бо́жию восприя́ла єси́. / Сего́ ра́ди дар чудоді́йственния по́мощі стяжа́вшая, / Ксе́ніє блаже́нная, моли́ Христа́ Бо́га // ізба́витися нам от вся́каго зла покая́нієм."]},{"h":"Кондак, глас 3","ps":["Днесь сві́тло лику́єть град свята́го Петра́, / я́ко мно́жество скорб'я́щих обріта́ють утіше́ніє, / на твоя́ моли́тви наді́ющеся, / Ксе́ніє всеблаже́нная, // ти бо єси́ гра́ду сему́ похвало́ і утвержде́ніє."]},{"h":"Інший кондак, глас 3","ps":["На землі́ я́ко стра́нна преби́вши, / о Небе́снім же оте́чествії воздиха́ющи, / юро́да от бу́їїх і неві́рних, / прему́дра же і свя́та от ві́рних познава́єшися, / і от Бо́га сла́вою і че́стію вінча́єшися, / Ксе́ніє мужеу́мная і богоу́мная, / сего́ ра́ди зове́м ті: // ра́дуйся, я́ко по стра́нствії земні́м в дому́ О́тчем водворя́єшися."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я блаже́нная ма́ти Ксе́ніє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святим Петру і Февронії Муромським","e":"Akathist to the Holy Peter and Fevronia of Murom","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці і вели́ції уго́дниці Госпо́дні, гра́да Му́рома засту́пниці і при́снії о душа́х на́ших моли́твенниці, святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє! Пі́ніє похва́льноє вам принося́ще, мо́лим ви усе́рдно: я́ко іму́щії дерзнове́ніє ко Го́споду, предста́тельством ва́шим от вся́ких бід нас свободи́те, і наслі́дники Ца́рствія Небе́снаго нас соді́лайте, да зове́м вам ра́достно:","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци небе́снії воі́стину яви́стеся, блаже́ннії Пе́тре і Февро́ніє, от ю́ности ва́шея чи́стую со́вість іму́щії к Бо́гу, і до́брі во благоче́стії і чистоті́ вку́пі пожи́вшії, нам же оста́вльшії в примі́р подража́нія житіє́ ва́ше богоуго́дноє, єму́же чудя́щеся і чудеси́ ва́шими озаря́ємі, зове́м вам гла́си хвале́бними си́це:","Ра́дуйтеся, от ю́ности ва́шея Христа́ возлюби́вшії і Тому́ от душі́ порабо́тавшії;","ра́дуйтеся, цілому́дрія храни́тели і душе́вния і тіле́сния чистоти́ рачи́тели.","Ра́дуйтеся, ду́ші ва́ша і тілеса́ на землі́ в обита́лище Ду́ха Свята́го угото́вившії;","ра́дуйтеся, іспо́лненнії прему́дрості і ра́зума боже́ственнаго.","Ра́дуйтеся, я́ко во пло́ті, я́ко безпло́тни, вку́пі пожи́сте;","ра́дуйтеся, я́ко равноа́нгельную честь досто́йні прия́сте.","Ра́дуйтеся, я́ко от землі́ на Не́бо прейдо́сте і та́мо со А́нгели Тро́йце предстої́те;","ра́дуйтеся, я́ко со безпло́тними ли́ки трисвяту́ю піснь Єй воспіва́єте.","Ра́дуйтеся, на Небесі́ і на землі́ от Го́спода просла́вленнії;","ра́дуйтеся, обрі́тшії ві́чноє всесві́тлоє мі́сто упокоє́нія.","Ра́дуйтеся, гра́да Му́рома сокро́вища пребога́тая;","ра́дуйтеся, істо́чници неістощи́мії чуде́с.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 2","ps":["Ви́дів князь Петр во возвра́тной болі́зні своє́й, зна́меніє гні́ва Бо́жия, за неісполне́ніє обі́та своєго́, поя́ти в супру́ги себі́ прему́друю Февро́нію, потща́ся сіє́ іспо́лнити і сочета́ся с не́ю бра́ком зако́нним. Оба́че і в супру́жестві цілому́дренно і богоуго́дно пожи́сте, блаже́ннії, іму́ще єди́ну мисль во двою́ ті́лу, є́же благоугожда́ти Бо́гу; ті́мже ви́ну поє́те Єму́ ни́ні со А́нгели піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богопросвіще́нним сви́ше одаре́ннії, Пе́тре і Февро́ніє святі́ї, любо́в і милосе́рдіє к бі́дним і си́рим яви́сте, оби́димим і безпомо́щним засту́пниці би́сте, і іни́ми доброді́тельми мно́гими украси́сте княже́ніє своє́ земно́є. Сего́ ра́ди вопіє́м к вам си́це:","Ра́дуйтеся, блаже́ннії і треблаже́ннії, в боголю́бії пожи́вшії і благові́ріє сохра́ншії;","ра́дуйтеся, ми́лості і сострада́нія преіспо́лненнії.","Ра́дуйтеся, безпомо́щних ско́рії помо́щници;","ра́дуйтеся, печа́льних блазі́ї уті́шители.","Ра́дуйтеся, сиро́т і вдови́ць корми́тели;","ра́дуйтеся, су́щих в біда́х предста́телі.","Ра́дуйтеся, болі́зней душе́вних і тіле́сних іску́снії ціли́телі","ра́дуйтеся, ско́рбних серде́ць радостотво́рнії посети́телі.","Ра́дуйтеся, любо́во ва́шу к Бо́гу, любо́вію к бли́жнім свої́м показа́вшії;","ра́дуйтеся, княже́ніє ва́ше земно́є пра́ведно і богоуго́дно содержа́вшії.","Ра́дуйтеся, князе́й правосла́вних похвало́ і гра́да Му́рома утвержде́ніє;","ра́дуйтеся, всея́ землі́ Украї́нськая заступле́ніє.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жия укріпля́єм, блаже́нне кня́же Пе́тре, восхоті́л єси́ па́че оста́вити град оте́чества твоєго́ і княже́ніє Му́ромськоє, не́же бракоразвести́ся с прему́дрою Февро́нією по настоя́нію го́рдих боля́р твої́х. Сего́ ра́ди Бог тя просла́ви і сотвори́, да ті́миже боля́ри возвраще́нний вку́пі с супру́жницею твоє́ю, на престо́лі княже́нія Му́ромськаго па́ки утверди́лся єси́, нам же примі́р хране́нія зако́на Бо́жия показу́єши по́двигом твої́м, да подража́юще тебі́ в свя́тости хране́нія соу́за бра́чнаго, воспіва́єм подвигополо́жнику Христу́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще попече́ніє о лю́діх свої́х, преблаже́ннії Пе́тре і Февро́ніє, неуси́пно подвиза́стеся ко бла́гу їх, благоче́стіє насажда́я, нече́стіє іскореня́я і вражду́ умиротворя́я. Ті́мже і Госпо́дь, ви́дя такови́я по́двиги ва́ша, зе́млю Му́ромськую плодоно́сієм благослови́ і мир глубо́ко княже́нію ва́шему дарова́, подвиза́я лю́ди ва́ша благода́рственно воспіва́ти вам си́це:","Ра́дуйтеся, уго́дниці Бо́жії, житію́ вели́ких святи́х соприча́стници;","ра́дуйтеся, прави́теліє предо́брії, лю́ди му́ромськия ко спасе́нію путеводи́вшії.","Ра́дуйтеся, христия́нськаго благоче́стія блюсти́телі;","ра́дуйтеся, нестроє́нія, раздо́ров і вся́каго нече́стія іскорени́тели.","Ра́дуйтеся, супру́гов христия́н ко благоче́стному житію́ наста́вници;","ра́дуйтеся, цілому́дрія і воздержа́нія супру́жеськая о́бразі преізя́щнії.","Ра́дуйтеся, пра́веднаго суда́ рачи́тели;","ра́дуйтеся, немздої́мства і безкори́стія ревни́тели.","Ра́дуйтеся, святи́х царе́й Константи́на і Єле́ни доброді́телей стяжа́телі;","ра́дуйтеся, равноапо́стольнаго кня́зя Влади́мира і блаже́нния княги́ні О́льги досто́йнії преє́мници.","Ра́дуйтеся, дво́їце пречестна́я і благо́є сочета́ніє, луча́ми чуде́с немерца́ємо сія́ющії;","ра́дуйтеся, оте́чества ва́шего пресві́тлії світи́льници.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 4","ps":["Бу́ря скорбе́й і напа́стей, воздвиза́ємая зло́бою ми́ра сего́, не осла́би крі́пкую любве́ ва́шея я́же к Бо́гу, Пе́тре і Февро́ніє блаже́ннії, но па́че научи́ вас благоїску́сно отража́ти разжже́нния стрі́ли іскуше́ній дия́вольських: ви бо обо́лкшеся в броню́ ві́ри Христо́ви, в ми́рі глубо́ці прейдо́сте многом'яте́жную пучи́ну жите́йськаго мо́ря, і достиго́сте в ти́хую при́стань спасе́нія, к не́йже і нас моли́твами ва́шими приведі́те, да вку́пі с ва́ми поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше бли́жнії і да́льнії благоче́стноє житіє́ ва́ше, благові́рнії Пе́тре і Февро́ніє, прославля́ху человіколю́бця Бо́га, дарова́вшаго вам крі́пость на вся ді́ла блага́я, і́миже я́ко луча́ми пресві́тлими, просія́єте в оте́честві ва́шем, іді́же і дони́ні імена́ ва́ша че́стни, і по́двиги ва́ша воспева́ються похвала́ми си́ми:","Ра́дуйтеся, дво́їце пресві́тлая, Бо́гом совокупле́нная;","ра́дуйтеся, сві́том благоче́стнаго житія́ ва́шего, я́ко світи́ла богосві́тлая, просія́вшії.","Ра́дуйтеся, ми́лостинею і моли́твами Небе́сноє Ца́рствіє стяжа́вшії;","ра́дуйтеся, смире́нієм і поще́нієм ві́чноє блаже́нство улучи́вшії.","Ра́дуйтеся, я́ко мзда ва́ша мно́га на Небесі́х єсть;","ра́дуйтеся, я́ко ра́дость ва́ша ві́чна во сві́тлостіх святи́х.","Ра́дуйтеся, раби́ Христо́ви возлю́бленнії;","ра́дуйтеся, святи́х всіх при́снії дру́зі.","Ра́дуйтеся, зві́зди непреле́стнії, путь супру́жеськаго житія́ богоуго́днаго ві́рно указу́ющії;","ра́дуйтеся, о́блаці росоно́снії, зной страсте́й і нече́стія прогоня́ющії.","Ра́дуйтеся, Бо́жиїх ми́лостей і щедро́т нам пода́телі;","ра́дуйтеся, оте́чества ва́шего украше́ніє неот'є́млемоє.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 5","ps":["Богопросвеще́ннії світи́льници благоче́стія і преди́внії чудотво́рці Пе́тре і Февро́ніє, Бо́га от всея́ душі́ возлюби́вше, вся за́повіді Єго́ сохрани́сте; ті́мже і Христо́с, я́ко со́лнце і луну́ пресві́тлия, показа́ вас, преблаже́ннії, чуде́с мно́гих заре́ю озаря́ющия о́бласть Му́ромськую і всю страну́ Украї́нськую, просла́вив нетлі́нієм святи́я і многоціле́бния мо́щі ва́ша, к ни́мже припа́дающе, по достоя́нію ублажа́єм вас і ви́ну благода́рственно поє́м ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше житіє́ ва́ше пра́ведноє і щедро́ти ва́ша, лю́діє му́ромстії сла́вляху вас, свої́х прави́телей ми́лостивих, благові́рнії Пе́тре і Февро́ніє, ви же смире́ніє і́стинноє возлюби́вше і похвали́ челові́чеськія небре́гше, горди́нею неуя́звлени преби́сте, і тім показа́сте нам о́браз ви́шшаго смире́нія, єму́же поуча́яся, с любо́вію вопіє́м вам такова́я:","Ра́дуйтеся, сла́ву челові́чу ні во что же вміни́вшії;","ра́дуйтеся, смире́ніє Христо́во усе́рдно возлюби́вшії.","Ра́дуйтеся, за́повідей Госпо́дніх ві́рнії ісполни́тели;","ра́дуйтеся, уче́нія Єва́нгельськаго і́стиннії послі́дователі.","Ра́дуйтеся, раби́ Бо́га Ви́шняго, во́лю Єго́ сотво́ршії;","ра́дуйтеся, ві́ру Христо́ву до конця́ соблю́дшії.","Ра́дуйтеся, христоімени́тим лю́дем благоче́стія учи́тели;","ра́дуйтеся, хотя́щих богоуго́дно жи́ти богому́дрії наста́вници.","Ра́дуйтеся, моли́твами ва́шими спаса́ющії нас от вся́ких бід;","ра́дуйтеся, вся блага́я проше́нія на́ша ісполня́ющії.","Ра́дуйтеся, в неду́зіх стра́ждущих благода́тнії вра́чеве;","ра́дуйтеся, ми́лостивії страни́ Му́ромськия покрови́теліє.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 6","ps":["Пропові́дници ві́ри правосла́вния і ревни́тели благоче́стія не сло́вом то́кмо, но всім житіє́м свої́м би́сте во гра́ді Му́роме, прехва́льнії Пе́тре і Февро́ніє; ті́мже і свята́я Це́рков досто́йні почита́єть по́двиги і труди́ ва́ша, і́миже труди́стеся во сла́ву Бо́га Ви́шняго, немо́лчно воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́сте во гра́ді Му́роме сві́том доброді́тельнаго житія́ ва́шего, я́ко зві́зди богосві́тлия, преблаже́ннії Пе́тре і Февро́ніє, і па́м'ять ва́ша в нем с похвала́ми до днесь, я́ко і по сме́рті своє́й не престає́те озаря́ти нас, мно́гая чудеси́ соверша́юще, і ті́ми сві́тлую зарю́ безсме́ртія нам от моще́й ва́ших возсіява́юще, да ублажа́єм вас благохвале́ніями сицеви́ми:","Ра́дуйтеся, чи́на і уста́вов святи́я Це́ркве ві́рнії храни́тели;","ра́дуйтеся, служи́телей олтаря́ Госпо́дня благогові́йнії почита́телі.","Ра́дуйтеся, благи́х оби́чаєв і преда́ній святооте́чеських ревни́тели;","ра́дуйтеся, оби́чаєв злих і суєму́дрій язи́чеських іскорени́тели.","Ра́дуйтеся, суди́ нелицеприя́тни лю́дем ва́шим твори́вшії;","ра́дуйтеся, суди́ ва́ша с ми́лостію соєдини́вшії.","Ра́дуйтеся, кро́тції і незло́бивії послі́дователі Христо́ви;","ра́дуйтеся, зло́бу добро́м препобежда́вшії.","Ра́дуйтеся, нетлі́нія благоуха́ющії цві́ти;","ра́дуйтеся, безсме́ртія немерца́ющії лучи́.","Ра́дуйтеся, на землі́ вели́чієм чуде́с блиста́ющії;","ра́дуйтеся, на Небесі́ со А́нгели Бо́га сла́в'ящії.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 7","ps":["Хотя́й человіколю́бець Госпо́дь яви́ти в житії́ ва́шем, Пе́тре і Февро́ніє, о́браз назида́нія не то́кмо лю́дем мирськи́м, но і ли́ком і́ночеським, внуши́ вам в ста́рости масти́тій оста́вити сла́ву княже́нія земна́го, і восприя́ти о́браз і́ночеський, в не́мже подвиза́стеся до́брі посто́м, бді́нієм і моли́твою, воспіва́юще непреста́нно Трієди́ному Бо́гу а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую благода́ть Бо́жию во і́ночестім постриже́нії приє́мше, преподо́бнії, но́вими по́двигами украси́сте равноа́нгельноє житіє́ ва́ше і та́ко сугу́б плод соверше́нства духо́внаго Христу́ принесо́сте, і мзду преподо́бних досто́йні от Него́ восприя́сте. Помина́я у́бо такову́ю ре́вность ва́шу к по́двигом духо́вним, прославля́єм вас си́ми достодо́лжними похвали́:","Ра́дуйтеся, я́ко любве́ ра́ди Го́спода, ми́ра сего́ княже́ніє і сла́ву оста́висте;","ра́дуйтеся, я́ко і́ночеськоє равноа́нгельноє житіє́ усе́рдно восприя́сте.","Ра́дуйтеся, соверше́ннаго терпі́нія подви́жници;","ра́дуйтеся, во́льния нищети́ блаже́ннії стяжа́телі.","Ра́дуйтеся, пре́жде кончи́ни ва́шея вся стра́сті умертви́вшії воздержа́нієм;","ра́дуйтеся, восприя́вшії святу́ю схи́му в броню́ спасе́нія.","Ра́дуйтеся, багряни́цю кня́жеськую на власяни́цю і́ночеськую премени́вшії;","ра́дуйтеся, посто́м, бді́нієм і непреста́нними моли́твами Бо́гу до́брі угоди́вшії.","Ра́дуйтеся, боголюбе́знаго уєдине́нія взиска́телі;","ра́дуйтеся, спаси́тельнаго безмо́лвія люби́телі.","Ра́дуйтеся, слеза́ми моли́твенними ороша́ємі;","ра́дуйтеся, в со́нмі преподо́бних на Небесі́ просла́вленнії.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 8","ps":["Стра́нноє і ди́вноє бі чу́до, єгда́ ти, блаже́нне Пе́тре, на кончи́ні живота́ твоєго́, проше́нія ра́ди супру́жници твоєя́, святи́я Февро́нії, ісхо́дом свої́м уме́длил єси́, до́ндеже сконча́ она́ пелену́ церко́вную, є́ю сшива́єму і вку́пі с тобо́ю к ісхо́ду сме́ртному приспі́, і та́ко неразлу́чнії в житії́, неразлу́чнії в кончи́ні яви́стеся, і во єди́н день і час святи́я ду́ші своя́ в ру́ці Бо́жії преда́сте, зову́ще при́сно живи́ми і ме́ртвими облада́ющему Влади́ці Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Всі чудя́хуся і сла́вляху ди́внаго во святи́х Свої́х Бо́га, єгда́ святи́я ва́ша тілеса́, в ра́зних гробі́х положе́нная, чуде́сно обріто́шася лежа́ща в о́бщей гробни́ці, ю́же угото́васті себі́, преподо́бнії, в собо́рній це́ркві гра́да Му́рома, іді́же і дони́ні неразлу́чно почива́єте, чудотво́рці святі́ї, неоску́дния істоча́юще ісціле́нія всім, с ві́рою прибега́ющим к вам і зову́щим:","Ра́дуйтеся, сою́з любве́ ва́шея до гро́ба і за гро́бом ві́рно сохра́ншії;","ра́дуйтеся, не то́кмо в жи́зні, но і по сме́рті, о Го́споді соєдине́ннії.","Ра́дуйтеся, в супру́жестем благоче́стнім житії́ вам подража́ющим крі́пції помо́щници;","ра́дуйтеся, теплото́ю любве́ ва́шея і нас согрева́ющії.","Ра́дуйтеся, сме́ртію вре́менною преше́дшії к жи́зні ві́чній;","ра́дуйтеся, от Го́спода нетлі́нієм і чудеси́ просла́вленнії.","Ра́дуйтеся, я́ко па́м'ять ва́ша с похвала́ми і успе́ніє со святи́ми;","ра́дуйтеся, я́ко імена́ ва́ша че́стна суть і благослове́нна в оте́честві ва́шем.","Ра́дуйтеся, Украї́нськия страни́ удобре́ніє благода́тноє;","ра́дуйтеся, гра́да Му́рома огражде́ніє несокруши́моє.","Ра́дуйтеся, о лю́б'ящих і чту́щих вас небе́снії предста́телі;","ра́дуйтеся, приснопрося́щії нам у Го́спода да́ри бла́гости Єго́.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 9","ps":["Всі А́нгели і святи́х ли́ки ра́довахуся ра́достію ве́лію, єгда́ святи́я ду́ші ва́ша достиго́ша ві́чнаго в оби́теліх ра́йських селе́нія, і Сам Творе́ць А́нгелов і Святі́йший святи́х Цар Сла́ви Христо́с, безсме́ртія вінці́ увінча́ вас і дарова́ вам благода́ть моли́тися Єму́ со дерзнове́нієм мно́гим о всіх і́щущих ва́шего заступле́нія, єго́же не лиші́те і нас грі́шних, Пе́тре і Февро́ніє достохва́льнії, смиренному́дренно воспіва́ющих просла́вльшему вас Бо́гу хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство челові́чеськоє не довлі́єть к досто́йному прославле́нію ди́внаго житія́ ва́шего, святі́ї чудотво́рці Пе́тре і Февро́ніє; кто бо іспові́сть вся моле́нія і поще́нія, болі́зні і труди́ ва́ша? Кто ізочте́ть вся сле́зи і воздиха́нія ва́ша я́же к Бо́гу? Оба́че ми любо́вію к вам подвиза́ємі, дерза́єм воспіва́ти вам сія́ ма́лия і нехи́тростния похвали́:","Ра́дуйтеся, благода́ті Свята́го Ду́ха ізбра́ннії сосу́ди;","ра́дуйтеся, ра́дости нам ві́чния благоприя́тнії хода́таї.","Ра́дуйтеся, богобоя́зненних супру́гов в благоче́стії утвержде́ніє;","ра́дуйтеся, наруши́телей супру́жеськаго цілому́дрія і согла́сія гро́зноє обличе́ніє.","Ра́дуйтеся, гнів Бо́жий, пра́ведно дви́жимий на нас, моли́твами ва́шими утоля́ющії;","ра́дуйтеся, о ми́рі всего́ ми́ра непреста́нно Го́спода умоля́ющії.","Ра́дуйтеся, на враги́ ви́димия і неви́димия крі́пції нам спобо́рници;","ра́дуйтеся, ангелонра́внії челові́ци.","Ра́дуйтеся, преподо́бних і пра́ведних сонасле́дници;","ра́дуйтеся, Пресвяти́я Тро́йці ві́рнії уго́дниці.","Ра́дуйтеся, блаже́ннії обита́телі го́рняго гра́да Ієрусали́ма Небе́снаго;","ра́дуйтеся, со святи́ми торжеству́ющії в ски́ніях ра́йських.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 10","ps":["Спасе́ніє ві́чноє унасле́довавше богоблаже́ннії Пе́тре і Февро́ніє, душа́ми ва́шими в оби́теліх го́рніх неразлу́чно в Бо́зі пребива́єте, святи́ми же моща́ми ва́шими в хра́мі Бо́жиєм нетлі́нно вку́пі почива́єте, і оби́льния ісціле́нія істоча́єте, да чудеси́ ва́шими благода́тно озаря́ємі, хвале́бно взива́єм Верхо́вному Творцю́ чуде́с Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ну заступле́нія, благоприя́тния моли́тви ва́ша к Бо́гу, обрі́тше, святі́ї чудотво́рці Пе́тре і Февро́ніє, благодаре́ніє Отцю́ Небе́сному усе́рдно возсила́єм за вся благодія́нія Єго́, ва́ми всім нам оби́льно явля́ємая, вам же, предста́телям на́шим, сицево́є прино́сим пі́ніє:","Ра́дуйтеся, всесві́тлаго Ца́рствія Христо́ва наслі́дници;","ра́дуйтеся, а́нгельських лико́в собесі́дниці.","Ра́дуйтеся, Бо́га во сла́ві непристу́пній созерца́ющії;","ра́дуйтеся, Трисія́ннаго Божества́ таї́нници.","Ра́дуйтеся, со святи́ми на Небесі́ ві́чно ца́рствующії;","ра́дуйтеся, от го́рних висо́т к земноро́дним ми́лостивно приника́ющії.","Ра́дуйтеся, кри́ни благоуха́ннії небе́снаго прозябе́нія;","ра́дуйтеся, кипари́си чудото́чнії рая́ Ісу́сова.","Ра́дуйтеся, пода́телі незави́стнії безме́зднаго врачева́нія;","ра́дуйтеся, соверши́тели достохва́льнії мно́гих чуде́с.","Ра́дуйтеся, благодія́ній мно́жество нам істоча́ющії;","ра́дуйтеся, ми́лостію сострада́нія ва́шего всіх об'є́млющії.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє прино́сим вам, уго́дниці Бо́жії Пе́тре і Февро́ніє, і с любо́вію припа́даєм к ра́ці святи́х і многоціле́бних моще́й ва́ших, прославля́я житіє́ ва́ше богоуго́дноє і по́двиги мно́гі. Мо́лимся вам усе́рдно, чудотво́рці святі́ї, помозі́те нам подража́ти ва́шим доброді́телем, да возмо́жем богоуго́дно пі́ти Созда́телю на́шему: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́та небе́снаго іспо́лнен бі собо́рний храм гра́да Му́рома, єгда́ благоволе́нієм Бо́жиїм святи́я мо́щі ва́ша Пе́тре і Февро́ніє, ці́ли і благоуха́нни обріто́шася в нем, і із нідр земни́х, я́ко сокро́вище драгоці́нноє, ізнесе́ни би́ша, іді́же і до ни́ні почива́ють, ісціле́нія неоску́дния істоча́юще неду́жним і боля́щим. Сего́ ра́ди пі́сненно вопіє́м к вам:","Ра́дуйтеся, зла́то нетлі́нноє, в ні́дріх земни́х обрі́тенноє;","ра́дуйтеся, би́сері сія́ющії і благода́тно просвіща́ющії челові́ков.","Ра́дуйтеся, святи́я Правосла́вния Це́ркве похвало́;","ра́дуйтеся, єресе́й і раско́лов обличе́ніє.","Ра́дуйтеся, сві́ти у́мнії, заре́ю Свята́го Ду́ха облиста́ющії;","ра́дуйтеся, ми́ра благоуха́нія Христо́ва преіспо́лненнії.","Ра́дуйтеся, облече́ннії в ри́зу благода́тного нетлі́нія;","ра́дуйтеся, препоя́саннії си́лою мно́гих чуде́с.","Ра́дуйтеся, я́ко ра́ка ва́ша честна́я враче́бниця яви́ся неду́гом челові́чеським;","ра́дуйтеся, я́ко от нея́ всяк с ві́рою приходя́й да́ри ціле́бния приє́млеть.","Ра́дуйтеся, сві́тлостію чуде́с ва́ших мрак душ на́ших озаря́ющії;","ра́дуйтеся, нетлі́нієм святи́х моще́й ва́ших зарю́ о́бщаго всіх воскресе́нія нам показу́ющії.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 12","ps":["Благода́ть сви́ше вам дарова́нную, позна́вше, святі́ї чудотво́рці Пе́тре і Февро́ніє, с благогові́нієм і любо́вію покланя́ємся нетлі́нним і многоціле́бним моще́м ва́шим і от них приє́млем в неду́зіх ісціле́ніє, в ско́рбіх утіше́ніє, в біда́х благода́тную по́мощ: ті́мже і прославля́єм вас по достоя́нію, небе́сних предста́телей і засту́пников на́ших, воспіва́юще хвали́ і благодаре́нія ва́ми благотворя́щему нам Влади́ці Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще мно́гая і пресла́вная ва́ша чудеса́, вели́ції уго́дниці Бо́жії Пе́тре і Февро́ніє, ублажа́єм вас, я́ко ціли́телей, уті́шителей і помо́щников от Го́спода нам дарова́нних, і моли́твенно торжеству́єм святу́ю па́м'ять ва́шу, от любве́ серде́чния воспіва́юще вам благода́рственно і хвале́бно:","Ра́дуйтеся, во благоуха́нії святи́ні нетлі́нно почива́ющії;","ра́дуйтеся, с ві́рою приходя́щих к ра́ці моще́й ва́ших благода́тно освяща́ющії.","Ра́дуйтеся, призива́ющих моли́твенно честна́я імена́ ва́ша ско́рії усли́шателі;","ра́дуйтеся, упова́ніє на вас по Бо́зі возлага́ющих ди́внії помо́щници.","Ра́дуйтеся, ізві́стнії умилостиви́тели Царя́ Небе́снаго;","ра́дуйтеся, си́льнії защи́тници на́ші от враго́в неви́димих.","Ра́дуйтеся, при́снії всім нам хода́таї спасе́нія;","ра́дуйтеся, неотсту́пнії храни́тели гра́да Му́рома.","Ра́дуйтеся, князе́й украї́нських пречу́дная добро́то;","ра́дуйтеся, оте́чества ва́шего Бо́гом дарова́ннії покрови́телі.","Ра́дуйтеся, тіле́с на́ших благода́тнії целе́бници;","ра́дуйтеся, о душа́х на́ших усе́рднії ко Го́споду моли́твенниці.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 13","ps":["О святі́ї і пресла́внії чудотво́рці, благові́рнії кня́же Пе́тре і княги́не Февро́ніє! Приймі́те ми́лостивно сіє́ похва́льноє пі́ніє от нас недосто́йних во умиле́нії вам приноси́моє, і ва́шим предста́тельством у Го́спода іспросі́те нам утвержде́ніє во ві́рі і до́брих ді́ліх, і ізбавле́ніє от всіх скорбе́й і болі́зней вре́менних і ві́чних, да сподо́бимся вку́пі с ва́ми і всі́ми святи́ми во Ца́рствії Небе́снім пі́ти Пресвяті́й Тро́йце ві́чно хвале́бную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели земні́ї і челові́ци небе́снії воі́стину яви́стеся, блаже́ннії Пе́тре і Февро́ніє, от ю́ности ва́шея чи́стую со́вість іму́щії к Бо́гу, і до́брі во благоче́стії і чистоті́ вку́пі пожи́вшії, нам же оста́вльшії в примі́р подража́нія житіє́ ва́ше богоуго́дноє, єму́же чудя́щеся і чудеси́ ва́шими озаря́ємі, зове́м вам гла́си хвале́бними си́це:","Ра́дуйтеся, от ю́ности ва́шея Христа́ возлюби́вшії і Тому́ от душі́ порабо́тавшії;","ра́дуйтеся, цілому́дрія храни́тели і душе́вния і тіле́сния чистоти́ рачи́тели.","Ра́дуйтеся, ду́ші ва́ша і тілеса́ на землі́ в обита́лище Ду́ха Свята́го угото́вившії;","ра́дуйтеся, іспо́лненнії прему́дрості і ра́зума боже́ственнаго.","Ра́дуйтеся, я́ко во пло́ті, я́ко безпло́тни, вку́пі пожи́сте;","ра́дуйтеся, я́ко равноа́нгельную честь досто́йні прия́сте.","Ра́дуйтеся, я́ко от землі́ на Не́бо прейдо́сте і та́мо со А́нгели Тро́йце предстої́те;","ра́дуйтеся, я́ко со безпло́тними ли́ки трисвяту́ю піснь Єй воспіва́єте.","Ра́дуйтеся, на Небесі́ і на землі́ от Го́спода просла́вленнії;","ра́дуйтеся, обрі́тшії ві́чноє всесві́тлоє мі́сто упокоє́нія.","Ра́дуйтеся, гра́да Му́рома сокро́вища пребога́тая;","ра́дуйтеся, істо́чници неістощи́мії чуде́с.","Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці і вели́ції уго́дниці Госпо́дні, гра́да Му́рома засту́пниці і при́снії о душа́х на́ших моли́твенниці, святі́ї благові́рнії кня́же Пе́тре і княги́не Февро́ніє! Пі́ніє похва́льноє вам принося́ще, мо́лим ви усе́рдно: я́ко іму́щії дерзнове́ніє ко Го́споду, предста́тельством ва́шим от вся́ких бід нас свободи́те, і наслі́дники Ца́рствія Небе́снаго нас соді́лайте, да зове́м вам ра́достно: Ра́дуйтеся, святі́ї і пресла́внії чудотво́рці Пе́тре і Февро́ніє."]},{"h":"Молитва перша","ps":["О вели́ції уго́дниці Бо́жії і преди́внії чудотво́рці благові́рнії кня́же Пе́тре і княги́не Февро́ніє, гра́да Му́рома предста́телі і храни́тели, і о всіх нас усе́рднії ко Го́споду моли́твенниці! К вам прибіга́єм і вам мо́лимся с упова́нієм крі́пким: принесі́те за нас грі́шних святи́я моли́тви ва́ша ко Го́споду Бо́гу і іспросі́те нам у бла́гости Єго́ вся благопотре́бная душа́м і тілесе́м на́шим: ві́ру пра́ву, наде́жду бла́гу, любо́в нелицемі́рну, благоче́стіє непоколеби́моє, в до́брих ді́ліх преуспі́яніє, ми́ра умире́ніє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, душа́м і тілесе́м здра́віє і ві́чноє спасе́ніє. Ісхода́тайствуйте у Царя́ Небе́снаго: ві́рних рабо́в Єго́, в ско́рбі і печа́лі день і нощ вопію́щих к Нему́, многоболі́зний вопль да усли́шить і да ізведе́ть от поги́белі живо́т наш. Іспросі́те Це́ркві святі́й і всей держа́ві Украї́нській мир, тишину́ і благоустроє́ніє, і всім нам житіє́ благополу́чноє і до́брую христия́нськую кончи́ну. Огради́те оте́чество ва́ше, град Му́ром, і вся гра́ди Украї́нськия от вся́каго зла і вся правові́рния лю́ди, к вам приходя́щия і моще́м покланя́ющіяся, осіні́те благода́тним ді́йством благоприя́тних моли́тв ва́ших, і вся проше́нія їх во бла́го іспо́лніте. Єй, чудотво́рці святі́ї! Не пре́зріте моли́тв на́ших, со умиле́нієм вам возноси́мих, но бу́діте о нас при́снії предста́телі ко Го́споду і сподо́біте нас по́мощію ва́шею свято́ю спасе́ніє ві́чноє получи́ти і Ца́рствіє Небе́сноє унаслі́довати; да славосло́вим неізрече́нноє человіколю́біє Отця́, і Си́на, і Свята́го Ду́ха, в Тро́йці покланя́ємаго Бо́га, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О уго́дниці Бо́жії, благові́рнії кня́же Пе́тре і княги́не Февро́ніє, к вам прибіга́єм і к вам со упова́нієм крі́пким мо́лимся: вознесі́те о нас, грі́шних (імена), святи́я моли́тви ва́ші ко Го́споду Бо́гу і іспросі́те у бла́гости Єго́ вся благопотре́бная душа́м і тілесе́м на́шим: ві́ру пра́ву, наде́жду бла́гу, любо́в нелицемі́рну, благоче́стіє непоколеби́мо, в до́брих ді́ліх преуспі́яніє. І хода́тайствуйте нам у Царя́ Небе́снаго житіє́ благополу́чноє і до́брую христия́нськую кончи́ну. Єй, чудотво́рці святі́ї! Не пре́зріте моли́тв на́ших, но бу́діте о нас при́снії предста́теліє ко Го́споду, і сподо́біте нас по́мощію ва́шею спасе́ніє ві́чноє получи́ти і Ца́рствіє Небе́сноє унаслі́довати, да славосло́вим неізрече́нноє человіколю́біє Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці покланя́ємаго Бо́га во ві́ки віко́в."]},{"h":"Тропар, глас 8","ps":["Я́ко благочести́ваго ко́рене пречестна́я о́трасль бил єси́, / до́брі во благоче́стії пожи́в, блаже́нне Пе́тре, / та́ко і с супру́жницею твоє́ю прему́дрою Февро́нією, / в ми́рі Бо́гу угоди́вше, і преподо́бних житію́ сподо́бистеся. / С ни́миже молі́теся Го́сподеві, / сохрани́ти без вреда́ оте́чество ва́ше, // да вас непреста́нно почита́єм."]},{"h":"Кондак, глас 8","ps":["Ми́ра сего́ княже́ніє і сла́ву вре́менну помишля́я, / сего́ ра́ди благоче́стно в ми́рі пожи́л єси́, Пе́тре, / ку́пно і с супру́жницею твоє́ю прему́дрою Февро́нією, / ми́лостинею і моли́твами Бо́гу угоди́вше. / Ті́мже і по сме́рті неразлу́чно во гро́бі лежа́ще, / ісціле́ніє неви́димо подава́єте, / і ни́ні Христу́ молі́теся // сохрани́ти град же і лю́ди, і́же вас сла́в'ящих."]},{"h":"Величання","ps":["Ублажа́єм вас, святі́ї чудотво́рці Пе́тре і Февро́ніє, і чтим святу́ю па́м'ять ва́шу, ви бо мо́лите за ни Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому мученику Іоанну Воїну","e":"Akathist to the Holy Martyr John the Warrior","secs":[{"h":"Кондак 1","ps":["Ізбра́ннаго раба́ Царя́ Небе́снаго, до́бляго Христо́ва страстоте́рпця, Іоа́нна свята́го Во́їна і чудотво́рця похва́льними пі́сньми воспої́м, я́ко христия́н засту́пника, цілому́дрія блюсти́теля, стра́ждущих уті́шителя. Ти же, предстоя́ Престо́лу Святи́я Тро́йці, моли́твами свої́ми от вся́ких зол і напа́стей охраня́й с ві́рою і любо́вію зову́щих ті:","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели с любо́вію зря́ху на равноа́нгельськоє житіє́ твоє́, Іоа́нне пречу́дне, ти бо, пеки́йся о Госпо́дніх, ка́ко угоди́ти Го́сподеві, сохрани́л ді́вство неврежде́нно, посто́м і моли́твою умерщвля́я плоть свою́ день і нощ. Ми же таково́му житію́ твоєму́ див'я́щеся, со умиле́нієм взива́єм ті си́це:","Ра́дуйся, чистоту́ се́рдця своєго́ сохрани́вий;","ра́дуйся, я́ко сего́ ра́ди Бо́га узрі́ти сподо́бился єси́.","Ра́дуйся, і́го Христо́во на ра́мо своє́ взе́мшій;","ра́дуйся, ду́шу свою́ Христа́ ра́ди погуби́вий, во є́же спасти́ ю.","Ра́дуйся, А́нгелов сожи́телю;","ра́дуйся, ді́вственников похвало́.","Ра́дуйся, храни́телю і наста́вниче ю́них отроко́в;","ра́дуйся, ско́рий помо́щниче борю́щимся со страстьми́ і похотьми́.","Ра́дуйся, защи́тниче дів і вдови́ць;","ра́дуйся, обличе́ніє наруши́телей цілому́дрія.","Ра́дуйся, роди́телей і воспита́телей наста́вниче;","ра́дуйся, сиро́тствующих незри́мий води́телю.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя святи́й Іоа́нн, єгда́ при́йде в Ну́мери Іфа́льськия, христия́ни гони́ми, не убоя́ся преще́ній нечести́ваго Іулія́на і рече́ їм: мужа́йтеся, укріпля́йтеся во ві́рі, да сподо́бітеся ви́ну воспіва́ти в Небе́сних черто́зіх Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум несумне́нний імі́л єси́ в себі́, Іоа́нне достохва́льне, єгда́ сла́ву ми́ра сего́ презрі́в і гні́ва ца́рськаго не устраши́вся, іспові́дал себі́ христия́нина би́ти, і сего́ ра́ди, я́ко злоді́й, в темни́цю всажде́н бил єси́. Таково́му твоєму́ о Христі́ дерзнове́нію див'я́щеся, глаго́лем:","Ра́дуйся, іспові́дниче Христо́в преізря́дний;","ра́дуйся, Христу́ спострада́вий.","Ра́дуйся, і́дольськаго служе́нія пре́лесть обличи́вий;","ра́дуйся, си́лою Креста́ врага́ побіди́вий.","Ра́дуйся, я́ко у́зи і темни́цю за Христа́ прия́ти сподо́бился єси́;","ра́дуйся, я́ко хлад і наготу́ за Христа́ предпоче́л єси́ сла́ві гріхо́вній.","Ра́дуйся, іспові́дников похвало́;","ра́дуйся, му́чеников ра́дованіє.","Ра́дуйся, в земни́х во́їніх до́блій во́їн Царя́ Небе́снаго;","ра́дуйся, убели́вий ри́зи своя́ в Кро́ві А́гнчей.","Ра́дуйся, Це́ркве Христо́ви защи́тниче;","ра́дуйся, всіх правосла́вних засту́пниче.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою сви́ше препоя́санний возмо́гл єси́ побіди́ти дре́вняго змі́я; то́южде си́лою одаре́нний, істоча́єши оби́ліє чуде́с всім призива́ющим с ві́рою і́м'я твоє́ і о тебі́ благода́рні вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в се́рдці своє́м тве́рдую ві́ру во Христа́ і си́лою тоя́ вооружи́вся, не убоя́лся єси́ гні́ва царе́ва і сохраня́л єси́ іфа́льськия лю́ди от мучи́телей. Сего́ ра́ди таково́є му́жество твоє́ похваля́юще, блажи́м тя си́це:","Ра́дуйся, адама́нте ві́ри Христо́ви;","ра́дуйся, сто́лпе Це́ркве Бо́жия.","Ра́дуйся, ві́рних наде́ждо і заступле́ніє;","ра́дуйся, неві́рних страх і посрамле́ніє.","Ра́дуйся, віне́ць іспові́дника Христо́ва стяжа́вий;","ра́дуйся, ору́жієм Креста́ врага́ Христо́ва низложи́вий.","Ра́дуйся, Христа́ па́че ми́ра возлюби́вий;","ра́дуйся, за христия́ни ду́шу свою́ положи́вий.","Ра́дуйся, за́мисли богоме́рзькаго мучи́теля разсі́явий;","ра́дуйся, я́ко в темни́ціх су́щих і во у́зех посіща́л єси́.","Ра́дуйся, я́ко і сам за Христа́ в темни́цю всажде́н бил єси́;","ра́дуйся, я́зви Го́спода своєго́ на ті́лі носи́вий.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рею помишле́ній сумни́тельних колеба́шеся блаже́нний Іоа́нн, єгда́ по́слан бисть в Ну́мери Іфа́льськия, да му́чить та́мо ве́рующия во Христа́. «А́ще у́бо, - глаго́лаше, - по повелі́нію царе́ву і́мам благові́рния лю́ди му́чити і убива́ти, осужде́н бу́ду от Бо́га, а́ще же не іду́ та́мо, в чи́ні во́їнства моєго́ обря́щуся царю́ проти́вен і преда́н бу́ду сме́рті лю́тій». Оба́че стра́хом Бо́жиїм води́мий, ві́ру Христо́ву в се́рдці своє́м сохрани́л да́же до злострада́ній і уз темни́чних, вопія́ Христу́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав нечести́вий Іулія́н твоє́ ко христия́ном милосе́рдіє і уві́дів тя самаго́ христия́нина би́ти, раз'яри́ся на тя зло́бою і повелі́ привести́ в Царгра́д, я́ко злоді́я і проти́вника царе́ва. Ти же, благода́тію Бо́жиєю укріпля́єм, страда́нія претерпі́л єси́ му́жественно і от ві́ри во Христа́ ніка́коже отступи́л єси́. Сего́ ра́ди велича́єм тя си́це:","Ра́дуйся, іспові́дниче ві́ри во Христа́ неустраши́мий;","ра́дуйся, во́їне Христо́в непобіди́мий.","Ра́дуйся, я́ко со Архистрати́гами Сил Небе́сних Престо́лу Бо́жию предстої́ши;","ра́дуйся, ско́рий помо́щниче всім за і́стину терп'я́щим.","Ра́дуйся, іскуше́ній і собла́знов от дия́вола ізбе́гнувий;","ра́дуйся, я́ко і всіх призива́ющих тя от іскуше́ній ізбавля́єши.","Ра́дуйся, за́мисли богоме́рзькаго мучи́теля разсі́явий;","ра́дуйся, і нам сі́ті дия́вола ізбіга́ти помога́ющий.","Ра́дуйся, щито́м ві́ри себ'я́ самаго́ от стріл лука́ваго защити́вий;","ра́дуйся, і́мже і нас от іскуше́ній охраня́ющий.","Ра́дуйся, христия́нськаго ро́да украше́ніє;","ра́дуйся, Небе́сних черто́гов обита́телю.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ подо́бен бил єси́, Іоа́нне, єгда́, прише́д в страни́ Іфа́льськия, увіща́л єси́ та́мо су́щих христия́н не отступа́ти от Со́лнця Пра́вди Христа́ Бо́га, но ви́ну пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя святи́й приводи́мия пред него́ по повелі́нію царе́ву ві́рния Христу́ лю́ди на муче́ніє за ві́ру Христо́ву, зіло́ скорбе́ за них, в се́рдці своє́м пеки́йся, да ізба́вить їх от руки́ мучи́телеви. Таково́є твоє́ попече́ніє о них похваля́юще, зове́м ті:","Ра́дуйся, любо́в Христо́ву в се́рдці своє́м імі́вий;","ра́дуйся, я́ко то́ю согрева́єм от мучи́телей ві́рния раби́ Христо́ви спаса́л єси́.","Ра́дуйся, велі́нія нечести́вих презрі́вий;","ра́дуйся, за́повіді Христо́ви сохрани́вий.","Ра́дуйся, ві́рних рабо́в Христо́вих дру́же;","ра́дуйся, христия́н засту́пниче.","Ра́дуйся, су́щим в темни́ціх і во у́зех уті́шителю;","ра́дуйся, ни́щих корми́телю.","Ра́дуйся, стра́нних води́телю;","ра́дуйся, немощству́ющих врачу́.","Ра́дуйся, засту́пниче си́рих;","ра́дуйся, пла́чущих уті́шителю.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Посто́м і моли́твою плоть твою́ ду́хові порабо́тил єси́ і во сла́ву Бо́жию духо́вні пожи́л єси́; сего́ ра́ди ни́ні предстої́ши Престо́лу Пресвяти́я Тро́йці, ви́ну воспіва́я піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко но́воє світи́ло на тве́рди небе́сній, всему́ христия́нському ро́ду, єгда́ Бо́жиїм ізволе́нієм обрі́тено бисть нетлі́нноє ті́ло твоє́, істоча́ющеє оби́ліє чуде́с с ві́рою к твоєму́ заступле́нію притека́ющим і моли́твенно тебі́ взива́ющим:","Ра́дуйся, Бо́гу житіє́м твої́м угоди́вий;","ра́дуйся, сего́ ра́ди от Него́ прославле́ніє прия́вий.","Ра́дуйся, тщету́ і пре́лесть ми́ра сего́ презрі́вий;","ра́дуйся, мзду Небе́сную восприя́вий.","Ра́дуйся, я́ко о ма́лі ві́рен яви́лся єси́;","ра́дуйся, я́ко оби́ліє благода́ті Бо́жієй прия́ти сподо́бился єси́.","Ра́дуйся, я́ко в житії́ сем бли́жняго самоотве́рженно возлюби́л єси́;","ра́дуйся, я́ко в ско́рбіх і напа́стіх су́щим засту́пник бил єси́.","Ра́дуйся, ду́шу свою́ за дру́ги полага́вий;","ра́дуйся, те́плий хода́таю за нас у Царя́ Небе́снаго.","Ра́дуйся, от мучи́телева гні́ва христия́ни спаса́вий;","ра́дуйся, я́ко і днесь о спасе́нії на́шем пече́шися.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́щу ті от ми́ра сего́ пресели́тися, смиренному́дрієм побужда́єм, повелі́л єси́ ні́коєму челові́ку ті́ло твоє́ положи́ти в до́мі, іді́же стра́ннії і ни́щії погреба́хуся. Госпо́дь же, смире́нния вознося́й, благоволи́ сохрани́ти о́ноє нетлі́нно і чудотворе́нія істоча́ющеє всем ко твоєму́ заступле́нію с ві́рою притека́ющим і о тебі́ Бо́гу вопію́щим: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ ми́лость рабо́м Свої́м Человіколю́бець Госпо́дь, єгда́ благоволи́ просла́вити тя і яви́ти в тебі́ благода́ть Свою́ чудотворя́щу. Ми же таково́му промишле́нію Бо́жию ра́дующеся, благода́рні вопіє́м:","Ра́дуйся, вмісти́лище благода́ті Бо́жієй;","ра́дуйся, сосу́де Бо́жий ізбра́нний.","Ра́дуйся, чудотво́рче преди́вний;","ра́дуйся, притека́ющим к тебі́ с ві́рою ско́рую по́мощ подава́яй.","Ра́дуйся, душе́вних і тіле́сних неду́гов на́ших ціли́телю;","ра́дуйся, бісо́в о і́мені Христо́ві ізгони́телю.","Ра́дуйся, лука́вство врага́ челові́чеськаго обличи́телю;","ра́дуйся, цілому́дрія охрани́телю.","Ра́дуйся, благочести́вих супру́жеств от вся́каго дия́вольськаго прельще́нія незри́мая огра́до;","ра́дуйся, татьби́ і граби́тельства ско́рий обличи́телю.","Ра́дуйся, соврати́вшихся на путь і́стини наста́вителю;","ра́дуйся, проше́нія на́ша на по́льзу ісполня́яй.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє і ди́вноє явле́ніє твоє́ чрез со́нноє виді́ніє ні́коєй жені́ благогове́йней уве́девшей і но́ваго чудотво́рця і уго́дника Бо́жія в тебі́ позна́вшей, лю́діє константино́польстії умили́шася і возопи́ша Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь доброді́тельми іспо́лненний в жи́зні сей, по сме́рті же сла́вою Бо́жиєю озаре́нний, преклоня́єши у́хо твоє́ на моли́тви чту́щих тя, от ни́хже сли́шиши сицева́я:","Ра́дуйся, милосе́рдію Отця́ Небе́снаго подража́телю;","ра́дуйся, а́лчущих пита́телю.","Ра́дуйся, стра́нних неви́димий сопу́тниче;","ра́дуйся, си́рих покрови́телю.","Ра́дуйся, озлобля́ємих уті́шителю;","ра́дуйся, за і́стину терп'я́щих подкрепи́телю.","Ра́дуйся, неду́гующим осла́бу і ісціле́ніє подава́яй;","ра́дуйся, в біда́х су́щих засту́пниче.","Ра́дуйся, ни́щія возлюби́вий;","ра́дуйся, я́ко с ни́ми і по отше́ствії от ми́ра сего́ ті́лом разлучи́тися не восхоті́л єси́.","Ра́дуйся, я́ко в до́мі убо́гих погребсти́ ті́ло своє́ завіща́л єси́;","ра́дуйся, за смиренному́дріє твоє́ вінце́м от Бо́га увінча́нний.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Все во́їнство а́нгельськоє возра́довашеся, ви́дя тя, во́їна Царя́ Небе́снаго непреобори́ма, побіди́вша миродержи́теля тьми і пре́лести ві́ка сего́, ті́мже і воспі́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії не возмо́гуть по достоя́нію восхвали́ти страда́нія твоя́, за Христа́ претерпе́нния, і милосе́рдія і цілому́дрія твоєго́ по́двиги. Ми же такови́м див'я́щеся, в не́мощі на́шей ма́лия сія́ хвале́нія прино́сим тебі́:","Ра́дуйся, Христа́ всім се́рдцем возлюби́вий;","ра́дуйся, во́льная страда́нія за І́м'я Єго́ претерпі́вий.","Ра́дуйся, о Бо́зі Вседержи́теле поревнова́вий;","ра́дуйся, віне́ць му́ченичеський стяжа́вий.","Ра́дуйся, пра́вило ві́ри і воздержа́нія учи́телю;","ра́дуйся, нищету́ духо́вную прояви́вий.","Ра́дуйся, смиренному́дрієм твої́м ду́ха горди́ні низложи́вий;","ра́дуйся, наслі́діє Ца́рства Небе́снаго стяжа́вий.","Ра́дуйся, в дому́ Отця́ Небе́снаго оби́тель себі́ сотвори́вий;","ра́дуйся, я́ко о спасе́нії на́шем при́сно хода́тайствуєши.","Ра́дуйся, по́мощ ско́рую прося́щим подава́яй;","ра́дуйся, я́ко немо́лчно мо́лиши за ни Христа́ Бо́га.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу свою́, презрі́л єси́ велі́нія мучи́теля, і о ті́лі своє́м неради́в, ра́достно восприя́л єси́ у́зи желі́зния і темни́чную скорб, Іоа́нне, Христо́во Во́їне, воспіва́я укрепля́вшему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і тве́рдоє прибі́жище всім с моли́твою к тебі́ прибега́ющим, чудотво́рче Іоа́нне, сего́ ра́ди зове́м ті:","Ра́дуйся, ско́рий послу́шниче всіх призива́ющих тя;","ра́дуйся, я́ко честни́я мо́щі твоя́ благоволи́ Бог просла́вити чудеси́.","Ра́дуйся, я́ко і от іко́н твої́х подає́ться благода́ть Бо́жия взира́ющим на них с ві́рою;","ра́дуйся, я́ко в созда́нних на прославле́ніє і́мене твоєго́ хра́міх незри́мо обита́єши.","Ра́дуйся, я́ко нікто́же та́мо с ві́рою моля́щийся тощ і неусли́шан ісхо́дить;","ра́дуйся, я́ко моли́твами твої́ми подкрепля́єши на́ша моле́нія, ко Престо́лу Вседержи́теля восходя́щия.","Ра́дуйся, я́ко коєго́ждо проше́нія предвари́ти тщи́шися;","ра́дуйся, я́ко на стро́потнім путі́ гріха́ іду́щим вразумле́нія подає́ши.","Ра́дуйся, я́ко іскуша́ємим от дия́вола ско́рую по́мощ явля́єши;","ра́дуйся, я́ко всіх ідти́ на путь спасе́нія направля́єши.","Ра́дуйся, я́ко грі́шния на покая́ніє наставля́єши;","ра́дуйся, уго́дниче Христо́в і моли́твенниче о нас благоприя́тний.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє похва́льноє прино́сим тебі́, му́чениче Христо́в Іоа́нне, є́же с любо́вію приє́мля, моли́ Го́спода ізба́витися нам от бід і скорбе́й, найпа́че же в час кончи́ни на́шея твої́м заступле́нієм предвари́, да не умре́м безпокая́нни, но сподо́бимся в Небе́сних селе́ніїх с тобо́ю воспі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Свіща́ єси́ в це́ркві Христо́вій, горя́щи невеще́ственним сві́том благода́ті Бо́жієй і озаря́ющи тьму неразу́мія на́шего, Іоа́нне преблаже́нне. Сего́ ра́ди мо́лим ті ся: просвіти́ ни, омраче́нния гріхо́м, да воспої́м тебі́:","Ра́дуйся, світ Боже́ственнаго уче́нія в се́рдці своє́м носи́вий;","ра́дуйся, я́ко тім просвіща́єм, тьму і́дольськаго служе́нія обличи́л єси́.","Ра́дуйся, я́ко і нам ті́мже сві́том просвіти́тися тщи́шися;","ра́дуйся, я́ко сла́ву Трисія́ннаго Божества́ лице́м к Лицю́ зри́ши.","Ра́дуйся, лучу́ благода́ті Бо́жієй, от Со́лнця Пра́вди возжже́нний;","ра́дуйся, озаря́яй тьму неві́дінія на́шего сві́том Христо́вих за́повідей.","Ра́дуйся, путево́дная звізда́ всім і́щущим спасе́нія;","ра́дуйся, я́ко наставля́єши нас на вся́коє ді́ло благо́є.","Ра́дуйся, я́ко мисль бла́гу нам на се́рдці во благовре́менії полага́єши;","ра́дуйся, я́ко во́їнському зва́нію о́браз до́браго во́їна в себі́ показу́єши.","Ра́дуйся, озари́вий вселе́нную сві́том доброді́телей твої́х;","ра́дуйся, я́ко, ви́дя до́брая ді́ла твоя́, челові́ци Отця́ Небе́снаго прославля́ють.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть дана́ тебі́ от Бо́га во є́же руково́дствовати ко спасе́нію і сохраня́ти от бід чту́щих па́м'ять твою́, сего́ ра́ди моли́твами твої́ми огради́ от вся́каго зла Це́рков і страну́ Украї́нськую, ві́рния же вся в доброді́теліх преуспіва́ти сотвори́, да воспої́м всі Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Бо́га, ди́внаго во святи́х Свої́х, хва́лим тя, Христо́ва іспові́дника, во́їна же і чудотво́рця хвале́ньми сицеви́ми:","Ра́дуйся, Це́ркве Бо́жия украше́ніє;","ра́дуйся, к во́їнству Небе́сному сопричте́нний.","Ра́дуйся, всеору́жіє Бо́жиє приє́мий;","ра́дуйся, тім вся ко́зні вра́жия преодоле́вий.","Ра́дуйся, броне́ю пра́ведности облече́нний;","ра́дуйся, щито́м ві́ри осіне́нний.","Ра́дуйся, шлем спасе́нія стяжа́вий;","ра́дуйся, меч духо́вний, є́же єсть сло́во Бо́жиє, па́че вся́каго ору́жія возлюби́вий.","Ра́дуйся, препоя́санний от Бо́га пра́вдою і і́стиною о чре́сліх свої́х;","ра́дуйся, я́ко к зва́нним на бра́чную ве́черю А́гнця сопричте́н єси́.","Ра́дуйся, я́ко та́мо воспі́ти піснь но́ву пред Престо́лом Єго́ сподо́бился єси́;","ра́дуйся, на Не́бі приобща́яйся ни́ні Христа́ і́стіє, не́же іногда́ на землі́.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О святи́й уго́дниче Христо́в і чудотво́рче Іоа́нне Во́їне! Прийми́ сіє́ хвале́ніє на́ше і мольби́ тебі́ приноси́мия, і благоприя́тними твої́ми к Бо́гу моли́твами ізба́ви нас от вся́ких зол і обстоя́ній, болі́зней душе́вних і тіле́сних, і от ві́чнаго муче́нія предста́тельством твої́м сохрани́ і досто́йни Ца́рствія Небе́снаго би́ти умоли́, да сподо́бимся в Небе́сних селе́ніїх воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Арха́нгели і А́нгели с любо́вію зря́ху на равноа́нгельськоє житіє́ твоє́, Іоа́нне пречу́дне, ти бо, пеки́йся о Госпо́дніх, ка́ко угоди́ти Го́сподеві, сохрани́л ді́вство неврежде́нно, посто́м і моли́твою умерщвля́я плоть свою́ день і нощ. Ми же таково́му житію́ твоєму́ див'я́щеся, со умиле́нієм взива́єм ті си́це:","Ра́дуйся, чистоту́ се́рдця своєго́ сохрани́вий;","ра́дуйся, я́ко сего́ ра́ди Бо́га узрі́ти сподо́бился єси́.","Ра́дуйся, і́го Христо́во на ра́мо своє́ взе́мшій;","ра́дуйся, ду́шу свою́ Христа́ ра́ди погуби́вий, во є́же спасти́ ю.","Ра́дуйся, А́нгелов сожи́телю;","ра́дуйся, ді́вственников похвало́.","Ра́дуйся, храни́телю і наста́вниче ю́них отроко́в;","ра́дуйся, ско́рий помо́щниче борю́щимся со страстьми́ і похотьми́.","Ра́дуйся, защи́тниче дів і вдови́ць;","ра́дуйся, обличе́ніє наруши́телей цілому́дрія.","Ра́дуйся, роди́телей і воспита́телей наста́вниче;","ра́дуйся, сиро́тствующих незри́мий води́телю.","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́ннаго раба́ Царя́ Небе́снаго, до́бляго Христо́ва страстоте́рпця, Іоа́нна свята́го Во́їна і чудотво́рця похва́льними пі́сньми воспої́м, я́ко христия́н засту́пника, цілому́дрія блюсти́теля, стра́ждущих уті́шителя. Ти же, предстоя́ Престо́лу Святи́я Тро́йці, моли́твами свої́ми от вся́ких зол і напа́стей охраня́й с ві́рою і любо́вію зову́щих ті:","Ра́дуйся, Іоа́нне, святи́й Во́їне і пресла́вний чудотво́рче."]},{"h":"Молитва","ps":["О, му́чениче Христо́в, Іоа́нне во́їне! Хра́брий єси́ во бра́ніх, і враго́м прогони́тель, і оби́димим засту́пник, всім правосла́вним христия́ном. О, вели́кий засту́пниче і уго́дниче Христо́в, Іоа́нне во́їнственниче! Поми́луй нас, грі́шних і недосто́йних, і заступи́ в біда́х і в ско́рбіх, і в печа́ліх, і во вся́кой злой напа́сти, і от вся́каго зла́го і оби́дящаго челові́ка, тебі́ бо дана́ бисть такова́я благода́ть от Бо́га, є́же моли́тися за ни, грі́шния, в біда́х і напа́стіх злі стра́ждущия. Ізба́ви у́бо нас от оби́дящих і ненави́дящих, бу́ди нам побо́рник крі́пок на вся ви́димия і неви́димия враги́ на́ша. О, вели́кий побо́рниче, Іоа́нне во́їне! Не забу́ди нас, всегда́ моля́щихся тебі́, прося́щих по́мощі і неоску́дния ми́лости твоєя́, і сподо́би нас, грі́шних і недосто́йних, получи́ти от Бо́га неізрече́нная блага́я, я́же угото́ва лю́б'ящим Єго́. Я́ко подоба́єть Єму́ вся́кая сла́ва, честь і поклоне́ніє, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Всеблага́го Бо́га і Царя́ / благові́рний раб і во́їн яви́лся єси́, Іоа́нне чудоді́телю, / постра́дав бо ра́ди ві́ри му́жеськи, / блаже́нно же сконча́в тече́ніє, / зри́ши Всетворця́ Го́спода в Небесі́х світлі́йше. / От Него́же приє́м дарова́ніє чуде́с, / стра́ждущим челові́ком во вся́ких напа́стіх помога́єши, / укріпля́єши во́їни в ра́тіх, / от враго́в пліне́нія, ран же і внеза́пних смерте́й і от бід лю́тих ізима́єши. / Ті́мже моли́ Влади́ку Христа́, приснопа́м'ятне, / да во вся́ком обстоя́нії сотвори́ть нам ми́лость, / і не введе́ть нас во іскуше́нія, // но спасе́ть ду́ші на́ша, я́ко Человіколю́бець."]},{"h":"Інший тропар, глас 8","ps":["Блаже́нство єва́нгельськоє возлюби́в, Богому́дре Іоа́нне, / чистоту́ се́рдця ді́вством почти́л єси́. / Ті́мже суєту́ ми́ра сего́ пренебре́г, / устреми́лся єси́ зрі́ти Бо́га, / І́же тя просла́ви чудеси́ во врачева́нії разли́чні стра́ждущих. / Сего́ ра́ди мо́лим тя: / проси́ нам у Христа́ Го́спода вся́ких скорбе́й ізбавле́нія // і получе́нія Ца́рства Небе́снаго."]},{"h":"Кондак, глас 6","ps":["Благочести́ваго во́їна Христо́ва, / побіди́вшаго враги́ душе́вния і тіле́сния богому́дренно, / Іоа́нна му́ченика достодо́лжно пі́сньми восхва́лим, / чудоді́йствуя бо, подає́ть оби́льная ісціле́нія стра́ждущим лю́дем / і мо́литься Го́споду Бо́гу // от вся́ких бід спасти́ правові́рния."]},{"h":"Інший кондак, глас 3","ps":["Вели́кая ско́рбним лю́дем ра́дость в біда́х обріта́єшися, чудотво́рче Іоа́нне, / вся́кия бо стра́сті моля́щим тя врачу́єши, / ісполня́я їх проше́нія. / Ті́мже і ни́ні моли́ Го́спода, // да спасе́ть ни в ми́лості Своє́й."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й Іоа́нне, і чтим честна́я страда́нія твоя́, я́же за Христа́ претерпі́л єси́."]}],"notes":[]},{"u":"Акафіст священномученику Киприану і святій мучениці Іустині","e":"Akathist to the Hieromartyr Cyprian and the Holy Martyr Justina","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці і ско́рії засту́пниці, священному́чениче Киприя́не і му́ченице Іусти́но, я́ко іму́щії ве́ліє дерзнове́ніє ко Го́споду і ви́ну Престо́лу Єго́ предстоя́щії, предста́тельством ва́шим от вся́ких нас бід свободи́те і наслі́дники Ца́рствія Небе́снаго соді́лайте, похва́льноє пі́ніє вам принося́щих:","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгельськія си́ли удиви́шася, ка́ко ви, Киприя́не і Іусти́но, от безду́шних бого́в отвратившеся і в Бо́га Жива́ уверовавше, позна́нієм і́стини Боже́ственния обріли́ єсте́ а́нгельськоє безстра́стноє житіє́. Ми же, сему́ див'я́щеся, вопіє́м вам такова́я:","Ра́дуйтеся, тве́рдостію ва́шея ві́ри во Христа́ А́нгели удиви́вшії.","Ра́дуйтеся, вхожде́нієм на брак А́гнчий лик святи́х возвеселившії.","Ра́дуйтеся, я́ко за Христа́ му́жественно пострадали єсте́.","Ра́дуйтеся, я́ко за іспові́даніє Єго́ вінці́ нетлі́ннії прия́ли єсте́.","Ра́дуйтеся, на небесі́х ни́ні пред Престо́лом Бо́жиїм предстоя́щії.","Ра́дуйтеся, о спасе́нії душ на́ших Го́спода умоляющії.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дя суєту́ і́дольськаго нече́стія, к позна́нію Боже́ственному от худо́жества волше́бнаго отврати́лся єси́, Киприя́не, ду́шу свою́ от поги́белі ві́чния ісхища́я. Ни́ні же, у Престо́ла Бо́жия во сла́ві небе́сній предстоя́, моли́ся Человіколю́бцю Влади́ці спасти́ душі́ на́ша, пою́щих Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом і́стиннаго богопозна́нія сви́ше наставля́ємий, чароді́йства і волхвова́нія отврати́лся єси́, Киприя́не, і сле́зним покая́нієм стра́сті своя́ угаси́л єси́; уві́дів же, я́ко і́мене Христо́ва і Креста́ Животворя́щаго бі́си трепе́щуть і ко́зні вра́жия разруша́ються, в храм Бо́жий на служе́ніє Єму́ прите́кл єси́. Ті́мже, усе́рдіє твоє́ похваля́юще, взива́єм си́це:","Ра́дуйся, хи́трости де́монськия му́жественно отвергнувий.","Ра́дуйся, ко́зні їх па́губния я́ко паучи́ну растерза́вий.","Ра́дуйся, пре́лести служе́нія єго́ небоя́зненно обличи́вий.","Ра́дуйся, змі́я лука́ваго пред всі́ми посрами́вий.","Ра́дуйся, я́ко тобо́ю бі́си отгоня́ються.","Ра́дуйся, я́ко тобо́ю болі́зні тіле́сния і душе́вния ісціля́ються.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпля́єма, сі́мена ві́ри спаси́тельния в се́рдці своє́м восприя́ла єси́, Іусти́но: ти бо про́повіді дия́кона Праїлія о Го́споді Ісу́се Христе́, ро́ждшемся от Пречи́стия Ді́ви Марі́ї, страдавшем, і погребенном, і разрушившим сме́ртію смерть, внима́я, до́брий плод в душі́ своє́й возрасти́ла єси́, те́рнія неві́рія іскореня́я, і Бо́гу вопія́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ра́зум Бо́гом просвіще́нний, свята́я Іусти́но, уразумі́ла єси́, я́ко то́кмо в Це́ркві Христо́вой обря́щеши спасе́ніє душі́ своєя́, в не́йже, сло́ву Бо́жию внима́я, Ду́хом Святи́м во ві́рі во Христа́ утверди́лася єси́. Таково́му Бо́жию благоволе́нію о тебі́ ра́дуяся, воспіва́єм ті си́це:","Ра́дуйся, звіздо́, во тьмі язи́чеськаго нече́стія возсія́вшая.","Ра́дуйся, сві́том благочести́вия ві́ри просветившаяся.","Ра́дуйся, благода́тію Ду́ха Свята́го ду́шу твою́ іспо́лнившая.","Ра́дуйся, Жениху́ Небе́сному ді́вство своє́ обручи́вшая.","Ра́дуйся,Сладча́йшаго Ісу́са неві́сто прекра́сная.","Ра́дуйся, вели́кою во Ца́рствії Небе́снім нарече́нная.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 4","ps":["Бу́ри гріхо́вния ізбіга́я, ко Христу́ прише́л єси́ і всего́ себе́, я́ко же́ртву благово́нную, Спаси́телю на́шему прине́сл єси́, богому́дре Киприя́не, тве́рдоє бо намі́реніє в се́рдці своє́м прия́л єси́: Креще́нієм святи́м ду́шу свою́ убіли́ти, ві́рним последователем Го́споду би́ти і во вся дні живота́ своєго́ воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще отрече́ніє твоє́ от служе́нія врагу́ ро́да челові́чеськаго і ви́дяще благо́є намі́реніє твоє́ во Христа́ облещи́ся і соверше́нним христия́нином би́ти, єпи́скоп Анфи́м а́біє крести́ тя, Киприя́не, і чтецом во хра́мі Бо́жиєм поста́ви. Ми же, ра́дующеся таково́му твоєму́ обраще́нію ко Христу́, поє́м ті такова́я:","Ра́дуйся, я́ко Го́спода все́ю душе́ю возлюби́л єси́.","Ра́дуйся, я́ко христия́нином і́стинним би́ти возжелі́л єси́.","Ра́дуйся, свято́є Креще́ніє с благогові́нієм прия́вий.","Ра́дуйся, Ду́ха Свята́го жили́ще себі́ сотвори́вий.","Ра́дуйся, Господом сви́ше просвіще́нний.","Ра́дуйся, єпи́скопом во ві́рі Христо́вой наста́вленний.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 5","ps":["Боготе́чною стезе́ю устреми́лася єси́ і ти́хаго приста́нища дости́гла єси́, свята́я му́ченице Іусти́но: ти бо сві́том і́стини Боже́ственния роди́телі твоя́ Єдесія і Клеодонію просвіти́вши, ку́пно с ни́ми свято́є Креще́ніє от єпи́скопа Онтата прия́ла єси́, да Христу́ уго́дна бу́деши і возмо́жеши невозбра́нно пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще премно́гую доброді́тель отця́ твоєго́ Єдесія, поста́ви єго́ святи́тель Бо́жий во пресви́тера, да доброді́тельним житіє́м і іни́х ко Христу́ приведе́ть; тебі́ же, достоблаже́нная Іусти́но, досто́йную дщер єго́, па́че всего́ Христа́ возлюби́вшую і в соблюде́нії за́повідей Єго́ до́брі подвиза́вшуюся, почита́єм зва́нії си́ми:","Ра́дуйся, красото́ю душе́вною просія́вшая.","Ра́дуйся, ді́вство непоро́чноє в дар Бо́гу прине́сшая.","Ра́дуйся, благові́стнице Єва́нгелія богому́драя.","Ра́дуйся, за́повідей Госпо́дніх пропові́днице усе́рдная.","Ра́дуйся, подви́жнице Бо́жия, посто́м і моли́твою воспитанная.","Ра́дуйся, голуби́ця непоро́чная, кро́тости і незло́бія преісполненная.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 6","ps":["Пропові́дник і́стини Христо́ви яви́лся єси́, священному́чениче Киприя́не, ті́мже Человіколю́бець Госпо́дь, І́же хотя́й всім спасти́ся, дарова́ нам тебе́ ди́внаго моли́твенника, ціли́теля і защи́тника от духо́в зло́би поднебе́сних: ти бо ді́ли і словеси́ твої́ми приво́диши мно́гія к покая́нію і гріхо́вния жи́зні ісправле́нію, науча́я всіх пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко світи́ло світоза́рноє, просвіща́ющеє сві́том богопозна́нія всіх, во тьмі неві́рія су́щих, святи́телю Киприя́не, поне́же моли́тві твоє́й никияже чародія́нія, от лука́вих бісо́в і злих челові́к ісходящия, противоста́ти не мо́гуть: оба́че си́лою Бо́жиєю разруша́ються і прогоня́ються. Сего́ ра́ди вопіє́м си́це:","Ра́дуйся, вра́жиїх ко́зней разруши́телю.","Ра́дуйся, злих бісо́в прогони́телю.","Ра́дуйся, от враг ви́димих і неви́димих стіно́ і огражде́ніє.","Ра́дуйся, оста́вленних врача́ми преди́вноє поможе́ніє.","Ра́дуйся, от бід і скорбе́й ско́ро ізбавля́яй.","Ра́дуйся, страда́нія в ра́дость претворя́яй.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хотя́щи му́дрим єва́нгельським ді́вам поревнова́ти, єле́єм до́брих діл іспо́лнилася єси́, сла́вная му́ченице Іусти́но, і, возже́гши світи́льник душі́ своєя́, просвещала єси́ лю́ди Христо́вим уче́нієм, да позна́вше Го́спода Ісу́са пою́ть Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ на тебі́ ми́лость Свою́ Всемогу́щий Госпо́дь: Боже́ственною бо благода́тію Своє́ю вознесе́ тя, пресла́вная Іусти́но, на висоту́ духо́внаго соверше́нства, я́ко і немощни́я от неду́гов душе́вних і тіле́сних ісціля́ти, і от духо́в нечи́стих стра́ждущия от ко́зней їх лука́вих свобожда́ти возмо́жеши. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, го́рняя, па́че до́льних, возлюби́вшая.","Ра́дуйся, Бо́гу всю себе́ преда́вшая.","Ра́дуйся, серафи́мською любо́вію к Нему́ горя́щая.","Ра́дуйся, і нас люби́ти Єго́ все́ю душе́ю науча́ющая.","Ра́дуйся, люде́й правосла́вних во ві́рі утвержде́ніє.","Ра́дуйся, ді́вственнаго со́нма украше́ніє.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нно бі нечести́вому іге́мону ви́діти тебе́, священному́чениче Киприя́не, єгда́ суду́ непра́ведному тебі́ предаде́: ти бо, я́ко непоколеби́м во́їн Царя́ Небе́снаго, со дерзнове́нієм Христа́ іспові́дал єси́, во страда́ніїх воспіва́я: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́ Бо́гу пре́дал єси́, священному́чениче Киприя́не: не убоя́лся бо єси́ преще́ній лю́тих і сами́х страда́ній, оба́че лице́м сві́тлим, благода́тію Бо́жиєю сія́ющим, предста́л єси́ суди́лищу нечести́вому, подвиза́я всіх ві́рних воспіва́ти ті си́це:","Ра́дуйся, ві́ри Христо́ви непоколеби́мий іспові́дниче.","Ра́дуйся, Пречи́стия Тро́йці дерзнове́нний пропові́дниче.","Ра́дуйся, си́лою Бо́жиєю духо́в зло́би побіди́вий.","Ра́дуйся, огне́м моли́тви стрі́ли вра́жія попали́вий.","Ра́дуйся, я́ко муче́нія лю́тая ні во что́же вміни́л єси́.","Ра́дуйся, я́ко в страда́ніїх твої́х Бо́га просла́вил єси́.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 9","ps":["Вся́коє благо́є проше́ніє на́ше, притека́ющих к тебі́ с ві́рою, не отри́ни, му́ченице свята́я Іусти́но, і́бо да́нною тебі́ от Бо́га благода́тію ізгоня́ти ду́хи нечи́стия, муча́щия челові́ка, бі́си прогоня́ються і неду́жним здра́віє подає́ться, вопію́щим Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії по достоя́нію не возмо́гуть воспі́ти вся труди́ твоя́, свята́я Іусти́но, ти бо всім се́рдцем і все́ю душе́ю Бо́га возлюби́вши, все твоє́ тща́ніє і жела́ніє направляла єси́, во є́же святу́ю во́лю Єго́ ісполня́ти. Ті́мже і ни́ні нас, біда́ми і скорбми́ отягче́нних, не оставля́єши, но предста́тельствуєши за ни пред Го́сподем, ісцеленієї утіше́ніє нам да́руя. Сего́ ра́ди, восхваля́я тя, взива́єм си́це:","Ра́дуйся, во благи́х проше́нія на́ша ско́ро ісполня́ющая.","Ра́дуйся, в неду́зіх стра́ждущия благода́тно посіща́ющая.","Ра́дуйся, в моли́твах на́ших те́плоє прибі́жище.","Ра́дуйся, оби́димим благо́є утіше́ніє.","Ра́дуйся, ві́рних ко спасе́нію до́брая наста́внице.","Ра́дуйся, в боре́ніїх су́щим помо́щнице.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасе́ніє всіх устроя́ющи Человіколю́бець Госпо́дь, по сконча́нії ісповедничеськаго по́двига твоєго́, увінча́ тя, святи́телю Киприя́не, вінце́м му́ченичеським: іспові́дуя бо пред мучи́телі Бо́га І́стинна, в Тро́йці Святі́й покланя́ємаго, небоя́зненно подклони́л єси́ под меч главу́ свою́, воспіва́я: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ і щит, богому́дре Киприя́не, всім усе́рдно к тебі́ прибегающим і пред іко́ною твоє́ю те́плі молящимся: тебі́ бо дарова́ нам Всеблаги́й Госпо́дь в по́мощ і врачевство́ болі́зней душе́вних і тіле́сних. Сего́ ра́ди взива́єм ті:","Ра́дуйся, я́ко Го́споду за нас моли́тви своя́ возно́сиши.","Ра́дуйся, я́ко пред Престо́лом Бо́жиїм о нас хода́тайствуєши.","Ра́дуйся, я́ко сві́том богові́дінія пра́ведния просвіща́єши.","Ра́дуйся, я́ко заблу́ждших на путь спаси́тельний наставля́єши.","Ра́дуйся, да́ри ціле́бния просящим у тебе́ ско́ро подава́яй.","Ра́дуйся, лю́б'ящим і чту́щим тя любо́вію сугу́бою воздава́яй.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє ко Го́споду возносила єси́, страстоте́рпице свята́я Іусти́но, єгда́ муче́нія тя́жкия му́жественно за Него́ терпі́ла єси́; тече́ніє же твоє́ ісповедничеськоє сконча́вши, ра́достно главу́ свою́ на ме́чноє усіче́ніє преклони́ла єси́, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рною свіще́ю на сві́щниці церко́вній сія́єши, свята́я Іусти́но, сві́том благода́тним отгоня́ющи от нас враго́во ви́димих і неви́димих. Ми же, с те́плою ві́рою і любо́вію к тебі́ прибіга́ющи, восхваля́єм му́ченичеськую кончи́ну твою́, взива́я си́це:","Ра́дуйся, Бо́га І́стиннаго дерзнове́нно пропові́давшая.","Ра́дуйся, о укріпля́ющем тя Го́споді вся возмогшая.","Ра́дуйся, я́ко я́зви Го́спода Ісу́са на ті́лі твоє́м носи́ла єси́.","Ра́дуйся, я́ко терпі́нієм твої́м мучи́телей побіди́ла єси́.","Ра́дуйся, му́ченичеськоє тече́ніє твоє́ мечною кончи́ною увенчавшая.","Ра́дуйся, Го́спода твоєго́ страда́ньми і чудеси́ просла́вившая.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ть дана́ вам от Бо́га, святі́ї Киприя́не і Іусти́но, попира́ти си́лу вра́жию і вся́коє бісо́вськоє нахожде́ніє: ви бо страда́нія ве́лія претерпі́вши, му́ченичеською кончи́ною своє́ю блаже́нства ві́чнаго дости́гли єсте́; ни́ні же предстоя́ Престо́лу Царя́ сла́ви, молі́теся о нас, во є́же ізба́витися нам от пліне́нія дия́вольськаго, да возмо́жем непреткнове́нно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ре́вность ва́шу по Бо́зі і ди́вная і пресла́вная чудеса́ ва́ша, велича́єм і восхваля́єм вас, священному́чениче Киприя́не і му́ченице Іусти́но, такову́ю благода́ть от Бо́га приє́мших; мо́лим же вас: єгда́ в час сме́рти на́шея де́монськия по́лчища обстоя́ть душі́ на́ша, тогда́ яві́те нам своє́ заступле́ніє, да при́сно ва́ми ізбавля́ємі, взива́єм си́це:","Ра́дуйтеся, от находя́щих ко́зней вра́жиїх ско́роє защище́ніє.","Ра́дуйтеся, от скорбе́й і печа́лей ізбавле́ніє.","Ра́дуйтеся, Христа́ до конця́ возлюби́вшії.","Ра́дуйтеся, душі́ своя́ за Него́ положи́вшії.","Ра́дуйтеся, в Кро́ві А́гнчей омившіїся.","Ра́дуйтеся, во дво́ріх Госпо́дніх вселившіїся.","Ра́дуйтеся, к со́нму святи́х сопричтеннії.","Ра́дуйтеся, Трисія́нним Сві́том озареннії.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 13","ps":["О преди́внії і пресла́внії уго́дниці Бо́жії, священному́чениче Киприя́не і му́ченице Іусти́но, ско́рії помошници всім с ві́рою к вам прибегающим, приймі́те от нас, недосто́йних, хвале́бноє пі́ніє сіє́, і от неду́гов душе́вних і тіле́сних вся ни ісцілі́те, от враг ви́димих і неви́димих засту́питі і ві́чнаго муче́нія ізба́витися нам Го́спода умолі́те, да ку́пно с ва́ми вопіє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськія си́ли удиви́шася, ка́ко ви, Киприя́не і Іусти́но, от безду́шних бого́в отвратившеся і в Бо́га Жива́ уверовавше, позна́нієм і́стини Боже́ственния обріли́ єсте́ а́нгельськоє безстра́стноє житіє́. Ми же, сему́ див'я́щеся, вопіє́м вам такова́я:","Ра́дуйтеся, тве́рдостію ва́шея ві́ри во Христа́ А́нгели удиви́вшії.","Ра́дуйтеся, вхожде́нієм на брак А́гнчий лик святи́х возвеселившії.","Ра́дуйтеся, я́ко за Христа́ му́жественно пострадали єсте́.","Ра́дуйтеся, я́ко за іспові́даніє Єго́ вінці́ нетлі́ннії прия́ли єсте́.","Ра́дуйтеся, на небесі́х ни́ні пред Престо́лом Бо́жиїм предстоя́щії.","Ра́дуйтеся, о спасе́нії душ на́ших Го́спода умоляющії.","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці і ско́рії засту́пниці, священному́чениче Киприя́не і му́ченице Іусти́но, я́ко іму́щії ве́ліє дерзнове́ніє ко Го́споду і ви́ну Престо́лу Єго́ предстоя́щії, предста́тельством ва́шим от вся́ких нас бід свободи́те і наслі́дники Ца́рствія Небе́снаго соді́лайте, похва́льноє пі́ніє вам принося́щих:","Ра́дуйтеся, Киприя́не і Іусти́но, ско́рії помо́щници і молитвеници о душа́х на́ших."]},{"h":"Молитва","ps":["О святі́ї священному́чениче Киприя́не і му́ченице Іусти́на! Внемлі́те смире́нному моле́нію на́шему. А́ще бо вре́менноє житіє́ ва́ше му́ченичеськи за Христа́ сконча́ли єсте́, но ду́хом от нас не отступа́єте єсте́, при́сно по за́повідем Госпо́днім ше́ствовати нас науча́юще і крест свой терпіли́во нести́ нам посо́бствующе. Се, дерзнове́ніє ко Христу́ Бо́гу і Пречи́стій Єго́ Ма́тері стяжа́ли єсте́. Ті́мже і ни́ні бу́діте моли́твенниці і хода́таї о нас, недосто́йних (імена́). Бу́діте нам засту́пниці кре́пції, да заступле́нієм ва́шим сохраня́ємі невреди́ми от бісо́в, волхво́в і от челові́к злих пребу́дем, сла́в'яще Святу́ю Тро́йцю: Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О святи́й уго́дниче Бо́жий, священному́чениче Киприя́не, ско́рий помо́щниче і моли́твенниче о всіх к тебі́ прибіга́ющих. Прийми́ от нас недосто́йних хвале́ніє на́ше і іспроси́ нам у Го́спода Бо́га в не́мощіх укріпле́ніє, в болі́зніх ісціле́ніє, в печа́ліх утіше́ніє і всім вся поле́зная в жи́зні на́шей. Вознеси́ ко Го́споду благомо́щную твою́ моли́тву, да огради́ть нас от паде́ній на́ших гріхо́вних, да научи́ть нас і́стинному покая́нію, да ізба́вить нас от пліне́нія дия́волськаго і вся́каго ді́йствія духо́в нечи́стих, і ізба́вить от оби́дящих нас. Бу́ди нам крі́пкий побо́рник на вся враги́ ви́димия і неви́димия, во іскуше́нії пода́ждь нам терпі́ніє і в час кончи́ни на́шей яви́ нам заступле́ніє от істяза́телей на возду́шних мита́рствах на́ших, да води́мії тобо́ю, дости́гнем Го́рняго Ієрусали́ма і сподо́бимся в Небе́сном Ца́рствії со всі́ми святи́ми сла́вити і воспіва́ти Всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["І нра́вом прича́стник, / і престо́лом намі́стник апо́столом бив, / дія́ніє обрі́л єси́, Богодухнове́нне, / во виді́нія восхо́д: / сего́ ра́ди, сло́во і́стини ісправля́я, / і ві́ри ра́ди пострада́л єси́ да́же до кро́ве, / священному́чениче Киприя́не, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 1","ps":["От худо́жества волше́бнаго обрати́вся, Богому́дре, / к позна́нію Боже́ственному, / показа́лся єси́ ми́ру врач мудрі́йший, / ісціле́нія да́руя че́ствующим тя, Киприя́не со Іусти́ною: / с не́юже моли́ся Человіколю́бцю Влади́ці // спасти́ ду́ші на́ша."]},{"h":"Величання","ps":["Велича́єм тя, священному́чениче Киприя́не, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святій великомучениці Параскеві, нареченій П’ятниці","e":"Akathist to the Holy Great Martyr Paraskeva, called Friday","secs":[{"h":"Кондак 1","ps":["Ізбра́нной Бо́гом от ро́да благоро́днаго, Іконі́йськаго гра́да, прему́дрой і всехва́льной неві́сті Христо́ві, я́ко ізбавля́ємії тобо́ю от іскуше́ній і бід, благода́рственная пі́нія і хвале́нія воспису́єм ті моли́твенници твої́, свята́я і многострада́льная му́ченице Параске́во. Ти же, імі́я дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да со умиле́нієм і ра́достію зове́м ті:","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Ікос 1","ps":["А́нгелом честну́ю і вселюбе́зную чистоту́ твоєго́ сердця́, многострада́льная Параске́во, непоро́чно сохра́нши, а́нгелом собесі́дниця би́ти сподо́билася єси́. С ни́миже воспіва́я трисвяту́ю піснь Бо́гу на небесі́, усли́ши і нас, ві́рою і любо́вію чту́щих тя і вопію́щих ті хвале́нія сія́ на землі́:","Ра́дуйся, отрокови́це, Бо́гом Отце́м предуста́вленная би́ти сообра́зной в страда́нії о́бразу Си́на Єго́;","ра́дуйся, і Си́ном Бо́жиїм укрепле́нная на по́двиги страда́льчеськия.","Ра́дуйся, і́стинную ві́ру в Животворя́щую і Єдиносу́щную Тро́йцю свя́то соблю́дшая;","ра́дуйся, свято́є целому́дріє і ді́вственную непоро́чность до́брі сохра́ншая.","Ра́дуйся, я́ко ра́достно уневі́стилася єси́ безсме́ртному Небе́сному Жениху́ Христу́;","ра́дуйся, земна́го обру́чника па́че Небе́снаго зна́ти не восхоті́вшая.","Ра́дуйся, я́ко цвіт чистоти́, в неув'яда́ємой сла́ві цвіту́щая;","ра́дуйся, я́ко крин, воня́ми твої́х доброді́телей нам благоуха́ющая.","Ра́дуйся, в Небе́сном вертогра́ді неізрече́нною ра́достію наслажда́ющаяся;","ра́дуйся, красні́йшаго па́че сино́в челові́чеських зрі́нієм та́мо утіша́ющаяся.","Ра́дуйся, убіли́вшая ри́зи твоя́ в кро́ві А́гнчей на землі́;","ра́дуйся, в ли́кі ді́вственниць предстоя́щая Бо́жиєму А́гнцю на небесі́.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 2","ps":["Ви́дівше благолі́піє лиця́ твоєго́, свята́я му́ченице Параске́во, лю́діє удивля́хуся, взира́юще на тя, не у ві́дяще красоти́ ду́ші твоєя́. Ми же, помина́юще светле́йшия па́че со́лнця доброді́телі твоя́, пої́м Го́сподеві, дарова́вшему тебі́ благода́ть Свою́: Аллилу́я."]},{"h":"Ікос 2","ps":["Му́дрости вмісти́лище па́че ума́ мирськи́х мудреце́в яви́лася єси́, отрокови́це непоро́чная, ізмла́да уклони́вшися от любве́ к ми́ру і отве́ргшися всего́, я́же в ми́рі, все́ю полното́ю любве́ твоєя́ возлюби́ла єси́ Небе́снаго Жениха́ Христа́, Царя́ Сла́ви, Єму́же, я́ко ві́рная раба́, в житії́ твоє́м апо́стольськи послужи́ла єси́, жи́вши свя́то среди́ неві́рних і безбоя́зненно пропові́давши їм Христа́ Бо́га. Таково́му твоєму́ ра́зуму див'я́щеся, сія́ похвали́ тебі́ воспису́єм:","Ра́дуйся, прему́драя Єва́нгельськая ді́во, во сві́ті ві́ри і діл благи́х ходи́вшая;","ра́дуйся, Христа́ Го́спода, Бо́жию си́лу і Бо́жию прему́дрость па́че всего́ возлюби́вшая.","Ра́дуйся, па́че мудреце́в ми́ра сего́ мудрі́йшая;","ра́дуйся, па́че ста́рець ідолослужи́тельних разу́мнійшая.","Ра́дуйся, неві́рних сві́том ві́ри просвіща́ющая;","ра́дуйся, чад Це́ркве Христо́ви во ві́рі утвержда́ющая.","Ра́дуйся, любо́вію твоє́ю ко Христу́ а́нгельськая ликостоя́нія возвеселя́ющая;","ра́дуйся, де́монськия лука́вствія ору́жієм Креста́ Госпо́дня отгоня́ющая.","Ра́дуйся, в пропові́данії ві́ри богоглаго́ливая уста́ апо́стольськая;","ра́дуйся, дів христия́нських украше́ніє.","Ра́дуйся, ві́рная ко Христу́ Бо́гу моли́твеннице о на́шем спасе́нії;","ра́дуйся, всіх скорб'я́щих крі́пкоє заступле́ніє і огражде́ніє.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 3","ps":["Си́лою Христо́вою соблюда́єма, всесла́вная му́ченице Параске́во, о болі́зніх тіле́сних небрегла́ єси́, по́двигом до́брим подвиза́тися хотя́щи. Му́жеським сми́слом вооружи́вшися, сла́бость же́нськую отве́ргла єси́, упова́нієм же укріпи́вшися, ра́достно предста́ла єси́ на суди́щі, іді́же я́сно ві́ру в Тро́йцю Боже́ственную пропові́дала єси́, Бо́гу вопію́щи: Аллилу́я."]},{"h":"Ікос 3","ps":["Сли́шав от тебе́, му́драя дщер, непра́ведний судія́ несли́ханная словеса́ о твоє́м рожде́нії, я́ко благочести́вії роди́телі твої́, стра́сті Христо́ви почита́юще, знамени́таго дне тезоімени́ту тя нареко́ша, Параске́вою, в предзнаменова́ніє, я́ко Христо́вих страсте́й і́маши би́ти прича́стницею. Не ра́зуме же сего́ нечести́вий іге́мон, но віща́ше ті безсту́дная словеса́ і повелі́ би́ти тя суро́вими жи́лами і полуме́ртву тя су́щу вве́ргнути в темни́цю. Ти же, до́блественне претерпі́вши жесточа́йшия му́ки, в темни́ці, а́ки в черто́зі сві́тлі лику́ющи, вопія́ла єси́: «Нікогда́же отлучу́ся Тебі́, Го́споди, но посли́ мі по́мощ Твою́ і спаси́ м'я вели́кия ра́ди Твоєя́ ми́лости». Ті́мже, ублажа́юще тя, вопіє́м ті такова́я:","Ра́дуйся, незло́бивая голуби́це, от іскуше́ній лука́ваго врага́ свободи́вшаяся;","ра́дуйся, слове́сная а́гнице, от зла́го во́лка мучи́теля к до́брому Па́стирю Христу́ Бо́гу прибі́гшая.","Ра́дуйся, во двор слове́сних ове́ць, одесну́ю Єго́ стоя́щих, вше́дшая;","ра́дуйся, на брак А́гнчий ра́достно теку́щая.","Ра́дуйся, я́ко тебі́ угото́вано єсть благ ві́чних сокро́вище;","ра́дуйся, я́ко тебі́ обетова́но єсть блаже́нство Ца́рства Небе́снаго.","Ра́дуйся, прему́драя Єва́нгельськая ді́во, сві́тло горя́щий світи́льник іму́щая;","ра́дуйся, дерзнове́ніє ве́ліє ко Христу́ Бо́гу стяжа́вшая.","Ра́дуйся, во́лею своє́ю благо́є і́го Христо́во на ся под'я́вшая;","ра́дуйся, се́рдце своє́ от вся́кия ле́сти душевре́дния чи́сто сохра́ншая.","Ра́дуйся, і́стинная Христо́вих страсте́й прича́стнице;","ра́дуйся, во страда́ніях твої́х благода́тную по́мощ от Христа́ Го́спода получи́вшая.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 4","ps":["Бу́рю тя́жких іскуше́ній воздвиго́ша вразі́ проти́ву тебе́, многострада́льная Параске́во; ти же от твої́х крове́й трудолю́бно ча́шу страда́ній іспила́ єси́, жела́ющи по Христе́, Женисі́ твоє́м, во слід потещи́, прехва́льная му́ченице, і я́ко ла́стовиця доброгла́сная, піснь воспіва́ла єси́ Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Імі́я всегда́ пред оча́ми свої́ми Го́спода, за іспові́даніє ві́ри па́лицями неми́лостивно от мучи́телей біє́ма, ра́довалася єси́, приснопа́м'ятная му́ченице Параске́во, вопію́щи: «Нічто́же м'я разлучи́ть от любве́ Твоєя́, Христе́», і та́ко подвиза́яся во Сла́ву Бо́жию, угоди́ла єси́ Го́споду. Ті́мже, помина́юще честна́я твоя́ страда́нія, с умиле́нієм зове́м ті:","Ра́дуйся, а́гнице вседо́бляя, Пастиренача́льнику Христу́ прине́сшаяся, я́ко же́ртва благоуха́нная;","ра́дуйся, безсме́ртному Жениху́ Христу́ непоро́чноє муче́ніє твоє́, я́ко ві́но пречестно́є, предста́вившая.","Ра́дуйся, отрокови́це чи́стая, і́стинноє іспові́даніє ві́ри Правосла́вния пред неві́рними яви́вшая;","ра́дуйся, пра́ведная обличи́тельнице, непра́вду нечести́ваго судії́ я́ві откри́вшая.","Ра́дуйся, я́ко тобо́ю посрами́ся лука́вий враг, ви́дящ себе́ от ю́ной ді́ви побіжде́нна;","ра́дуйся, я́ко ра́дуються о тебі́ і си́ли небе́сния, ви́дяще тя не́мощну і мла́ду су́щу, побіжда́ющую лю́тих мучи́телей.","Ра́дуйся, голуби́це чи́стая і непоро́чная се́рдцем;","ра́дуйся, смире́нная а́гнице, благоуспі́шно честні́й і блаже́нній стра́сті Госпо́дней уподо́бльшаяся.","Ра́дуйся, я́ко принесла́ся єси́ Зижди́телю твоєму́, я́ко кади́ло благово́нноє;","ра́дуйся, я́ко зрить на тя пресві́тлоє Со́лнце пра́вди, тридне́вно возсія́вшеє от гро́ба і укрепи́вшеє тя к по́двигу страда́льчеському.","Ра́дуйся, я́ко за пресла́вная твоя́ страда́нія сподо́билася єси́ вни́ти в черто́г Христа́, Царя́ Небе́снаго;","ра́дуйся, я́ко та́мо вку́пі со святи́ми наслажда́єшися неізрече́нною ра́достію.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 5","ps":["Боготе́чною звіздо́ю прешла́ єси́ в ми́рі, страстоте́рпице сла́вная Параске́во, я́сно ві́ру во Христа́ всім пропові́дающи. Страда́нія мно́га і лю́та му́жеськи претерпі́вши, мучи́теля посрами́ла єси́ і ко Христу́ Го́споду, я́ко Сві́ту незаходи́мому, ра́достно востекла́ єси́. Єму́же предстоя́щи с ли́ки пра́ведних, ви́ну вопіє́ши: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще си́ли небе́сния пло́тію стра́ждущую Соді́теля ра́ди страстоте́рпицю Параске́ву, Єго́ си́лою креп'я́щуюся, глаго́лаху: «Се, і ді́ви на землі́ просла́виша Го́спода!» Челові́ци же, тре́петом одержи́ми, ужаса́хуся і удивля́ющеся, пі́сньми прославля́ху: «О чудесе́! Ді́ва врага́ побіди́ і мо́литься ми́лостивому Влади́ке за спасе́ніє ми́ра». Сего́ ра́ди і ми, помина́юще іспо́лненноє ві́ри му́жество твоє́, пресла́вная му́ченице, ублажа́єм тя, глаго́люще:","Ра́дуйся, до́блественная страстоте́рпице, в защи́ту ві́ри Правосла́вния подвиза́вшаяся;","ра́дуйся, наві́тов вра́жиїх му́драя разори́тельнице.","Ра́дуйся, Іконі́йськаго гра́да учи́тельнице;","ра́дуйся, і́дольськой су́єтной ле́сти обличи́тельнице.","Ра́дуйся, ві́рних сми́сли воня́ми доброді́телей твої́х благово́нствующая;","ра́дуйся, смрад стра́стний благода́тію, сви́ше ті да́нною, отгоня́ющая.","Ра́дуйся, е́ллинськия куми́ри, я́ко прах, уничижи́вшая;","ра́дуйся, твої́ми по́двиги, і́же к Бо́гу, тьми нача́льника низложи́вшая.","Ра́дуйся, го́рняя, па́че до́льних, восхожде́нія в се́рдці твоє́м положи́ти возлюби́вшая;","ра́дуйся, Христу́ Го́споду, Человіколю́бцю, всю себе́ преда́вшая.","Ра́дуйся, подо́бно первому́ченице Фе́клі, мног наро́д сло́вом Бо́жиїм просвіти́вшая;","ра́дуйся, неві́рних к Боже́ственній ві́рі приве́дшая.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 6","ps":["Пропові́дницю чуде́с і сла́ви Бо́жия яви́ла єси́ себе́, до́блестная му́ченице Параске́во, после пресла́внаго ісціле́нія в темни́ці, от Христа́ Го́спода тебі́ дарова́ннаго. Єму́же возсила́я благода́рственная моле́нія, ра́достно ми вопіє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́, я́ко світоза́рная звізда́, обагри́вшися ка́плями кро́вними, і Боже́ственною благода́тію отгна́ла єси́ безбо́жия тьму, му́ченице Параске́во, просвіти́вши ві́рния, чту́щия твоя́ до́блественния по́двиги. Ті́мже восхваля́юще тя, усе́рдно вопіє́м ті:","Ра́дуйся, богому́драя ді́во, Христо́вих страсте́й о́бщнице;","ра́дуйся, в темни́ці ті су́щей, а́нгельськаго посіще́нія сподо́бльшаяся.","Ра́дуйся, в отра́ду болі́зней твої́х ору́дія страсте́й Христо́вих созерца́вшая;","ра́дуйся, Честни́й Крест і терно́вий віне́ць нетлі́ннаго Жениха́ твоєго́, Христа́, узре́вшая.","Ра́дуйся, я́зви Го́спода на ті́лі твоє́м носи́вшая;","ра́дуйся, от всіх язв Ті́мже Го́сподом чрез а́нгела ісцеле́нная.","Ра́дуйся, я́ко То́йже Госпо́дь дарова́л тебі́ крі́пость і прему́дрость, є́йже не возмого́ша проти́витися всі противля́ющіїся і́стині;","ра́дуйся, от крове́й твої́х сві́тлую себі́ ри́зу істка́вшая.","Ра́дуйся, я́ко тобо́ю от мно́гих ран грі́шнії ісціля́ються;","ра́дуйся, я́ко тобо́ю от разли́чних болі́зней, с ві́рою тя призива́ющії, здра́віє приє́млють.","Ра́дуйся, уз гріхо́вних ско́рая ріши́тельнице;","ра́дуйся, о всіх христия́нах пред престо́лом Бо́жиїм ві́рная моли́твеннице.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 7","ps":["Хотя́щу безу́мному мучи́телю іге́мону жела́ніє своє́ улучи́ти і па́ки покуша́ющуся ласка́тельними словеси́ тебе́, свята́я му́ченице Параске́во, от і́стиннаго Бо́га обрати́ти к поклоне́нію і́долом; ти же, я́ко богому́драя ді́ва, вразумля́я єго́ в сує́тстві і́долов, рекла́ єси́ єму́: «Покажи́ мі, іге́моне, бого́в, ї́хже ти мни́ши ісцели́вших м'я от ран», і по велі́нію мучи́теля прише́дши в храм і́дольський, помоли́лася єси́ єди́ному і́стинному Бо́гу, от Єго́же Свята́го і́мене всі і́доли падо́ша і разси́пашася в прах, во увіре́ніє, я́ко єди́н єсть Бог, прославля́ємий во Святі́й Тро́йці, Єму́же вку́пі со святи́ми а́нгелами ви́ну вопіє́ши: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ безчелові́чія я́рость звірообра́зний мучи́тель, єгда́ тебе́, свята́я му́ченице Параске́во, повелі́ на дре́ві пові́сити і свіща́ми горя́щими опаля́ти твоя́ діви́чеськая ребра́. Сіє́ пачеєсте́ственноє терпі́ніє твоє́ благогові́йно воспомина́юще, похвала́ми блажи́м тя сицеви́ми:","Ра́дуйся, многообра́зния болі́зні за Царя́ Христа́ Бо́га претерпі́вшая;","ра́дуйся, я́ко пред лице́м челові́чеським а́ще і му́ку прия́ла єси́, упова́ніє же твоє́ безсме́ртія іспо́лнено єсть.","Ра́дуйся, я́ко пові́шена била́ єси́ на дре́ві Христа́ ра́ди, на Кресті́ расп'я́таго, да вінце́м нетлі́нія от Него́ ув'язе́шися;","ра́дуйся, я́ко стро́гана била́ єси́ по ребро́м, Ісу́са ра́ди копіє́м в ребро́ прободе́ннаго, да Ца́рствієм Єго́ Небе́сним наслади́шися.","Ра́дуйся, я́ко огнь любве́ к Бо́гу в се́рдці твоє́м возжгла́ єси́;","ра́дуйся, я́ко за Того́ свіща́ми о́гненними пали́ма била́ єси́.","Ра́дуйся, тверді́йшая адама́нта в терпі́нії твоє́м показа́вшаяся;","ра́дуйся, во ві́рі во Христа́ Го́спода кріпча́є па́че ка́мене, в му́жестві непоколеби́мом преби́вшая.","Ра́дуйся, я́ко огне́м опаля́єма, о́гненною му́дростію пла́мень угаси́ла єси́ єсте́ственний;","ра́дуйся, я́ко свіщу́ неугаси́му душе́вную соблю́дши, вошла́ єси́ со Христо́м, Женихо́м твої́м, в черто́г Небе́сний.","Ра́дуйся, я́ко чуде́сними і́скрами стра́сті умертви́вши, де́монськия полки́ страда́льчеськи побіди́ла єси́;","ра́дуйся, я́ко страда́ніями твої́ми мног наро́д к позна́нію і́стиннаго Бо́га привела́ єси́.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 8","ps":["Стра́нноє і стра́шноє святи́я му́ченици Параске́ви страда́ніє ви́дяще, ві́рнії удивля́хуся зіло́: ка́ко мла́да отрокови́ця су́щи, в ю́ностнім тілесі́ такова́я му́жественно за Христа́ терпи́ть му́ки, сле́знаго іспо́лнишася умиле́нія? Неві́рнії же тре́петом одержи́ми і чуде́сними і́скрами опаля́ємі от А́нгела, біжа́ху. Ми же, прославля́юще ди́внаго во святи́х Бо́га, вопіє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь Сладча́йший Ісу́с сла́дость, весь жела́ніє тебі́ бисть, свята́я му́ченице Параске́во: сла́дці бо Єго́ ра́ди го́ркія терпі́ла єси́ му́ки, глаго́лющи к мучи́телю: «Вра́же нечести́вий іге́моне, что неі́стовствуєши на христия́ни? Ні ца́рства у тебе́ от'я́х, ні гра́да твоєго́ разори́х, но бу́їми словеси́ увіща́ти м'я помишля́єши. Аз пло́ті моєя́ не щажду́ за Христа́ моєго́, зане́ Он лю́бить м'я: к Нему́ пойду́ і Того́ бу́ду неві́ста. Той мене́ спасе́ть от рук враг мої́х і да́руєть мі жизнь ві́чную». Помина́юще сицева́я твоя́ словеса́ і до́блественния по́двиги твоєго́ іспові́дничества, вопіє́м ті:","Ра́дуйся, зло́би неві́рних не устраши́вшаяся;","ра́дуйся, тва́ри па́че Созда́вшаго не послужи́вшая.","Ра́дуйся, во є́же сопротивля́тися враго́м Бо́жиїм, в духо́вноє всеору́жіє благода́ті Бо́жієй обле́кшаяся;","ра́дуйся, і́долом німи́м і глухи́м в ка́пищі і́дольськом не покло́нившаяся.","Ра́дуйся, і́менем всеси́льнаго Го́спода і твоє́ю к Нему́ моли́твою вся і́доли та́мо сокруши́вшая;","ра́дуйся, де́монов кова́рствія Боже́ственною си́лою упраздни́вшая.","Ра́дуйся, томле́нія мучи́телей Кресто́м Госпо́днім, я́ко держа́вним ору́жієм, му́жеськи побіди́вшая;","ра́дуйся, о́гненноє опале́ніє і жже́ніє ді́вственнаго тілесе́ твоєго́ во воню́ ми́ра Христу́ Бо́гу прине́сшая.","Ра́дуйся, ві́ру, наде́жду і любо́в к Бо́гу сохра́ншая;","ра́дуйся, побі́ди віне́ць от ру́ки Христа́ Жизнода́вця приє́мшая.","Ра́дуйся, ріко́, іспо́лненная благода́ті Бо́жия вода́ми;","ра́дуйся, істо́чниче, кип'я́щий чуде́с ізлія́нії.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 9","ps":["Всі́ми богокра́сними лі́потами доброді́телей украси́вши себі́, прехва́льная му́ченице Параске́во, яви́лася єси́ тве́рда і непоколеби́ма во іспові́данії ві́ри Христо́ви. Сего́ ра́ди а́нгельськоє єстество́ ве́лією возра́довася ра́достію, узрі́вше му́жественную крі́пость твою́ і тве́рдоє твоє́ упова́ніє. І ми сли́шавше, ка́ко посрами́ся лука́вий враг, от ді́ви побіжда́єм, і ка́ко Сам Христо́с Бог досто́йно вінча́єть тя му́ченицю, ку́пно с тобо́ю ра́достно вопіє́м прославля́ющему тя Го́споду: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий язи́к не возмо́жеть восхвали́ти ді́ла твоя́ і вели́кия страда́льчеськия твоя́ по́двиги по достоя́нію, сла́вная му́ченице Параске́во. Кто бо по́вість страда́нія твоя́ і доброді́телі? На суди́щі бо іспові́давши і́стиннаго Бо́га, от безчелове́чних мучи́телей претерпі́ла єси́ лю́тая, болі́зненная страда́нія; і в сих жесто́ких болі́зніх би́вши па́лицями біє́ма, желі́зними ноготьми́ строга́єма і огне́м пали́ма, нічто́же і́но віща́ла єси́ к Созда́телю твоєму́, то́кмо сіє́: «Спаси́ м'я, Го́споди, недосто́йную рабу́, не разлучи́ мене́, Христе́, от Твоєго́ жела́нія!» Смире́нно помина́юще сицева́я твоя́ страда́нія, умиле́нную піснь прино́сим ті, глаго́люще:","Ра́дуйся, кро́вію страда́нія твоєго́ Христу́ Бо́гу уневі́стившаяся;","ра́дуйся, страсте́м Христо́вим подража́вшая.","Ра́дуйся, любве́ ра́ди Госпо́дні жесто́кия муче́нія претерпі́вшая;","ра́дуйся, от Небе́снаго Царя́ благолі́пний віне́ць восприя́вшая.","Ра́дуйся, я́ко всім ві́рним воспомина́ніє твоє́ пресла́дко;","ра́дуйся, я́ко всій Це́ркві Христо́вой і́м'я твоє́ прече́стно.","Ра́дуйся, досточу́дноє а́нгелом і челові́ком зрі́лище би́вшая;","ра́дуйся, і са́мих мучи́телей непобіди́мим терпі́нієм твої́м удиви́вшая.","Ра́дуйся, я́ко Сам Госпо́дь сви́ше призрі́ на твоя́ страда́нія;","ра́дуйся, я́ко Сам Той Подвигополо́жник похвали́ твоя́ по́двиги.","Ра́дуйся, ді́вам добро́то і похвале́ніє;","ра́дуйся, му́чеником красото́ і ві́рним утіше́ніє.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, о ті́лі твоє́м вся́чеськи небрегла́ єси́, свята́я му́ченице Параске́во. Єгда́ бо на тя і ме́чноє на смерть осужде́ніє ізи́де от беззако́ннаго мучи́теля, ти под меч о́стрий, а́ки под віне́ць кра́сний, ра́достно потекла́ єси́; і во главу́ усікнове́на би́вши, душе́ю твоє́ю воспари́ла єси́ в черто́г Жениха́ твоєго́ Безсме́ртнаго, Христа́ Бо́га, Єму́же ви́ну на Небесі́х ни́ні воспіва́єши: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ била́ єси́ крі́пка і непоколеби́ма во іспові́данії ві́ри в Трієди́наго Бо́га. Сего́ ра́ди многоболе́зненная страда́нія от мучи́теля претерпі́ла єси́ і, до́брі сконча́вши тече́ніє твоє́, віне́ць от Христа́ Бо́га прия́ла єси́, і а́нгельських ликостоя́ній на Небесі́ сподо́билася єси́. Ті́мже воспомина́юще твоя́ по́двиги, ублажа́єм тя, многострада́льная:","Ра́дуйся, тече́ніє му́ченичеськаго путі́ до́брі сконча́вшая;","ра́дуйся, ві́ру безсме́ртному Жениху́ Христу́ до сме́рти сохра́ншая.","Ра́дуйся, в житії́ твоє́м богоуго́дними ді́ли Го́сподеві послужи́вшая;","ра́дуйся, за любо́в ко Христу́ Бо́гу всю мирську́ю суєту́ отве́ргшая.","Ра́дуйся, си́лою сви́ше на брань проти́ву сил преіспо́дніх препоя́санная;","ра́дуйся, побідоно́сною сла́вою во ви́шніх от Христа́ Побіди́теля оді́янная.","Ра́дуйся, ору́жієм благоволе́нія Бо́жия вінча́нная на землі́;","ра́дуйся, цві́том неув'яда́ємим укра́шенная на Небесі́.","Ра́дуйся, христия́ном крі́пкоє прибі́жище;","ра́дуйся, ві́рним тве́рдоє заступле́ніє.","Ра́дуйся, безпомо́щних защи́тительнице;","ра́дуйся, си́рих покрови́тельнице.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше вся́коє побіжда́ється, і мно́гоє мно́жество хвале́бних пі́сней, воспису́ємих ті, ність дово́льно по достоя́нію восхвали́ти тя, прехва́льная му́ченице Параске́во. Оба́че моли́твами твої́ми получа́юще от Христа́ Бо́га неісче́тная благодія́нія, благода́рні су́ще, поє́м о тебі́ Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Возсія́вши нам, я́ко світи́ло світоза́рноє, мрак де́монський от челові́к твої́ми мольба́ми отгоня́єши, свята́я му́ченице Параске́во, приє́мши бо благода́ть ціли́ти неду́ги, всім ві́рним, притека́ющим к тебі́ с моли́твою, подає́ши ісціле́ніє: кровоточи́вії бо і прокаже́ннії прикоснове́нієм к ра́ці моще́й твої́х очища́ються, глусі́ї сли́шать, разсла́бленнії здра́ві бива́ють призива́нієм свята́го твоєго́ і́мене. Ми же, помина́юще ско́роє заступле́ніє твоє́, вопіє́м ті:","Ра́дуйся, благово́нная сми́рно, Це́рков Христо́ву благоуха́ющая;","ра́дуйся, благонаде́жная моли́твеннице, фиміа́м моли́тви о нас к Бо́гу принося́щая.","Ра́дуйся, мирополо́жнице ісціле́ній неоску́дная;","ра́дуйся, сокро́вище Бо́жиїх даро́в неіждива́ємоє.","Ра́дуйся, ча́ше, от оби́лія до́му Бо́жия че́рплющая ра́дость;","ра́дуйся, сосу́де, от ісполне́нія Христо́ва приє́млющий всіх благ небе́сних сла́дость.","Ра́дуйся, благода́тную ро́су ісціле́ній всім ві́рним істоча́ющая;","ра́дуйся, ско́рбния сердца́ неду́жних дарова́нієм ісціле́ній ободря́ющая.","Ра́дуйся, я́ко Христо́с Бог за до́блественная твоя́ страда́нія сла́ву і велелі́піє на тя возложи́л єсть;","ра́дуйся, я́ко тебі́ Цар ца́рствующих і Госпо́дь госпо́дствующих блаже́нство Ца́рствія Своєго́ дарова́л єсть.","Ра́дуйся, Ца́рствія Христо́ва сонасле́днице;","ра́дуйся, сла́ви Бо́жієй соприча́стнице.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 12","ps":["Благода́ть от Бо́га дана́ ті єсть подава́ти ісціле́нія всім тре́бующим, я́ко от істо́чника пребога́таго, храни́ти же і соблюда́ти от разли́чних болі́зней, бід і скорбе́й вся́каго челові́ка, ві́рою, любо́вію і благогове́нієм честна́я твоя́ страда́нія воспомина́ющаго і почита́ющаго. Моли́твеннаго твоєго́ о нас предста́тельства і благода́тних дарова́ній не лиши́ і нас, многострада́льная Христо́ва страстоте́рпице. Да і ми, здра́ві су́ще ті́лом і ду́хом, в ни́нішней і бу́дущей жи́зні о тебі́ поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м твоя́ крі́пкия по́двиги, почита́єм страда́нія, хва́лим долготерпі́ніє, ублажа́єм святу́ю твою́ кончи́ну, сла́вим твоє́ в не́мощнім ті́лі непобіди́моє му́жество, і́мже на землі́ і на Небесі́ просла́вилася єси́, свята́я і добропобі́дная му́ченице Параске́во. І в честь твої́х побідоно́сних по́двигов і страда́ній похва́льная воспису́єм ті сія́:","Ра́дуйся, от а́нгельських чино́во в сожи́тельство їх любе́зно прия́тая;","ра́дуйся, от ді́вственних лико́во в черто́г небе́сний ра́достно введе́нная.","Ра́дуйся, от му́ченичеських полко́в под віне́ць сла́ви провожда́ємая во гла́сі ра́дованія;","ра́дуйся, от небе́сних жи́телей приє́млющая о Го́споді цілова́ніє.","Ра́дуйся, я́ко мзда твоя́ мно́га єсть на Небесі́х;","ра́дуйся, я́ко ра́дость твоя́ ві́чна єсть во сві́тлості святи́х.","Ра́дуйся, в небе́сном черто́зі Боже́ственнаго Жениха́ твоєго́ со а́нгели Єго́ веселя́щаяся;","ра́дуйся, лицезрі́нієм Всеблага́го Го́спода та́мо вку́пі со святи́ми наслажда́ющаяся.","Ра́дуйся, душе́вних і тіле́сних неду́гов на́ших ціли́тельнице;","ра́дуйся, душеспаси́тельних благ і небе́сних даро́в пода́тельнице.","Ра́дуйся, я́ко тобо́ю от неча́янния сме́рті сохрани́тися упова́єм;","ра́дуйся, я́ко твої́м заступле́нієм ві́чную жизнь от Христа́ Бо́га улучи́ти благонаде́жно ча́єм.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 13","ps":["О свята́я прему́драя і всехва́льная му́ченице, неві́сто Христо́ва Параске́во! От благогові́йних серде́ць приноси́мую ті, а́ще і недосто́йную, хвале́бную піснь сію́ прийми́ от нас, я́ко усе́рдную же́ртву серде́ць, лю́б'ящих тя і че́ствующих святу́ю па́м'ять твою́. Охраня́й нас моли́твами твої́ми святи́ми, і вся лю́ди, притека́ющия к честні́й іко́ні твоє́й і с любо́вію лобиза́ющия ю, ізбавля́й от вся́каго зла́го обстоя́нія і ско́рби. Да ти́хоє і безмо́лвноє житіє́ пожи́вше в ни́нішнем ві́ці, блаже́нство ві́чноє наслі́дим, і ку́пно с тобо́ю і всі́ми святи́ми ви́ну сподо́бимся воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом честну́ю і вселюбе́зную чистоту́ твоєго́ сердця́, многострада́льная Параске́во, непоро́чно сохра́нши, а́нгелом собесі́дниця би́ти сподо́билася єси́. С ни́миже воспіва́я трисвяту́ю піснь Бо́гу на небесі́, усли́ши і нас, ві́рою і любо́вію чту́щих тя і вопію́щих ті хвале́нія сія́ на землі́:","Ра́дуйся, отрокови́це, Бо́гом Отце́м предуста́вленная би́ти сообра́зной в страда́нії о́бразу Си́на Єго́;","ра́дуйся, і Си́ном Бо́жиїм укрепле́нная на по́двиги страда́льчеськия.","Ра́дуйся, і́стинную ві́ру в Животворя́щую і Єдиносу́щную Тро́йцю свя́то соблю́дшая;","ра́дуйся, свято́є целому́дріє і ді́вственную непоро́чность до́брі сохра́ншая.","Ра́дуйся, я́ко ра́достно уневі́стилася єси́ безсме́ртному Небе́сному Жениху́ Христу́;","ра́дуйся, земна́го обру́чника па́че Небе́снаго зна́ти не восхоті́вшая.","Ра́дуйся, я́ко цвіт чистоти́, в неув'яда́ємой сла́ві цвіту́щая;","ра́дуйся, я́ко крин, воня́ми твої́х доброді́телей нам благоуха́ющая.","Ра́дуйся, в Небе́сном вертогра́ді неізрече́нною ра́достію наслажда́ющаяся;","ра́дуйся, красні́йшаго па́че сино́в челові́чеських зрі́нієм та́мо утіша́ющаяся.","Ра́дуйся, убіли́вшая ри́зи твоя́ в кро́ві А́гнчей на землі́;","ра́дуйся, в ли́кі ді́вственниць предстоя́щая Бо́жиєму А́гнцю на небесі́.","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Кондак 1","ps":["Ізбра́нной Бо́гом от ро́да благоро́днаго, Іконі́йськаго гра́да, прему́дрой і всехва́льной неві́сті Христо́ві, я́ко ізбавля́ємії тобо́ю от іскуше́ній і бід, благода́рственная пі́нія і хвале́нія воспису́єм ті моли́твенници твої́, свята́я і многострада́льная му́ченице Параске́во. Ти же, імі́я дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да со умиле́нієм і ра́достію зове́м ті:","Ра́дуйся, Параске́во, неві́сто Христо́ва всехва́льная."]},{"h":"Молитва","ps":["Свята́я неві́сто Христо́ва, многострада́льная му́ченице Параске́во! Ві́ми, я́ко от ю́ности твоєя́ ти все́ю душе́ю твоє́ю і всім се́рдцем твої́м возлюби́ла єси́ Царя́ Сла́ви, Христа́ Спаси́теля, і Єму́ єди́ному уневі́стилася єси́, разда́вши імі́нія твоя́ неіму́щим і бі́дним. Ти си́лою благоче́стія твоєго́, твої́м цілому́дрієм і пра́ведностію, я́ко луча́ми со́лнечними, просія́ла єси́, жи́вши свя́то среди́ неві́рних і безбоя́зненно пропові́давши їм Христа́ Бо́га. Ти, от дній ю́ности твоєя́, науче́нная твої́ми роди́телями, всегда́ благогові́йно че́ствовала дні іскупи́тельних страсте́й Го́спода на́шего Ісу́са Христа́, Єго́же ра́ди і сама́ доброво́льно пострада́ла єси́. Ти, десни́цею А́нгела Бо́жия от неісці́льних ран ди́вно ісцеле́нная і восприя́вшая неізрече́нную сві́тлость, ізуми́ла єси́ неві́рних мучи́телей. Ти, і́менем Го́спода на́шего Ісу́са Христа́ і си́лою моли́тви твоє́я в ка́пищі язи́чеськом всіх і́долов до́лу пове́ргши, в прах сокруши́ла єси́ я. Ти, опаля́ємая свіща́ми, єди́ною моли́твою твоє́ю ко всеси́льному Го́споду угаси́ла єси́ огнь єсте́ственний, і тім же пла́менем, чуде́сне возжже́нним чрез А́нгела Бо́жия, попали́вши неі́стових беззако́нников, мног наро́д привела́ єси́ к позна́нію і́стиннаго Бо́га. Ти, во сла́ву Го́спода прия́вши ме́чноє глави́ твоєя́ усіче́ніє от мучи́телей, до́блественно сконча́ла єси́ страда́льчеський твой по́двиг, возше́дши душе́ю твоє́ю на Небеса́, в черто́г вожделі́ннаго твоєго́ Жениха́ Христа́ Царя́ Сла́ви, ра́достно сре́тшаго тя сим небе́сним гла́сом: «Ра́дуйтеся, пра́веднії, я́ко му́чениця Параске́ва увінча́ся!» Ті́мже і ми днесь приве́тствуєм тя, многострада́льная, і, взира́юще на святу́ю твою́ іко́ну, с умиле́нієм вопіє́м ті: всечестна́я Параске́во! Ві́ми, я́ко ве́ліє і́маши дерзнове́ніє ко Го́споду: умоли́ у́бо Єго́, Человіколю́бця, і о нас предстоя́щих і моля́щихся ті. Да пода́сть Он і нам, я́коже тебі́, терпі́ніє і благоду́шіє в біда́х і ско́рбних обстоя́ніях; да да́руєть Он, хода́тайством твої́м і заступле́нієм, ра́достноє, благоде́нственноє і ми́рноє житіє́, здра́віє же і спасе́ніє, і во всем благо́є поспіше́ніє возлю́бленному на́шему оте́честву да ниспо́слеть свято́є Своє́ благослове́ніє і мир, і всім правосла́вним христия́ном да пода́сть твої́ми святи́ми моли́твами утвержде́ніє во ві́рі, благоче́стії і свя́тості, преспі́яніє же в христия́нськой любві́ і вся́кой доброді́телі; да очи́стить нас грі́шних от вся́кия скве́рни і поро́ка; да огради́ть нас святи́ми Свої́ми а́нгелами, да засту́пить, сохрани́ть і поми́луєть всіх свято́ю Своє́ю благода́тію і соді́лаєть наслі́дниками і прича́стниками Небе́снаго Своєго́ Ца́рствія. І та́ко улучи́вше спасе́ніє твої́ми святи́ми моли́твами, предста́тельством і заступле́нієм, всесла́вная неві́сто Христо́ва Параске́во, просла́вим всі пречестно́є і великолі́поє і́м'я ди́внаго во святи́х Свої́х і́стиннаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Прему́драя і всехва́льная Христо́ва му́чениця Параске́ва, / му́жеськую крі́пость приї́мши, / же́нськую же не́мощ отве́ргши, / дия́вола побіди́ і мучи́теля посрами́, / вопію́щи і глаго́лющи: / прийді́те, ті́ло моє́ мече́м ссіци́те і огне́м сожги́те, / аз бо, ра́дующися, іду́ ко Христу́, Жениху́ моєму́. / Тоя́ моли́твами, Христе́ Бо́же, // спаси́ ду́ші на́ша."]},{"h":"Інший тропар, глас 8","ps":["І́же ві́руя і му́жеством душе́вним, тезоімени́тне, / дия́вола посрами́ла єси́ / і мучи́тельськоє преще́ніє і ра́ни до́блественне побіди́ла єси́, / му́ченице Параске́во, вопія́: / мече́м сосеця́йте і огне́м сожиза́йте ті́ло моє́, / я́ко да, ра́дуюся, прийду́ Жениху́ моєму́ Христу́ Бо́гу. // Єго́же моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Всесвято́є і непоро́чноє муче́ніє прине́сши, / я́ко ві́но пречестно́є, безсме́ртному Жениху́ Христу́, / А́нгельськоє ликостоя́ніє возвесели́ла єси́ / і побіди́ла єси́ де́монськия ко́зні. / Сего́ ра́ди тя че́стно ві́рою чтим, // му́ченице Параске́во многострада́льная."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпице Христо́ва Параске́во, і чтим честна́я страда́нія Твоя́, я́же за Христа́ претерпі́ла єси́."]}],"notes":[]},{"u":"Акафіст святителю Митрофану, єпископу Воронезькому","e":"Akathist to St Mitrophan, Bishop of Voronezh","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, многоціле́бний істо́чниче і моли́твенниче о душа́х на́ших, святи́телю о́тче Митрофа́не, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́ зову́щих:","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний бил єси́, святи́телю о́тче Митрофа́не: впери́в бо ум в Боже́ственная, вре́менная і земна́я пренебре́гл єси́, ті́мже і всели́ся в тя Пресвяти́й Дух, Єго́же благода́тію сві́тло украше́н єси́. Сего́ ра́ди тебе́, на Небесі́ і на землі́ просла́вленному, вопіє́м си́це:","Ра́дуйся, я́ко чистото́ю і святи́нею А́нгелом уподо́бился єси́;","ра́дуйся, я́ко посто́м і бді́нієм безстра́стія дости́гл єси́.","Ра́дуйся, світи́льниче Боже́ственнаго сві́та;","ра́дуйся, моли́тв благово́нноє кади́ло.","Ра́дуйся, ві́рних непрело́жноє утвержде́ніє;","ра́дуйся, неві́рних богому́дренноє обличе́ніє.","Ра́дуйся, христия́н непости́дноє прибі́жище;","ра́дуйся, благоче́стія стіно́ необори́мая.","Ра́дуйся, крі́пкоє корми́ло Це́ркве Христо́ви;","ра́дуйся, непоколеби́мий сто́лпе Правосла́вія.","Ра́дуйся, апо́стольських преда́ній ві́рний храни́телю;","ра́дуйся, та́їн Бо́жиїх і́стинний строї́телю.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще от святи́х моще́й твої́х приснотеку́щий істо́чник ісціле́ній, благогові́нія і ра́дости іспо́лнені, благодари́м Бо́га, ди́вно прославля́ющаго святи́я Своя́, вопію́ще Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом, просвіще́нним сви́ше, вразумля́я заблу́ждших, побо́рник бил єси́ і́стинния Христо́ви Це́ркве, єгда́ в ца́рствующем гра́де Москві́ суєму́дреннії лжеучи́теліє на собо́рі святи́тельськом отверзо́ша нечести́вая уста́ своя́ на єя́ хуле́ніє. Ми же от ми́сленних волко́в ізба́вльшеся, ві́рно взива́єм ті:","Ра́дуйся, цівни́це Ду́ха Свята́го, бряця́ющая сла́ву Бо́жию во спасе́ніє челові́ком;","ра́дуйся, гро́ме, сокруша́яй єрети́чеськоє злоче́стіє.","Ра́дуйся, мо́лніє, попаля́ющая пле́вели неві́рія;","ра́дуйся, я́сноє зерца́ло апо́стольських преда́ній.","Ра́дуйся, немо́лчний благові́стниче велі́ній Христо́вих;","ра́дуйся, ві́рний наста́вниче богому́дрія.","Ра́дуйся, мона́шествующих сла́во;","ра́дуйся, архієре́єв боже́ственноє удобре́ніє.","Ра́дуйся, златоза́рноє світи́ло, просвіща́ющеє зе́млю Ру́ськую;","ра́дуйся, наде́жний хода́таю нам Ца́рствія Небе́снаго.","Ра́дуйся, я́ко твої́м к Бо́гу моле́нієм от а́да свобожда́ємся;","ра́дуйся, я́ко твої́м предста́тельством ра́йськия жи́зні сподобля́ємся.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лі Ви́шняго чудоді́йствующей, нікто́же притека́яй к тебі́, преблаже́нне о́тче, отхо́дить тощ: неду́гующим бо яви́лся єси́ ісціле́ніє, сліпи́м прозрі́ніє, хроми́м утвержде́ніє, і всі благові́рнії лю́діє, ско́раго тя помо́щника стяжа́вше, ра́достно Бо́гу воспіва́ють: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй в се́рдці своє́м огнь любве́ Боже́ственния, спасе́нія ра́ди душ челові́чеських па́стирськи подвиза́лся єси́, богому́дре, проти́ву ко́зней дия́вольських і побіди́тельним ору́жієм креста́ разсіка́л єси́ сі́ті лука́ваго, я́ко паучи́ну. Ті́мже прийми́ от нас піснь сію́:","Ра́дуйся, ра́бе Бо́жий, благи́й і ві́рний;","ра́дуйся, досто́йний ді́лателю вертогра́да Христо́ва.","Ра́дуйся, учи́телю смире́нія і цілому́дрія;","ра́дуйся, о́бразе кро́тости і послуша́нія.","Ра́дуйся, му́жу жела́ній;","ра́дуйся, Пропові́дниче чуде́с Бо́жиїх.","Ра́дуйся, наста́вниче діл до́брих;","ра́дуйся, тве́рдоє огражде́ніє Христо́ви Це́ркве.","Ра́дуйся, огневи́дний сто́лпе, наставля́яй на путь спасе́нія;","ра́дуйся, світоза́рний світи́льниче, ві́рния просвіща́яй.","Ра́дуйся, неізчерпа́ємий сосу́де благода́ті Христо́ви;","ра́дуйся, чи́стоє прия́телище Ду́ха Свята́го.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю мирська́го житія́ і тяжелоно́сния страсте́й во́лни преше́д, обрі́л єси́ ти́хоє приста́нище і, в пусти́ню всели́вся, нелі́ностно рабо́тал єси́ Христу́ во мно́зі долготерпі́нії. Отню́дуже руководи́л єси́ в Ца́рствіє Бо́жиє і духо́вная ча́да своя́, научи́в їх єди́ними усти́ і єди́ним се́рдцем пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще ди́вния о Бо́зі труди́ твоя́, святи́телю о́тче Митрофа́не, прихожда́ху к тебі́ іздале́ча жа́ждущії глаго́лов живота́ ві́чнаго: поне́же ти учи́л і твори́л єси́, наставля́л сло́вом і житіє́м свої́м. Сего́ ра́ди любо́вію вопіє́м ті:","Ра́дуйся, апо́столов преє́мниче;","ра́дуйся, святи́телей сопресто́льниче.","Ра́дуйся, преподо́бних собесі́дниче;","ра́дуйся, пра́ведних украше́ніє.","Ра́дуйся, ві́нче воздержа́нія;","ра́дуйся, благосінноли́ственноє дре́во, пото́ками ра́йськими воспита́нноє.","Ра́дуйся, безпомо́щних спаси́тельноє призрі́ніє;","ра́дуйся, цві́те нетлі́нія.","Ра́дуйся, я́ко отчужде́нієм вре́менних благ стяжа́л єси́ блаже́нство нищети́ духо́вния;","ра́дуйся, я́ко самово́льним обнища́нієм обрі́л єси́ сокро́вище благ ві́чних.","Ра́дуйся, я́ко во глубину́ смире́нія прини́кл єси́;","ра́дуйся, я́ко на висоту́ безстра́стія возше́л єси́.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́, путеводи́вшей дре́вле волхво́в к пра́ведному Со́лнцю, подо́бен бил єси́, всехва́льне о́тче, сам восходя́ благода́тію Бо́жиєю от си́ли в си́лу, і приводя́ с собо́ю ко Христу́ Бо́гу всіх і́щущих спасе́нія. Ті́мже і ми, немерца́ющим сія́нієм сла́ви твоєя́ озаря́ємі, согла́сно вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше в тебі́ воро́нежстії лю́діє пе́рваго архипа́стиря, я́ко А́нгела, зна́меніє небе́сния благода́ті нося́ща, возра́довашася ра́достію неізглаго́ланною: ти же, до́брі внима́я себе́ і всему́ ста́ду, в не́мже тя Дух Святи́й поста́ви єпи́скопа, пасл єси́ усе́рдно Це́рков Го́спода і Бо́га, я́ко сло́во возда́ти хотя́. Сего́ ра́ди ублажа́єм тя, о́тче Митрофа́не, зову́ще:","Ра́дуйся, челові́че Бо́жий, преподо́бієм, а́ки по́ясом злати́м, препоя́санний;","ра́дуйся, дру́же Христо́в, святи́тельством, а́ки би́сером драги́м, преукраше́нний.","Ра́дуйся, во́їне Христо́в непобіди́мий;","ра́дуйся, стра́же до́ма Бо́жия неуси́пний.","Ра́дуйся, восхожде́нія в се́рдці своє́м к Небесі́ положи́вий;","ра́дуйся, слове́сния о́вці Христо́ви на живоно́сних па́житях воспита́вий.","Ра́дуйся, я́ко не попусти́л єси́ душетлі́нному зві́рю расхи́тити ста́до твоє́;","ра́дуйся, я́ко от Небе́снаго Пастиренача́льника пра́ведноє воздая́ніє прия́л єси́.","Ра́дуйся, возлюби́вий благолі́піє до́му Бо́жия;","ра́дуйся, в само́м себі́ храм Трийпоста́сному Божеству́ угото́вавий.","Ра́дуйся, я́ко во умерщвле́нном тілесі́ ри́зою нетлі́нія оді́ян єси́;","ра́дуйся, я́ко із гро́ба заре́ю безсме́ртія нас осіява́єши.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Слове́с єва́нгельських, є́же не скрива́ти себі́ сокро́вища на землі́, ві́рний блюсти́тель показа́лся єси́, всеблаже́нне Митрофа́не, єгда́ достоя́ніє своє́ му́дре расточи́л єси́, снабдіва́я убо́гих і посо́бствуя благові́рному імпера́тору Петру́ в сооруже́нії корабле́й на побіжде́ніє неві́рних ага́рян, не ві́дущих пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ ца́рству правосла́вному благотво́рний світ вели́ких доброді́телей твої́х, святи́телю о́тче Митрофа́не, о ни́хже благодаря́ще Отця́ Небе́снаго, к тебі́ я́ко к при́сному о нас моли́твеннику, взива́єм си́це:","Ра́дуйся, наста́вниче цілому́дрія;","ра́дуйся, смире́нія Христо́ва і́стинний подража́телю.","Ра́дуйся, олтаря́ Госпо́дня благогові́йний служи́телю;","ра́дуйся, святи́телей украше́ніє.","Ра́дуйся, і́ночеськаго равноа́нгельнаго житія́ ревни́телю;","ра́дуйся, безмо́лвія дре́вніх богоно́сних оте́ць подража́телю.","Ра́дуйся, ми́лости струє́ неізсяка́ємая;","ра́дуйся, благоутро́бія храни́лище неоску́дноє.","Ра́дуйся, си́рих благонаде́жноє приста́нище;","ра́дуйся, вдови́ць ско́роє заступле́ніє.","Ра́дуйся, мно́жество душ уневі́стивий Христу́;","ра́дуйся, ку́пно с ни́ми пребива́яй в ра́дості Го́спода твоєго́.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́щу ні́когда благові́рному імпера́тору Петру́ бесі́довати с тобо́ю, призва́н бил єси́ во двор ца́рський: єгда́ же внеза́пу узрі́л о́крест єго́ ізвая́нія язи́чеськая, а́біє возврати́лся єси́ всп'ять, не убоя́вся преще́нія царе́ва, і гото́в бил єси́ ду́шу свою́ положи́ти па́че, не́же растли́ти ми́сленния о́чі сердця́ своєго́ неподо́бним виді́нієм, науча́я ві́рних єди́ному живо́му Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя по благоче́стію ревни́теля позна́в благові́рний цар і ви́дя небоя́зненноє твоє́ на смерть ізволе́ніє, повелі́ су́єтная ізвая́нія низри́нути. Ми же свято́му дерзнове́нію твоєму́ чудя́щеся, вопіє́м:","Ра́дуйся, непрекло́нний іспові́дниче Правосла́вія;","ра́дуйся, ре́вностний защи́тниче благоче́стія.","Ра́дуйся, священнотаї́нниче благода́ті;","ра́дуйся, велегла́сний пропові́дниче покая́нія.","Ра́дуйся, апо́столов немо́лчная уста́;","ра́дуйся, Це́ркве непоколеби́мий сто́лпе.","Ра́дуйся, па́стирю до́брий;","ра́дуйся, я́ко неприча́стен яви́лся єси́ лицеприя́тію.","Ра́дуйся, я́ко і́стину не обину́яся свиді́тельствовал єси́;","ра́дуйся, я́ко твої́м посо́бієм сокруша́ються ко́зні вра́жия.","Ра́дуйся, я́ко всім ві́рним воспомина́ніє твоє́ пресла́дко;","ра́дуйся, я́ко всій Це́ркві Христо́вой і́м'я твоє́ прече́стно.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до благода́ті небе́сния явля́ється ни́ні во о́чію всіх ві́рних: долготерпіли́вий і многоми́лостивий Госпо́дь не прогні́вался на ни до конця́ за беззако́нія на́ша, но, пом'яну́в щедро́ти Своя́, дарова́ нам тебе́, досточу́дне о́тче, засту́пника ізря́дна, та́ко вознесе́ рог спасе́нія на́шего, да ви́ну поє́м Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ во ви́шніх, но і ни́жніх не оставля́єши, святи́телю о́тче Митрофа́не, при́сно со Христо́м ца́рствуєши, і о нас грі́шних моли́тви к Нему́ возсила́єши: не то́чію бо припа́дающих к цільбоно́сним моща́м твої́м, но і дале́че отстоя́щих, призива́ющих же всечестно́є і́м'я твоє́, предста́тельством твої́м соблюда́єши от вся́каго зла. Ті́мже во умиле́нії зове́м ті:","Ра́дуйся, прибі́жище на́ше во всіх ско́рбіх;","ра́дуйся, ско́рий помо́щниче всіх в біда́х су́щих.","Ра́дуйся, ціли́телю болі́зней душе́вних вку́пі і тіле́сних;","ра́дуйся, на неви́димиі враги́ на́ша си́льний побо́рниче.","Ра́дуйся, посіти́телю в не́мощі лежа́щих;","ра́дуйся, уті́шителю в біда́х су́щих.","Ра́дуйся, я́ко тобо́ю престає́ть рида́ніє;","ра́дуйся, я́ко тобо́ю подає́ться ра́дость.","Ра́дуйся, я́ко Христу́ до́блественно послі́довал єси́;","ра́дуйся, я́ко Сладча́йшему Ісу́су до конця́ послужи́л єси́.","Ра́дуйся, я́ко наслажда́єшися лицезрі́нія Бо́жия;","ра́дуйся, я́ко сподо́бился єси́ зрі́ти невече́рній день Ца́рствія Єго́.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́кия ско́рби і труди́ до́блественно претерпі́л єси́, ше́ствуя по путі́ спасе́нія до масти́тия ста́рости, облече́н во всеору́жіє Бо́жиє, во пло́ті а́ки безпло́тен, умерщвля́я стра́сті і сокруша́я наві́ти миродержи́теля тьми ві́ка сего́. Ті́мже Небе́сним сопричи́слен си́лам, ку́пно с ни́ми воспіва́єши Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії недоумі́ють ізобрази́ти оби́лія любве́ твоєя́, є́юже, отходя́ к Творцю́, преіспо́лнен бил єси́ к ча́дом твої́м о Го́споді: восхоті́в бо і по отше́ствії своє́м при́сно поуча́ти їх, я́ко живи́й, завіща́л єси́ їм вся потре́бная ко спасе́нію. Сего́ ра́ди із глубини́ серде́ць вопіє́м ті:","Ра́дуйся, благоче́стно тече́ніє сконча́вий;","ра́дуйся, ві́ру соблюди́й всеці́лу.","Ра́дуйся, ору́жієм благоволе́нія Бо́жия вінча́нний на землі́;","ра́дуйся, вінце́м нетлі́нія украше́нний на Небесі́.","Ра́дуйся, до́лу вели́чієм чуде́с блиста́ющий;","ра́дуйся, го́ре луча́ми Трисо́лнечнаго Сві́та осіява́ємий.","Ра́дуйся, я́ко в пресві́тлих ра́йських оби́теліх вселя́єшися.","Ра́дуйся, я́ко лице́м к лицю́ Боже́ственнаго сві́та причаща́єшися.","Ра́дуйся, я́ко с небе́сних висо́т на мольби́ на́ша призира́єши;","ра́дуйся, я́ко в со́ніях і виді́ніях во бла́го нам явля́єшися.","Ра́дуйся, я́ко моли́твами твої́ми от ві́чния сме́рти свобожда́ємся;","ра́дуйся, я́ко предста́тельством твої́м безконе́чния жи́зні сподобля́ємся.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 10","ps":["І́же всім челові́ком хотя́й спасти́ся і в ра́зум і́стини прийти́, Госпо́дь і Бог наш Ісу́с Христо́с яви́л нам нетлі́нноє ті́ло твоє́ на землі́, я́ко живоно́сную купі́ль, врачу́ющую вся́ку болі́знь і вся́ку я́зю в лю́діх. Ті́мже благода́рственно вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ спасе́нія прибега́ющим к тебі́, святи́телю Митрофа́не, і в бива́ємих от тебе́ знаме́ніїх, іспові́дающих вели́чіє Бо́жиє. Сего́ ра́ди, уще́дрени твої́м чудоді́йственним о нас ко Христу́ Бо́гу хода́тайством, вопіє́м ті:","Ра́дуйся, царе́й благочести́вих побо́рниче;","ра́дуйся, архієре́єв правосла́вних укріпле́ніє.","Ра́дуйся, ца́рства правосла́внаго защи́тниче;","ра́дуйся, Це́ркві святі́й утвержде́ніє.","Ра́дуйся, пре́жде сме́рти умертви́вий плоть свою́;","ра́дуйся, предвкуси́вий жизнь ві́чную, пре́жде вни́тія в селе́нія ра́йськая.","Ра́дуйся, уме́рий ми́ру пре́жде кончи́ни твоєя́;","ра́дуйся, воскреси́й ду́хом во Христі́, пре́жде успе́нія твоєго́.","Ра́дуйся, я́ко от оби́телі земни́я во Оби́тель Небе́сную пресели́лся єси́;","ра́дуйся, я́ко от Оби́телі Небе́сния во оби́телі земни́я благотворя́ нисхо́диши.","Ра́дуйся, я́ко і по отше́ствії твоє́м с на́ми пребива́єши.","Ра́дуйся, я́ко і по уме́ртвії твоє́м умерщвле́нния гріхми́ ду́ші моли́твами твої́ми оживля́єши.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє, приноси́моє ни́ні, а́ще би і преви́ше челові́чеськаго би́ло, не довлі́ло би к Славосло́вію Бо́га, дарова́вшаго тебі́ благода́ть ісціле́ній. Сего́ ра́ди недоумі́юще благохвали́ти єго́ по достоя́нію, смиренному́дренно вопіє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельна світи́льника, просвіща́ющаго ду́ші на́ша ві́рою, ви́дим тебі́, преблаже́нне о́тче, пред Престо́лом Бо́жиїм стоя́ща, і твої́м блиста́нієм озаря́ємі, зове́м ті такова́я:","Ра́дуйся, па́стирю преди́вний;","ра́дуйся, учи́телю прему́дрий.","Ра́дуйся, сто́лпе ві́ри непоколеби́мий;","ра́дуйся, насади́телю благи́х.","Ра́дуйся, чистоти́ селе́ніє;","ра́дуйся, печа́льних утіше́ніє.","Ра́дуйся, си́рих пита́телю;","ра́дуйся, оби́димих предста́телю.","Ра́дуйся, прему́дрости Бо́жия прия́телище;","ра́дуйся, істо́чниче неізчерпа́ємия благода́ті ісціле́ній.","Ра́дуйся, провозві́стниче Боже́ственних велі́ній;","ра́дуйся, сокро́вище милосе́рдія Бо́жия неістощи́моє.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть, сви́ше ті да́нную позна́вше, благогові́йно лобиза́єм святолі́пноє ізображе́ніє всечестна́го лиця́ твоєго́, є́же благоволи́л єси́ ди́вно яви́ти нам. Ті́мже благода́рственно вопіє́м Христу́ Бо́гу на́шему: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ к Бо́гу отше́ствіє, святи́телю Митрофа́не, почита́єм свяще́нную па́м'ять твою́, велича́єм ре́вность по Бо́зі, хва́лим долготерпі́ніє, сла́вим незло́біє, і ублажа́єм кончи́ну твою́: на сме́ртнім бо о́дре возлежа́, жела́нієм возжела́л облещи́ся во вели́кий а́нгельський о́браз, нарече́н бил Мака́рієм, блаже́нства тезоімени́тим, блаже́н бив воі́стинну, я́ко Ца́рствіє Небе́сноє наслі́довал єси́. Ті́мже моля́щеся усе́рдно, о є́же сподо́битися і нам неосужде́нно предста́ти на Стра́шноє суди́ще Христо́во, взива́єм ті:","Ра́дуйся, у Престо́ла Бо́жия те́плий о нас предста́телю;","ра́дуйся, му́жу жела́ній, просла́вивший Бо́га в тілесі́ і в душе́ своє́й.","Ра́дуйся, добропобі́дний во́їне Царя́ Небе́снаго;","ра́дуйся, вождю́ прему́дрий ра́тующим проти́ву сил а́дових.","Ра́дуйся, я́ко с горя́щим світи́льником срі́тил єси́ Христа́;","ра́дуйся, я́ко от Него́ благода́ть ісціле́ній прия́л єси́.","Ра́дуйся, я́ко благоволе́нієм Пресвяти́я Богоро́диці возвели́чен єси́;","ра́дуйся, я́ко во сві́тлостіх святи́х пребива́єши.","Ра́дуйся, я́ко со проро́ки і апо́столи ликовству́єши;","ра́дуйся, я́ко со святи́телі і му́ченики просла́влен єси́.","Ра́дуйся, я́ко с преподо́бними і пра́ведними весели́шися;","ра́дуйся, я́ко со всі́ми ізбра́нними Бо́жиїми при́сно торжеству́єши.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О вели́кий і пречу́дний о́тче Митрофа́не, прийми́ благоутро́бно сіє́ ма́лоє моле́ніє на́ше, і твої́м благоприя́тним хода́тайством ізба́ви нас от всіх враг ви́димих і неви́димих, от вся́кия напа́сти і ско́рби, от напра́сния сме́рти і бу́дущия му́ки, да сподо́бимся с тобо́ю і со всі́ми святи́ми во ві́ки воспіва́ти Бо́гу Спаси́телю на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел земни́й і челові́к небе́сний бил єси́, святи́телю о́тче Митрофа́не: впери́в бо ум в Боже́ственная, вре́менная і земна́я пренебре́гл єси́, ті́мже і всели́ся в тя Пресвяти́й Дух, Єго́же благода́тію сві́тло украше́н єси́. Сего́ ра́ди тебе́, на Небесі́ і на землі́ просла́вленному, вопіє́м си́це:","Ра́дуйся, я́ко чистото́ю і святи́нею А́нгелом уподо́бился єси́;","ра́дуйся, я́ко посто́м і бді́нієм безстра́стія дости́гл єси́.","Ра́дуйся, світи́льниче Боже́ственнаго сві́та;","ра́дуйся, моли́тв благово́нноє кади́ло.","Ра́дуйся, ві́рних непрело́жноє утвержде́ніє;","ра́дуйся, неві́рних богому́дренноє обличе́ніє.","Ра́дуйся, христия́н непости́дноє прибі́жище;","ра́дуйся, благоче́стія стіно́ необори́мая.","Ра́дуйся, крі́пкоє корми́ло Це́ркве Христо́ви;","ра́дуйся, непоколеби́мий сто́лпе Правосла́вія.","Ра́дуйся, апо́стольських преда́ній ві́рний храни́телю;","ра́дуйся, та́їн Бо́жиїх і́стинний строї́телю.","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, многоціле́бний істо́чниче і моли́твенниче о душа́х на́ших, святи́телю о́тче Митрофа́не, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́ зову́щих:","Ра́дуйся, Митрофа́не, вели́кий і пресла́вний чудотво́рче."]},{"h":"Молитва перша","ps":["О святи́телю о́тче Митрофа́не, се ми грі́шнії, нетлі́нієм честни́х моще́й твої́х і мно́гими благодія́ньми, чуде́сно соді́янними і содіва́ємими тобо́ю, уві́рившеся, іспові́дуєм, я́ко і́маши ве́лію благода́ть у Го́спода Бо́га на́шего, і всесмире́нно ко твоєму́ благосе́рдію припа́дающе, тебі́ мо́лимся си́це: моли́ о нас Христа́ Бо́га на́шего, да низпо́слеть всім чту́щим святу́ю па́м'ять твою́ і усе́рдно к тебі́ прибега́ющим бога́тия ми́лости Своя́; да утверди́ть во святі́й Своє́й Правосла́вной Це́ркві живи́й дух пра́вия ві́ри і благоче́стія, дух ві́дінія і любве́, дух ми́ра і ра́дости о Ду́сі Свя́те, да вся ча́да єя́, чи́ста су́ща от мирськи́х іскуше́ній і плотськи́х по́хотей і зла́го ді́йствія злих духо́в, ду́хом і і́стиною покланя́ються Єму́, і усе́рдно о соблюде́нії за́повідей Єго́ ко спасе́нію душ свої́х да потща́ться. Па́стирем єя́ да дасть Госпо́дь святу́ю ре́вность попече́нія о спасе́нії люде́й, во є́же неві́рующія просвіти́ти, неве́дущия наста́вити, сомня́щіяся вразуми́ти, отпа́дшия от Правосла́вния Це́ркве к ней возврати́ти, ве́рующия во ві́рі соблюсти́, грі́шния на покая́ніє подви́гнути, ка́ющіяся уті́шити і во іспра́вленії жи́зні утверди́ти, і та́ко вся лю́ди ко угото́ванному ві́чному Ца́рству святи́х Єго́ привести́. Умоли́ Го́спода, уго́дниче Христо́в: ві́рних рабо́в Єго́, в ско́рбі і печа́лі день і нощ вопію́щих к Нему́, многоболі́зний вопль да усли́шить і да ізведе́ть от поги́белі живо́т наш. Всім же в держа́ві лю́дем да да́руєть благи́й Бог наш мир, тишину́, безм'яте́жіє і ізоби́ліє плодо́в земни́х, па́че же ко ісполне́нію за́повідей Єго́ тща́ніє нелі́ностноє; і да ізба́вить ца́рствующия гра́ди, град сей і вся іни́я гра́ди і ве́сі, от гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних, междоусо́бния бра́ні, смертоно́сния я́зви і от вся́каго зла. Єй, святи́телю Бо́жий, да устро́їши моли́твами твої́ми вся блага́я душа́м і тілесе́м на́шим; да і ми просла́вим в душа́х і тілесі́х на́ших Го́спода і Бо́га на́шего, Ісу́са Христа́, Єму́же со Отце́м і Святи́м Ду́хом сла́ва і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́телю о́тче Митрофа́не! Прийми́ сіє́ ма́лоє моле́ніє от нас, грі́шних раб Бо́жиїх (імена́), к тебі́ прибіга́ющих, і те́плим твої́м предста́тельством умоли́ Го́спода і Бо́га на́шего, Ісу́са Христа́, я́ко да пода́сть нам согріше́ній на́ших проще́ніє і ізба́вить нас от бід, печа́лей, ско́рби і болі́зней душе́вних і тіле́сних, обдержа́щих нас; да пода́сть вся на по́льзу настоя́щаго житія́ на́шего потре́бная; да да́руєть нам сконча́ти житіє́ сіє́ привре́менноє в покая́нії і да сподо́бит нас, грі́шних і недосто́йних, Небе́снаго Ца́рствія Своєго́, во є́же со всі́ми святи́ми сла́вити Єго́ безконе́чноє милосе́рдіє, со Безнача́льним Єго́ Отце́м і Святи́м і Животворя́щим Єго́ Ду́хом, во ві́ки віко́в."]},{"h":"Тропар, глас 4","ps":["Пра́вило ві́ри і о́браз кро́тости, / сло́вом і житіє́м, па́стві твоє́й, о́тче смиренному́дре Митрофа́не, бил єси́. / Ті́мже і во сві́тлостіх святи́х, / со́лнця світлі́йше возсія́л єси́, / вінце́м нетлі́нія і сла́ви украша́єм, / моли́ Христа́ Бо́га, // страні́ на́шей і гра́ду твоєму́ в ми́рі спасти́ся."]},{"h":"Кондак, глас 8","ps":["Воздержа́нієм ті́ло ду́ху порабо́тив, / ду́шу же равноа́нгельну сотвори́в, / святи́тельською оді́ялся єси́ оде́ждою, я́ко віне́ць свяще́нства, / і ни́ні, всіх Влади́ці предстоя́, // моли́, всеблаже́нне Митрофа́не, умири́ти і спасти́ ду́ші на́ша."]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче Митрофа́не, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Олександру, Свірському чудотворцю","e":"Akathist to our Venerable Father Alexander of Svir, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і чудотво́рче, преподо́бний о́тче Алекса́ндре, возсія́вий ми́рові, я́ко звізда́ богосві́тлая, житія́ твоєго́ добро́тою і мно́жеством чудотворе́ній, восхваля́єм тя любо́вію в пі́сніх духо́вних: ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгельський нрав імі́л єси́, о́тче преподо́бне, і я́ко безпло́тний, непоро́чно житіє́ соверши́л єси́ на землі́, ди́вний о́браз соверше́нства духо́внаго нам оста́вив, да подража́єм доброді́телем твої́м, і зове́м ті си́це:","Ра́дуйся, благочести́вих роди́телей плод богодарова́нний;","ра́дуйся, непло́діє ро́ждших тя разріши́вий.","Ра́дуйся, сі́тованіє їх на ра́дость преложиви́й;","ра́дуйся, от пеле́н Бо́гом ізбра́нний.","Ра́дуйся, от утро́би ма́тернія на слу́жбу Єму́ предуста́вленний;","ра́дуйся, от ю́ности Єго́ Єди́наго всім се́рдцем возлюби́вий.","Ра́дуйся, вся кра́сная ми́ра сего́ ні во что же вміни́вий;","ра́дуйся, посто́м і бді́нієм моли́твенним плоть твою́ удручи́вий.","Ра́дуйся, непоро́чний сосу́де Бо́жия благода́ті;","ра́дуйся, жили́ще Ду́ха Свята́го, украше́нноє чистото́ю.","Ра́дуйся, му́жу жела́ній духо́вних;","ра́дуйся, главо́, освяще́нная десни́цею Всеви́шняго.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь ду́шу твою́, я́ко ни́ву благовозді́ланную к плодоно́сію духо́вному, от ю́ности к іска́нію єди́наго на потре́бу напра́ви твой по́мисл, преподо́бне, ті́мже любве́ ра́ди Христо́ви, роди́телей твої́х і дом оте́чеський оста́вил єси́, вся́каго пристра́стія су́єтнаго свободи́вся, прите́кл єси́ в пусти́нную оби́тель Валаа́мськую на по́двиги і́ночеськия, зови́й спаса́ющему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богопросвіще́нним пости́гл єси́ суєту́ ми́ра сего́ і непостоя́нство, в не́мже ра́дость сміня́ється ско́рбію, благополу́чіє наві́тується неча́янними бі́дами. Ті́мже ві́чних нетлі́нних благ возжелі́л єси́, о́тче преподо́бне, і сія́ взиска́ти потща́лся єси́ отрече́нієм мирськи́х благ і во́льною нището́ю, подвига́я нас зва́ти тебі́:","Ра́дуйся, пусти́ннаго безмо́лвія люби́телю;","ра́дуйся, смире́нія і нестяжа́нія рачи́телю.","Ра́дуйся, і́стиннаго самоотверже́нія соверше́нний о́бразе;","ра́дуйся, і́ночеськаго равноа́нгельськаго житія́ всеїзря́дноє явле́ніє.","Ра́дуйся, пра́вило ві́ри і благоче́стія;","ра́дуйся, зерца́ло терпіли́ваго послуша́нія.","Ра́дуйся, безмо́лвіє і́ночеськоє возлюби́вий;","ра́дуйся, сле́зи духо́вния стяжа́вий.","Ра́дуйся, пла́чем вре́менним блаже́нство ві́чноє сниска́вий;","ра́дуйся, моли́твами непреста́нними прило́ги вра́жія сокруши́вий.","Ра́дуйся, бді́нієм і труди́ плоть твою́ ду́хові покори́вий;","ра́дуйся, посто́м і воздержа́нієм стра́сті укроти́вий.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Всеви́шняго осіне́нний і укріпля́ємий, в і́ночестім постриже́нії власо́в глави́ твоєя́, все плотсько́є мудрова́ніє отложи́л єси́, преподо́бне, і я́ко во́їн благоїску́сний, схи́му і́ночеськую в броню́ спасе́нія стяжа́в, і непобіди́мим ору́жієм Креста́ Христо́ва вооружи́вся, крі́пко ра́товал єси́ проти́ву врага́ неви́димаго – дия́вола, смире́нієм глубо́ким побіжда́я єго́ вознесе́нную горди́ню, і ви́ну вопія́ ко Го́споду: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я слез істо́чник ізоби́льний, уго́дниче Бо́жий, і умиле́нія ве́лію благода́ть, хліб твой слеза́ми ороша́л єси́ і питіє́ пла́чем растворя́л, от преізби́тка жела́нія Боже́ственнаго і любве́ ко Го́споду. Ті́мже і ми убла́жаєм тя зва́нії си́ми:","Ра́дуйся, крі́пости і му́жества тезоимени́тий подви́жниче;","ра́дуйся, ангелоподо́бний челові́че.","Ра́дуйся, Царя́ Небе́снаго во́їне добропобі́дний;","ра́дуйся, валаа́мськия оби́телі пло́де до́брий.","Ра́дуйся, пустинножи́телю благоприя́тний;","ра́дуйся, моли́твенниче неусипа́ющий.","Ра́дуйся, по́стниче ізря́дний;","ра́дуйся, безмо́лвниче ди́вний.","Ра́дуйся, по́двигом дре́вніх богоно́сних отце́в послі́дователю;","ра́дуйся, їх терпі́нію і трудо́м подража́телю.","Ра́дуйся, благовре́менно моги́лу себі́ іскопа́вий;","ра́дуйся, о сме́ртнім часі́ непреста́нно помишля́вий.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ря іскуше́ній і устремле́ній дия́вольських не возможе́ поколеба́ти хра́мини твоєя́ душе́вния, преподо́бне о́тче, осно́вана бо бі на тве́рдем ка́мені ві́ри во Христа́, і храни́ма трезве́нієм і моли́твами непреста́нними, і́миже ви́ну противобо́рствовал єси́ врагу́ спасе́нія челові́чеськаго, і непреткнове́нно восходи́л єси́ по стезе́м доброді́телей к соверше́нству духо́вному в мі́ру во́зраста Христо́ва, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав похваля́єма себе́ от челові́к, убоя́лся єси́ превозноше́нія су́єтнаго, о́тче богому́дре, і я́ко і́стинний смире́нія о́браз, уми́слил єси́ убіжа́ти в пусти́ню неізві́данную, на рі́ку Свир, на мі́сто, сви́ше тебі́ указа́нноє во виді́нії чу́дном, да та́мо і невозбра́нно єди́ному Бо́гу порабо́таєши, іді́же ми срі́таєм тя благохвале́нії си́ми:","Ра́дуйся, смири́вшагося до ра́бія зра́ка Христа́ Го́спода благи́й послі́дователю;","ра́дуйся, святи́х Єго́ за́повідій усе́рдний ісполни́телю.","Ра́дуйся, ді́вственниче душе́ю і ті́лом;","ра́дуйся, трудолю́бче нелицемі́рний.","Ра́дуйся, презрі́вий сла́ву челові́чеськую су́єтную;","ра́дуйся, сокруши́вий сі́ті тщесла́вія і горди́ні.","Ра́дуйся, попра́вий високоу́мія душевре́дную пре́лесть;","ра́дуйся, усво́ївий себі́ свято́є смире́ніє Христо́во.","Ра́дуйся, іспо́лнивий вся обі́ти і́ночества;","ра́дуйся, украси́вийся да́рами благода́ті Бо́жия.","Ра́дуйся, по благода́ті приє́мий власть на ду́хи нечи́стия;","ра́дуйся, ні во что же вміни́вий тіх устраше́нія і приви́дінія.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 5","ps":["Світоза́рний луч озари́ в нощні́й темноті́ мі́сто пусти́нноє, на не́мже всели́тися прише́л єси́, преподо́бне, зна́менуя собо́ю сві́тлость душі́ твоєя́, і пламені́ющеє любо́вію ко Го́споду се́рдце твоє́, іді́же благоприя́тно бисть Творцю́ твоє́ проізволе́ніє рабо́тати Єму́ в преподо́бії і свя́тості, і пі́ти Єму́ та́мо хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше а́нгельстії чи́нове равноа́нгельськоє житіє́ твоє́, о́тче богоблаже́нне, смире́нія твоєго́ глубину́, моли́тви неотсту́пность, воздержа́нія тве́рдость і ве́лію ре́вность ду́ха твоєго́ о чистоті́, удиви́шася і просла́виша Человіколю́бця Бо́га, укріпля́ющаго не́мощноє єстество́ челові́чеськоє. Ми же ублажа́єм тя і зове́м:","Ра́дуйся, світи́лниче пусти́нний, просвіти́вий страну́ коре́льськую сія́нієм твої́х доброді́телей;","ра́дуйся, мона́шествующих ди́вноє украше́ніє.","Ра́дуйся, кри́не благоуха́нний пусти́ннаго прозябе́нія;","ра́дуйся, дре́во благопло́дноє небе́снаго насажде́нія.","Ра́дуйся, возлюби́вий благолі́піє до́му Бо́жия;","ра́дуйся, в самі́м себі́ храм Трийпоста́сному Божеству́ угото́вивий.","Ра́дуйся, преподо́бієм і пра́вдою оді́янний;","ра́дуйся, сою́зом доброді́телей удобре́нний.","Ра́дуйся, пома́заніє приє́мий от Свята́го Ду́ха;","ра́дуйся, освяще́нний сосу́де благода́ті Бо́жия.","Ра́дуйся, ра́бе Христо́в, благи́й і ві́рний;","ра́дуйся, слуго́ Госпо́день і́стинний.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник по́двигов твої́х в пусти́ні Сви́рстій яви́лся лове́ць звіре́й ди́віїх, і́же гнав єле́ня в дубра́ві непроходи́мій, смотре́нієм Бо́жиїм обрі́те хра́мину твою́, преподо́бне о́тче: ви́дів же тя во пло́ті А́нгела, зна́меніє благода́тнаго озаре́нія на лице́ своє́м нося́ща, стра́ха і ра́дости іспо́лнися і, припа́д к честни́м твої́м стопа́м, во умиле́нії се́рдця возопи́ Зижди́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в пусти́ні Сви́рстій богосві́тлоє світи́ло, і на спасе́нія стезю́ наста́вил єси́ мно́гі ду́ші челові́чеськія, яви́ бо тя Христо́с наста́вника і учи́теля і́ноком пустиннолюби́вим, і́же стека́хуся к тебі́, я́ко о́вці к па́стирю, могу́щу упасти́ їх на па́жити живоно́сній. Ті́мже, я́ко сотвори́вшаго і научи́вшаго, че́ствуєм тя си́ми похва́льними словеси́:","Ра́дуйся, істо́чниче богодухнове́нних уче́ній;","ра́дуйся, храни́лище ізоби́льнаго умиле́нія.","Ра́дуйся, одушевле́нния скрижа́ли зако́на Госпо́дня;","ра́дуйся, немо́лчний пропові́дниче Єва́нгелія Христо́ва.","Ра́дуйся, за́повіді Госпо́дні іспо́лнивий, і о́ним научи́вий ученико́в твої́х;","ра́дуйся, ліни́вих подви́гнувий к ісправле́нію твої́ми христоподража́тельними нра́ви.","Ра́дуйся, немощни́х укріпи́вий да́нною ті от Го́спода благода́тію;","ра́дуйся, скорб'я́щих уті́шивий сла́достію твої́х слове́с.","Ра́дуйся, грі́шних к покая́нію напра́вивий;","ра́дуйся, ю́ния уцілому́дривий.","Ра́дуйся, сострада́нія іспо́лненний;","ра́дуйся, в ми́лості бога́тий.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ Человіколю́бець Госпо́дь просла́вити мі́сто по́двигов твої́х, о́тче, посла́ А́нгела Своєго́ благовісти́ти тебі́, я́ко бу́деть на мі́сті том оби́тель і́ноком во спасе́ніє, і в ней храм во і́м'я Святи́я Тро́йці. Ти же явле́нієм безпло́тнаго просвіще́н, с ра́достним тре́петом внима́л єси́ благові́стію небе́сному, зови́й в смире́нії ду́ха Влади́ці А́нгелов і челові́ков: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє благоволе́нія Бо́жия дарова́ся тебі́, преподо́бне, єгда́ безмо́лвствующу ті в ізбра́нній пусти́ні, в нощі́ світ ве́лій облиста́ тя, і Три Му́жа в оде́ждах сві́тлих предста́ша пред тобо́ю, мир тебі́ да́рующе і повеліва́юще, да устро́їши та́мо оби́тель і́ночеськую, і в ней храм во і́м'я Святи́я Тро́йці. Див'я́ся у́бо сему́ пречу́дному в трі́єх а́нгельських ли́ціх Тро́їчеському явле́нію, зове́м ті:","Ра́дуйся, таї́нниче Пресвяти́я і Єдиносу́щния Тро́йці;","ра́дуйся, самови́дче неізрече́ннаго Бо́жия явле́нія.","Ра́дуйся, собесі́дниче світоно́сних а́нгельських сил;","ра́дуйся, созерца́телю лучеза́рнаго Боже́ственнаго виді́нія.","Ра́дуйся, прича́стниче огнезра́чнаго трисо́лнечнаго сія́нія;","ра́дуйся, покло́нниче Триіпоста́снаго Божества́.","Ра́дуйся, в сме́ртнім тілесі́, безсме́ртія заре́ю просвіще́нний;","ра́дуйся, на землі́ небе́снаго посіще́нія удосто́єнний.","Ра́дуйся, смире́нієм висо́кая стяжа́вий;","ра́дуйся, нището́ю бога́тую ми́лость Госпо́дню улучи́вий.","Ра́дуйся, сі́явий слеза́ми ра́дость присносу́щную;","ра́дуйся, приє́мий ісполне́ніє обітова́ній непрело́жних.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 8","ps":["Страннолі́пно яви́лся ті на возду́сі А́нгел Госпо́день в ма́нтії і куко́ли і́ночестім, указу́яй мі́сто, на не́мже храм во і́м'я Живонача́льния Тро́йці імі́л єси́ созда́ти в пусти́ні Сви́рстій, преподо́бне о́тче, єго́же Бо́жиїм поспіше́нієм соверши́в і освяти́в, со уче́ники твої́ми немо́лчния хвали́ возсила́л єси́ в нем Го́сподеві, зови́й: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́ преда́во во́лі Госпо́дней, ученика́ми твої́ми умоле́нний, свяще́нства благода́ть восприя́ти не уклони́лся єси́, о́тче, а́ще і тужа́ше дух твой, ужаса́яся висоти́ сея́, но послуша́ніє яви́л єси́ духо́вним ча́дом твої́м, подвиза́я їх согла́сно зва́ти тебі́:","Ра́дуйся, Безкро́вния Же́ртви досто́йний соверши́телю;","ра́дуйся, олтаря́ Госпо́дня благогові́йний служи́телю.","Ра́дуйся, преподо́бния ру́ці твої́ со мно́гим дерзнове́нієм ко Го́споду воздія́вий;","ра́дуйся, моли́тви теплі́йшия от се́рдця чи́ста к престо́лу Вседержи́теля возноси́вий.","Ра́дуйся, о́браз благоче́стія би́вий твої́м ученико́м;","ра́дуйся, ма́стію свяще́нства ума́щенная главо́.","Ра́дуйся, вождю́ благоїску́сний во́їнов духо́вних;","ра́дуйся, о́тче благому́дрий общежи́тія і́ночеськаго.","Ра́дуйся, сві́ще, в моли́тві к Бо́гу возжже́нная;","ра́дуйся, звіздо́ ко спасе́нію путь ві́рний показу́ющая.","Ра́дуйся, масли́но, єле́й ми́лости Бо́жия істочи́вшая;","ра́дуйся, ча́ше, жа́ждущих уче́нія спаси́тельнаго напоі́вшая.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 9","ps":["Всі і́ноці оби́телі твоєя́ в ра́достний тре́петь прийдо́ша, єгда́ устремле́ніє пото́ка во́днаго, на святу́ю оби́тель твою́ дви́жущеєся, моли́твою твоє́ю укроти́л єси́, і призива́нієм всеси́льнаго і́мене Ісу́с Христо́ва, бу́рному пото́ку тещи́ безвре́дно устро́їл єси́ на благу́ю потре́бу і́ночествующих, є́же ви́дівше духо́вная ча́да твоя́ всеумиле́нно возгласи́ша ку́пно с тобо́ю Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вети́йство челові́чеськоє не довлі́єть ізрещи́ оби́ліє ра́дости духо́вния, є́юже преіспо́лнился єси́, о́тче богоно́сне, єгда́ во вре́м'я моли́тви твоєя́ но́щния, яви́ся ті Пресвята́я Богоро́диця с ли́ком чи́нов а́нгельських і обітова́нії непрело́жними ду́шу твою́ возвесели́, я́ко при́сная Засту́пниця оби́телі твоєя́ бу́деть, снабдіва́ющи і покрива́ющи ю по вся дні. Ті́мже і ми сія́ ра́достния тебі́ прино́сим глаго́ли:","Ра́дуйся, благоволе́нієм Богома́тере осіне́нний;","ра́дуйся, посіще́нієм Цари́ці небесе́ і землі́ уті́шенний.","Ра́дуйся, сли́шавий ми́лостивия от уст Єя́ глаго́ли;","ра́дуйся, приє́мий обітова́ніє крі́пкаго Єя́ оби́телі заступле́нія.","Ра́дуйся, люби́миче Єя́ преі́скренній;","ра́дуйся, ізбра́нниче Си́на Єя́ і Бо́га.","Ра́дуйся, да́ром чудотворе́нія облагода́тствованний;","ра́дуйся, бу́дущая, я́ко настоя́щая прови́дівий.","Ра́дуйся, ри́барем лови́тву чуде́сно умно́живий;","ра́дуйся, непло́дним роди́телем чадоро́діє дарова́вий.","Ра́дуйся, боля́щия здра́ви возста́вивий;","ра́дуйся, та́йная согріше́нія челові́чеськая обличи́вий.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́ші учени́к твої́х, оте́чеськи назида́л єси́ їх, богому́дре, о́ваго сло́вом, о́ваго приме́ром житія́ твоєго́, с кро́тостію облича́я, с любо́вію увіщава́я їх преуспіва́ти в благоче́стії і чистоті́: найпа́че же пред кончи́ною твоє́ю, вся ко спасе́нію душе́вному благопотре́бная запові́дал єси́ їм, і научи́л єси́ їх в моли́твах бо́дрствовати і немо́лчно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ заступле́нія би́ша моли́тви твоя́ чудотво́рче святи́й, всім с ві́рою к тебі́ притека́ющим во вся́кой ско́рби, і́бо чистоти́ ра́ди твоєя́ серде́чния си́ла духо́вная от Бо́га тебе́ дарова́ся боля́щих ісціля́ти, бе́дствующим помога́ти, бу́дущая прориця́ти, я́ко сла́вити бли́жнім і да́льним вели́чія Бо́жія, в тебі́ явле́нная, і зва́ти тебі́ си́це:","Ра́дуйся, врачу́ немздоприє́мний неду́гов челові́чеських;","ра́дуйся, не то́кмо тіле́сних, но і душе́вних болі́зней ізря́дний ціли́телю.","Ра́дуйся, сліпи́м прозрі́ніє дарова́вий;","ра́дуйся, сляче́нних і уві́чних здра́ви сотвори́вий.","Ра́дуйся, бі́сних от дия́вольськаго удруче́нія свободи́вий;","ра́дуйся, ізступле́нним ум здра́вий возврати́вий.","Ра́дуйся, покри́тих стру́пами уврачева́вий;","ра́дуйся, печа́льних уті́шивий.","Ра́дуйся, бе́дствующим на по́мощ ускори́вий;","ра́дуйся, пліне́нним і в темни́ці сідя́щим осла́бу і свобо́ду явле́нієм твої́м дарова́вий.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прине́сл єси́ Пресвяті́й Тро́йце во вре́м'я кончи́ни твоєя́, преподо́бне, і моли́тві, су́щей на усті́х твої́х, пре́дал єси́ святу́ю ду́шу твою́ в ру́ці Жива́го Бо́га, Єго́же от ю́ности возлюби́л єси́, і Єму́же до ста́рости масти́тия рабо́тал єси́ нелицемі́рно; ті́мже со упова́нієм благи́м ра́достно преше́л єси́ к оби́телем небе́сним, со а́нгельськими ли́ки пі́ти Трийпоста́сному Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Ми́рную кончи́ну твою́ ви́дівше твої́ ученици́, вели́кий уго́дниче Бо́жий, скорб разлуче́нія с тобо́ю утіше́нієм благода́тним раствори́ша, в упова́нії всеси́льнаго предста́тельства твоєго́ го́ре у престо́ла Бо́жия, іді́же сли́шиши с любо́вію тебі́ зову́щих:","Ра́дуйся, віне́ць безсме́ртния жи́зні приє́мий от руки́ Вседержи́теля;","ра́дуйся, ликовству́яй в черто́зі Небе́снаго Домовлади́ки.","Ра́дуйся, открове́нним лице́м созерца́яй сла́ву Трисія́ннаго Божества́;","ра́дуйся, со ста́рці білори́зними покланя́яйся Творцю́.","Ра́дуйся, наслі́дниче всесві́тлаго Ца́рствія Христо́ва;","ра́дуйся, граждани́не Ієрусали́ма Го́рняго.","Ра́дуйся, небе́снаго Сіо́на жи́телю;","ра́дуйся, нерукотворе́нних ски́ній ра́йських обита́телю.","Ра́дуйся, по труді́х вре́менния жи́зні, поко́й ві́чний получи́вий;","ра́дуйся, блаже́нство, от ві́ка пра́ведним уготова́нноє, пра́ведно восприя́вий.","Ра́дуйся, луча́ми невече́рняго сві́та сви́ше осія́нний;","ра́дуйся, до́лу вели́чієм чуде́с блиста́яй.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ті прича́стна яви́ся свяще́нная ра́ка, содержа́щая многоціле́бния мо́щі твоя́, чудотво́рче святи́й, ї́хже по лі́тіх мно́зіх яви́ Госпо́дь в ні́дріх земни́х нетлі́нними, ізціле́нія неоску́дно істоча́ющия, і всяк неду́г врачу́ющия си́лою Бо́га, ди́внаго во святи́х Свої́х, ди́вно просла́вльшаго тя на небесі́ і на землі́, Єму́же воспіва́єм: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ра́достную піснь хвали́ і благодаре́нія Человіколю́бцю Бо́гу, просла́вльшему тя в страні́ Украї́нській чудотво́рця ди́внаго і ми́лостиваго, мо́лим тя, преподо́бне о́тче наш: бу́ди хода́тай к Нему́ і моли́твенник при́сний о нас зову́щих ті:","Ра́дуйся, засту́пниче ро́да христия́нськаго;","ра́дуйся, сокро́вищнице да́ров многоразли́чних.","Ра́дуйся, покро́ве, Бо́гом зда́нний;","ра́дуйся, от Бо́га благода́ть ізцеле́ній восприя́вий.","Ра́дуйся, цві́те нетлі́нія, облагоуха́вий Святу́ю Це́рков;","ра́дуйся, заре́ безсме́ртія, от гро́ба пресла́вно возсія́вшая.","Ра́дуйся, щедро́т і ми́лованія стру́є неізсяка́ємая;","ра́дуйся, благоутро́бія істо́чниче неоскудіва́ємий.","Ра́дуйся, любве́ і сострада́нія явле́ніє многочуде́сноє;","ра́дуйся, тіле́с на́ших богодарова́нноє врачева́ніє.","Ра́дуйся, о душа́х на́ших благоприя́тноє предста́тельство.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 13","ps":["О, вели́кий і пресла́вний чудотво́рче, преподо́бне о́тче наш Алекса́ндре! Ми́лостивно прийми́ сіє́ ма́лоє моле́ніє на́ше, і моли́твами твої́ми сохрани́ нас от неду́гов душе́вних і тіле́сних в жи́зні сей, і от гряду́щих муче́ній ві́чних ізба́ви, і сподо́би нас вку́пі с тобо́ю во Ца́рствії Небе́снім ви́ну пі́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський нрав імі́л єси́, о́тче преподо́бне, і я́ко безпло́тний, непоро́чно житіє́ соверши́л єси́ на землі́, ди́вний о́браз соверше́нства духо́внаго нам оста́вив, да подража́єм доброді́телем твої́м, і зове́м ті си́це:","Ра́дуйся, благочести́вих роди́телей плод богодарова́нний;","ра́дуйся, непло́діє ро́ждших тя разріши́вий.","Ра́дуйся, сі́тованіє їх на ра́дость преложиви́й;","ра́дуйся, от пеле́н Бо́гом ізбра́нний.","Ра́дуйся, от утро́би ма́тернія на слу́жбу Єму́ предуста́вленний;","ра́дуйся, от ю́ности Єго́ Єди́наго всім се́рдцем возлюби́вий.","Ра́дуйся, вся кра́сная ми́ра сего́ ні во что же вміни́вий;","ра́дуйся, посто́м і бді́нієм моли́твенним плоть твою́ удручи́вий.","Ра́дуйся, непоро́чний сосу́де Бо́жия благода́ті;","ра́дуйся, жили́ще Ду́ха Свята́го, украше́нноє чистото́ю.","Ра́дуйся, му́жу жела́ній духо́вних;","ра́дуйся, главо́, освяще́нная десни́цею Всеви́шняго.","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і чудотво́рче, преподо́бний о́тче Алекса́ндре, возсія́вий ми́рові, я́ко звізда́ богосві́тлая, житія́ твоєго́ добро́тою і мно́жеством чудотворе́ній, восхваля́єм тя любо́вію в пі́сніх духо́вних: ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, моли́твами твої́ми от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, преподо́бне Алекса́ндре, Сви́рський чудотво́рче."]},{"h":"Молитва","ps":["О свяще́нная главо́, А́нгеле земни́й і челові́че небе́сний, преподо́бне і богоно́сне о́тче наш Алекса́ндре, ізря́дний уго́дниче Пресвяти́я і Єдиносу́щния Тро́йці, явля́яй мно́гія ми́лости живу́щим во святі́й оби́телі твоє́й і всім, с ві́рою і любо́вію притека́ющим к тебі́! Іспроси́ нам вся благопотре́бная к житію́ сему́ вре́менному, і ну́жная к ві́чному спасе́нію на́шему. Посо́бствуй предста́тельством твої́м, уго́дниче Бо́жий, пред Го́сподем на враги́ ви́димия і неви́димия. Ві́рних рабо́в Єго́, в ско́рбі і печа́лі день і нощ вопію́щих к Нему́, многоболі́зненний вопль да усли́шить і да ізведе́ть от поги́белі живо́т наш, да в ми́рі глубо́ці пребу́деть Свята́я Правосла́вная Це́рков Христо́ва, і в благостроє́нії зи́ждеться Оте́чество на́ше, во вся́ком благоче́стії неруши́мо. Бу́ди всім нам, чудотво́рче святи́й, помо́щник ско́рий во вся́кой ско́рби і обстоя́нії, найпа́че же в час кончи́ни на́шея яви́ся нам засту́пник благосе́рдий, да не пре́дани бу́дем на мита́рствіх возду́шних вла́сті зло́бнаго мироде́ржця, но да сподо́бимся непреткнове́ннаго восхо́да в Ца́рствіє Небе́сноє. Єй, о́тче, моли́твенниче наш при́сний! Не посрами́ упова́нія на́шего, не пре́зри смире́нная моле́нія на́ша і предста́тельствуй за нас пред престо́лом Живонача́льния Тро́йці, да сподо́бимся вку́пі с тобо́ю і со всі́ми святи́ми ми, недосто́йнії, в селе́ніїх ра́йських сла́вити вели́чіє, благода́ть і ми́лость єди́наго в Тро́йці Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва, що читається в обителі біля мощей","ps":["О преподо́бне і богоно́сне о́тче наш Алекса́ндре! Смире́нно припа́дающе к ра́ці честни́х твої́х моще́й, мо́лим тя прилі́жно, воздви́гни ру́ці твої́ о нас грі́шних, ко Влади́чиці на́шей Богоро́дице і Присноді́ві Марі́ї, я́ко да пом'яне́ть дре́внія ми́лости Своя́, і́миже обіща́лася неотсту́пна би́ти от оби́телі твоєя́; і пода́сть нам си́лу і крі́пость на враго́в душе́вних, отводя́щих нас от путі́ спаси́тельнаго, да я́вльшеся о́них побіди́телі, в день Стра́шнаго Суда́ усли́шим от тебе́ похва́льний о́ний глас: Се аз і ді́ти, я́же дал мі єси́, Бо́же! І побі́дний віне́ць от побіди́теля враго́в Христа́, Си́на Бо́жия воспри́ймем, і наслі́діє ві́чних благ ку́пно с тобо́ю полу́чим, воспіва́юще Пресвяту́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, і твоє́ ми́лостивоє предста́тельство і заступле́ніє, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["От ю́ности, Богому́дре, жела́нієм духо́вним в пусти́ню всели́вся, єди́наго Христа́ возжела́л єси́ усе́рдно стопа́м в слід ходи́ти; ті́мже і а́нгельстії чи́ни зря́ще тя, удиви́шася, ка́ко с пло́тію к неви́димим ко́знем подвиза́вся, прему́дре, побіди́л єси́ полки́ страсте́й воздержа́нієм, і яви́лся єси́ равноа́нгелен на землі́, Алекса́ндре, преподо́бне. Моли́ Христа́ Бо́га да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Я́ко многосві́тлая звізда́ днесь в страна́х Украї́нських возсія́л єси́, о́тче, всели́вся в пусти́ню, Христо́вим стопа́м послі́довати усе́рдно возжелі́л єси́, і Того́ свято́є і́го на ра́мо твоє́ взем честни́й крест, умертви́л єси́, труди́ по́двиг твої́х тіле́сная взигра́нія. Ті́мже вопіє́м ті: спаси́ ста́до твоє́, є́же собра́л єси́, му́дре, да зове́м ті: ра́дуйся, преподо́бне Алекса́ндре, о́тче наш."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче Алекса́ндре, і чтим святу́ю па́м'ять твою́, наста́вниче мона́хов і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святому апостолу і євангелісту Іоанну Богослову","e":"Akathist to the Holy Apostle and Evangelist John the Theologian","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Го́сподем от мре́жей ри́барських на про́повідь Єва́нгелія і от ловли риб на уловле́ніє челові́ков во світ і́стиннаго богові́дінія, вели́кий апо́столе, учениче́, дру́же і напе́рсниче Христо́в, моли́ єди́наго і́стиннаго Человіколю́бця, Єго́же ти приі́скренні возлюби́л єси́, да поми́луєть нас, і́щущих твоєго́ к Нему́ предста́тельства і зову́щих ті:","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Ікос 1","ps":["А́нгельських сил і вся́кия тва́рі Творця́, Влади́ку і Го́спода, восприє́мшаго плоть на́шу і я́вльшагося на землі́ спасе́нія на́шего ра́ди, узрі́в ходя́ща при мо́рі Галиле́йстім і взива́юща тя со бра́том твої́м, Іоа́нне блаже́нне, в зва́ніє апо́стольства, оста́вль мре́жі ри́барськия і отця́ твоєго́ в корабли́, неукло́нно отто́лі послі́довал єси́ стопа́м Спаси́телевим. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, любве́ ра́ди ко Христу́ отця́ по пло́ті оста́вивий;","ра́дуйся, Христо́м Небе́снаго Отця́ обріти́й.","Ра́дуйся, мир і вся єго́ пре́лести презрі́вий;","ра́дуйся, небе́сная блага́я во воздая́ніє получи́вий.","Ра́дуйся, плоть ду́ху соверше́нно поработи́вий;","ра́дуйся, дух твой Сладча́йшему твоєму́ Учи́телю Ісу́су покори́вий.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 2","ps":["Ви́дя Христо́с Госпо́дь непоро́чную чистоту́ твоєго́ се́рдця, плотськи́ми сластьми́ не омраче́нную, суди́ тебі́ досто́йна би́ти зрі́нія та́їнственних открове́ній, я́ко да, проницяя во глубину́ богосло́вія, возмо́жеши пропові́дати то́є во усли́шаніє всего́ ми́ра. Сего́ ра́ди «син громо́в» от Го́спода нарече́н бил єси́ і Тому́ возопи́л єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом і́стиннаго богопозна́нія озаря́я твою́ ду́шу, ше́ствовал єси́ вослі́д Блага́го Учи́теля твоєго́, поуча́яся із уст Єго́ ісходя́щей прему́дрості, і соверше́ннаго ра́ди твоєго́ незло́бія і ді́вственнаго цілому́дрія бил єси́ возлю́блен Христо́м Господом твої́м. Усли́ши у́бо ни, воспіва́ющія ті си́це:","Ра́дуйся, незло́бія рачи́телю;","ра́дуйся, ді́вства і чистоти́ храни́телю.","Ра́дуйся, любве́ к Бо́гу і бли́жнім учи́телю,","ра́дуйся, до́брих нра́вов наста́вниче.","Ра́дуйся, смиренному́дрія зерца́ло;","ра́дуйся, Боже́ственния благода́ті світи́ло.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 3","ps":["Си́лу Божества́ Христо́ва, сокритую под о́блаком немощна́го челові́чеськаго єстества́ позна́л єси́ я́вно, єгда́ Госпо́дь наш, воскреша́я дщер Іаї́рову і посліди́ преображаяся на Фаво́рі, сподо́би тя со іні́ма двіма́ ученико́ма свиді́теля би́ти такови́х пресла́вних чуде́с. Уви́дів же, я́ко Христо́с єсть Бог і́стинний, із глубини́ се́рдця твоєго́ воззва́л єси́ Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ве́ліє дерзнове́ніє к возлюби́вшему тя Христу́ Си́ну Бо́жию, возле́гл єси́ на пе́рсіх Єго́ при соверше́нії Та́йния Ве́чері, і єгда́ прориця́ше Госпо́дь о преда́теле Своє́м, тогда́ єди́н ти дерзну́л єси́ вопросі́те о і́мені єго́. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, возлю́бленний Христо́в учениче́;","ра́дуйся, при́сний Єго́ дру́же.","Ра́дуйся, невозбра́нно на пе́рсіх Госпо́дніх возлежавий;","ра́дуйся, дерзнове́нно о і́мені предаю́щаго вопроси́вий.","Ра́дуйся, па́че іни́х ко Христу́ ближа́йший;","ра́дуйся, словеса́ Госпо́дня, я́коже сокро́вище многоці́нноє, слагавий в се́рдці своє́м.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 4","ps":["Бу́ря я́рости і зло́бнаго неі́стовства жестокосе́рдих і неблагода́рних іуде́єв, єгда́ воста́ на Христа́ Си́на Бо́жия, тогда́ всі ученици́ Єго́, стра́хом об'яти би́вше, біжа́ша; но ти, любо́в крепльшую к Нему́ імі́я, да́же до Креста́ і сме́рті не отступи́л єси́ от Него́, на вся муки́ Христо́ви взира́я і соболезнуя се́рдцем Ді́ві Ма́тері Бо́жієй, плачущей і рида́ющей. Удивля́яся же кра́йнему милосе́рдію і долготерпі́нію Бо́жию, взива́л єси́ к Пострада́вшему за род челові́чеський: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́ся на Кресті́ пригвожде́нний за гріхи́ на́ша Спас ми́ра і ви́дів тя і Ма́тер Свою́ предстоящия, си́на тя Преблагослове́нній Ді́ві Богоро́диці вдал єсть, глаго́ля Єй: «Же́но, се син Твой, — і тебі́ па́ки: — Се Ма́ти твоя́». Ми же, див'я́щеся любві́ Христо́ві, на тебі́ явле́нній, воспіва́єм си́це:","Ра́дуйся, син Бо́жия Ма́тере би́ти сподо́бивийся;","ра́дуйся, того́ ра́ди найпа́че ко Христу́, я́ко ні́киїм духо́вним родством, присвоївийся.","Ра́дуйся, Ма́тері Бо́жієй досто́йно послужи́вий;","ра́дуйся, Сію́, я́коже ма́тер свою́, во вся́кой че́сти у себ'я́ імі́вий.","Ра́дуйся, і во Успе́нії честно́є і свято́є Єя́ ті́ло ко гро́бу проводивий;","ра́дуйся, со блиста́ющеюся райською ветвію, Арха́нгелом Гавриї́лом принесенною, одру́ Єя́ предшедий.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́ во Асі́ї, отше́д в ню на пропові́даніє сло́ва Бо́жия, я́коже жре́бієм указа́ся тебі́. Но на путі́ твоє́м попусти́ Госпо́дь би́ти тебі́ вве́ржену в мо́ре: благода́ть же Бо́жия, всегда́ с тобо́ю пребива́ющая, сохрани́ тя во вода́х морськи́х жива́, і по четирена́десятих днех повелі́ во́лні морсті́й, да воспенившися ізве́ржеть тя на брег. Єгда́ же узрі́ сія́ учени́к твой Про́хор, уже́ мно́го плакавий о кончи́ні твоє́й, ве́ліїм гла́сом воззва́ чудоді́йствующему Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше єфе́сстії жи́теліє пресла́вноє чу́до, тобо́ю сотворе́нноє, єгда́ о́трока До́мна, умерщвле́ннаго от бі́са, моли́твою твоє́ю воскреси́л єси́, воспі́ша велегла́сно си́лу Бо́га, тобо́ю їм пропові́даннаго, і ізба́вльшеся от гну́снаго ідолослуже́нія, взива́ху тебі́ си́це:","Ра́дуйся, і́стиннаго Бо́га служи́телю;","ра́дуйся, бісо́в прогони́телю.","Ра́дуйся, мертвеци́ си́лою Христо́вою оживля́яй;","ра́дуйся, то́ю жизнь і здра́віє лю́дем возвраща́яй.","Ра́дуйся, помраче́нния умо́м к Сві́ту І́стини призива́яй;","ра́дуйся, пра́вия ві́ри просвіще́нієм к доброді́телі наставля́яй.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 6","ps":["Пропові́дник богоно́сний сло́ва Бо́жия во Єфе́сі бил єси́, і усердствуя о распростране́нії благода́ті єва́нгельськия, утвержда́л єси́ твоє́ уче́ніє зна́меньми вели́кими і чу́дними, ка́пище же Артемидино єди́ною моли́твою низпровергл єси́, да зря́ще сіє́, язи́чници позна́ють Єди́наго Бо́га, Єму́же ми вопіє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ во Єфе́сі, я́коже со́лнце, світ ві́ри Христо́ви, тобо́ю проповеданния, єгда́ злочести́вий Дометія́н воздви́же гоне́ніє на христия́ни; тогда́ і тебі́, я́ко усе́рднаго іспові́дника і́мене Христо́ва, посла́ єпа́рх в Рим свя́зана, іді́же і претерпі́л єси́ стра́шная муче́нія. Тіх ра́ди благоче́стно возглаша́єм ті сицева́я:","Ра́дуйся, Христо́ва ра́ди іспові́данія бієнний;","ра́дуйся, ча́шу смертоно́снаго я́да невре́дно іспи́вий.","Ра́дуйся, в котлі єле́я кип'ящаго не сваривийся;","ра́дуйся, си́лою Христо́вою в лю́тих муче́ніїх ціл сохранивийся.","Ра́дуйся, твої́м неврежденієм ке́саря, му́чащаго тя, устраши́вий;","ра́дуйся, сим же наро́д о вели́чествії Бо́га, от христия́н почита́ємаго, уві́ривий.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 7","ps":["Єгда́ узрі́ мучи́тель, я́ко і люті́йшия муки́, я́же от него́ претерпі́л єси́, не возмого́ша умертви́ти тебі́, тогда́, возмні́в тя безсме́ртна би́ти, во о́стров Па́тмос на ізгна́ніє осужда́єть. Ти же, повину́яся Про́мислу Бо́жию, та́ко благоволи́вшему, благода́рственно воспіва́л єси́ Бо́гу, вся во благо́є устрояющему: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая чудеса́ показа́л єси́ язичником, іща́ обрати́ти їх ко спасителней ві́рі Христо́ві, єгда́ пловущу ті во ізгна́ніє твоє́, повелі́нієм твої́м о́трока утопшаго мо́ре на кора́бль жива́ ізве́рже, бу́ря укроти́ся, вода́ сла́ная в сла́дкую претвори́ся, во́їн от чре́внаго неду́га ісціли́ся, і по прише́ствії твоє́м в Па́тмос, біс питливий, бу́дущая прорицявий, із одержи́маго їм ізгна́ся. Тогда́ всі зря́щії такова́я ди́вная зна́менія, тобо́ю соверша́ємая, прихожда́ху к позна́нію Триіпоста́снаго Бо́га і креща́хуся. Ми же тя ублажа́єм та́ко:","Ра́дуйся, мо́рю і бу́ри повеліва́яй;","ра́дуйся, сатани́нськия ду́хи от челові́к ізгоня́яй.","Ра́дуйся, болі́зні єди́ним сло́вом ісціля́яй;","ра́дуйся, всім в ну́ждах по́мощ подава́яй.","Ра́дуйся, чудеси́ твої́ми ідолопоклонник удиви́вий;","ра́дуйся, уче́нієм твої́м неві́рния во і́стинній ві́рі утверди́вий.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 8","ps":["Стра́нно бі ви́діти жреце́м Аполлоновим, я́ко храм бо́га їх і вся би́вшия в нем і́доли ти єди́ним сло́вом на зе́млю низпровергл єси́. Чудя́щеся у́бо о сем і яря́щеся на таково́є твоє́ дерзнове́ніє, ідо́ша к волхву́ ні́коєму, ве́лію си́лу от сатани́ в себі́ імевшему, прося́ще єго́, да отмсти́ть безче́стіє бо́га їх; он же, сліп сий душе́ю, не ві́дая си́ли, в тебі́ обитающия, покуша́шеся привиді́нії разли́чними тебі́ устраши́ти і на тя наро́д подви́гнути: оба́че сам окая́нний погрузи́ся в мо́ре і та́мо поги́бе, безсильним би́вшим бісо́м спасти́ єго́, ти бо воспрети́л єси́ їм і́менем Ісу́са Христа́ Си́на Бо́жия, Єго́же просла́ви наро́д, чудесе́ свиді́тель, воспі́в: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнен бив любве́ Боже́ственния, яви́лся єси́ вмісти́лище даро́в Свята́го Ду́ха: бу́дущая прорицял єси́, отстоя́щая, я́ко близ су́щая, возвіща́л єси́, неду́жния ісціля́л єси́, жені́ іге́мона на о́строві Патмосе, в болі́зні рожде́нія стра́ждущей, єдва́ на праг до́му єя́ вступив, облегче́ніє дарова́л єси́. Прийми́ у́бо от нас, грі́шних, похвали́ сицеви́я:","Ра́дуйся, благода́ті Бо́жия вмісти́лище;","ра́дуйся, Ду́ха Свята́го обита́лище.","Ра́дуйся, ріко́, чудоточная цільбоно́сния в болі́зніх си́ли;","ра́дуйся, істо́чниче наставле́ній, приводя́щих к позна́нію пра́вия ві́ри.","Ра́дуйся, кова́рства лука́ваго сатани́ облича́яй;","ра́дуйся, ві́рния от ко́зней єго́ защища́яй.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 9","ps":["Вся́коє беззако́ніє істребля́я ре́вностно от среди́ люде́й, к ни́мже по́слан бил єси́, обличи́л єси́ прельще́ніє ідолопокло́нников, і́же почита́ху бі́са, во о́бразі во́лка превели́ка лю́дем являвшегося, і мно́гія от них к ві́рі Христо́ві приве́л єси́: та́же ка́пище Вакхово моли́твою твоє́ю разруши́л єси́, і волхва́ Нукіяна вку́пі с дома́шніми єго́ к покая́нію чудеси́ твої́ми обрати́л єси́. Ті́ї же, от гріха́ ко спасе́нію обрати́вшеся, немо́лчно взива́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ветийство му́дрости челові́чеськия не возмо́жеть ізрещи́, ніже́ ум плотська́го челові́ка постигнута, я́же ти возвісти́л єси́ нам о безначальнем битії́ Триіпоста́снаго Бо́га: подо́бно бо Мойсе́ю, во громіх і блистаніїх на горі́ прия́л єси́ от Бо́га та́йну богосло́вія і возгласи́л єси́ ми́ру, я́ко в нача́лі бі Сло́во, Отцю́ іскони́ неразлу́чноє і всему́ су́щему вино́вноє, іму́щеє Світ Жи́зні, єго́же тьма не мо́жеть об'яти. Озаря́ємі такови́м облистанієм сві́та Боже́ственния І́стини, почита́єм тя я́ко таї́нника Безнача́льния Тро́йці і воспіва́єм тя я́ко Богосло́ва совершеннейшаго:","Ра́дуйся, о́рле, воспаривий до самаго́ огнеобразнаго Престо́ла Бо́жия;","ра́дуйся, трубо́, возвісти́вшая ми́ру Предві́чнаго і Безнача́льнаго Бо́га.","Ра́дуйся, челові́чество і Божество́ Христо́во нам ізьясняяй;","ра́дуйся, ди́вная словеса́ і наставле́нія Госпо́дня во Єва́нгелії твоє́м нам возвіща́яй.","Ра́дуйся, любві́ ді́лом і і́стиною нас науча́яй;","ра́дуйся, пребива́ющим в любві́ пребива́ніє в них Бо́га обещаваяй.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ душі́ челові́чеськія, вся́ко поуча́л єси́ лю́ди ві́ровати во Христа́ Си́на Бо́жия, імі́ти со́вість незазо́рну і люби́ти друг дру́га, да возмо́гуть не то́кмо зді, но і в селе́ніїх пра́ведних воспі́ти лі́потно Всемогу́щему Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ни Го́рняго Ієрусали́ма узрі́во во открове́нії, возвісти́л єси́ нам, я́же та́мо ви́діл єси́ і я́же і́муть би́ти до сконча́нія ми́ра, сказу́я нам сіє́ іносказа́тельними словеси́, я́же мо́жеть разумі́ти то́кмо ум, імі́яй му́дрость. Удивляющеєся таково́му да́ру проро́чествія, тебі́ от Бо́га дарованному, воспіва́єм тя си́це:","Ра́дуйся, позна́нієм Су́щаго і І́же бі і Гряду́щаго превозше́дий єстество́ челові́чеськоє;","ра́дуйся, вмісти́лище та́їнств, невместимих челові́чеським умо́м, би́вий.","Ра́дуйся, неізрече́нная Бо́жия открове́нія узрі́вий;","ра́дуйся, сія́ ві́рним преподавий.","Ра́дуйся, ра́дости святи́х єще́ в жи́зні сей позна́вий;","ра́дуйся, о́ними ни́ні в преізбиточествії наслажда́яйся.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє принесе́ тебі́, святи́й апо́столе Іоа́нне, христия́нин, і́же в нищету́ прише́д і не іми́й чим возда́ти свої́м заімодавцем, во отча́яніє впаде́ і іска́ше сам себе́ умертви́ти; ти же, пропові́дник любве́ ко бли́жнім сий, жела́я ізба́вити того́ от вре́менния і ві́чния сме́рти, крестним зна́менієм сі́но во зла́то претвори́л єси́ і сіє́ тому́ вручи́л єси́, да сим зла́том і до́лги отда́сть заімодавцем, і дом свой пропитаєть, Бо́гу же, тобо́ю єго́ облагодетельствовавшему, да поє́ть: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная душа́ твоя́, дости́гши в мі́ру во́зраста соверше́ннаго, позна́ла єсть приближеніє вре́мене, єгда́ подоба́єть тлі́нному наслі́дити обіща́нноє нетлі́ніє і сме́ртному обіща́нноє безсме́ртіє. Скончава́я у́бо земно́є житіє́ твоє́, повелі́л єси́ ученико́м твої́м земле́ю покри́ти до верха́ ті́ло твоє́; сли́шавше же о сем, су́щії во гра́ді бра́тія прийдо́ша ко гро́бу твоєму́ і, откопавше, нічто́же в нем обріто́ша. Ті́мже позна́вше, я́ко ізміне́ніє твоє́ сотвори́ся не оби́чним челові́чеським сме́ртним успе́нієм, воспі́ша тебі́ та́ко:","Ра́дуйся, о́рле, обнови́вий ю́ность твою́ приближе́нієм к Со́лнцю Сла́ви Бо́жия;","ра́дуйся, такови́м ізміне́нієм превозше́дий вся уста́ви єстества́ челові́чеськаго.","Ра́дуйся, по обітова́нію Блага́го Учи́теля твоєго́ возсі́дий на єди́нім от двана́десяти престо́лов;","ра́дуйся, творя́й на том суд і пра́вду посреді́ люде́й Бо́жиїх Ізра́їля.","Ра́дуйся, наслажда́яйся лицезрі́нієм Сладча́йшаго Ісу́са, к Нему́же на пе́рси пре́жде Єго́ стра́сті і Воскресе́нія возле́гл єси́;","ра́дуйся, от Єго́ милосе́рдія хода́тайствуяй нам вся блага́я.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 12","ps":["Благода́ть дана́ бисть от Бо́га мі́сту тому́, іді́же ті́ло твоє́ землі́ пре́дано бя́ше, да іспускаєть в день погребе́нія твоєго́ то́нкий прах на ісціле́ніє боля́щим, показу́я сим чу́дом, ка́ко прославля́єть Бог люб'ящия Єго́, да всі, зря́ще сіє́, непреста́нно се́рдцем і усти́ во дні і в нощі́ вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще труди́ твоя́ во апо́стольстві і чудеса́ і ісціле́нія, я́же істоча́л єси́, і істоча́єши благода́тію Ду́ха Свята́го, в тебі́ обита́ющаго, восхваля́єм Бо́га, дарова́вшаго нам такова́го путеводи́теля, наставля́ющаго нас на путь спасе́нія і милосердующаго о не́мощіх на́ших. Прийми́ у́бо от нас, святи́й апо́столе, похвали́ сицеви́я:","Ра́дуйся, благові́стниче ві́ри Христо́ви усе́рднійший;","ра́дуйся, учи́телю Це́ркве Христо́ви ізря́днійший.","Ра́дуйся, богосло́вов нача́ло і основа́ніє;","ра́дуйся, Боже́ственних Тайн возвісти́телю.","Ра́дуйся, ді́вствующих о́бразе і цілому́дрія пра́вило;","ра́дуйся, всіх ві́рних, ко твоєму́ заступле́нію прибіга́ющих, ско́рий помо́щниче і покрови́телю.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 13","ps":["О пресла́вний і всехва́льний апо́столе і євангели́сте, напе́рсниче Христо́во возлю́бленний Іоа́нне! Твої́м всеси́льним хода́тайством ко Всеблаго́му твоєму́ Учи́телю і на́шему Влади́ці і Го́споду іспроси́ нам вся блага́я вре́менная і ві́чная і христия́нськую кончи́ну житія́ на́шего, да с тобо́ю і со а́нгельськими ли́ки в селе́нії пра́ведних воспоє́м Трийпоста́сному Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельських сил і вся́кия тва́рі Творця́, Влади́ку і Го́спода, восприє́мшаго плоть на́шу і я́вльшагося на землі́ спасе́нія на́шего ра́ди, узрі́в ходя́ща при мо́рі Галиле́йстім і взива́юща тя со бра́том твої́м, Іоа́нне блаже́нне, в зва́ніє апо́стольства, оста́вль мре́жі ри́барськия і отця́ твоєго́ в корабли́, неукло́нно отто́лі послі́довал єси́ стопа́м Спаси́телевим. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, любве́ ра́ди ко Христу́ отця́ по пло́ті оста́вивий;","ра́дуйся, Христо́м Небе́снаго Отця́ обріти́й.","Ра́дуйся, мир і вся єго́ пре́лести презрі́вий;","ра́дуйся, небе́сная блага́я во воздая́ніє получи́вий.","Ра́дуйся, плоть ду́ху соверше́нно поработи́вий;","ра́дуйся, дух твой Сладча́йшему твоєму́ Учи́телю Ісу́су покори́вий.","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Кондак 1","ps":["Ізбра́нний Го́сподем от мре́жей ри́барських на про́повідь Єва́нгелія і от ловли риб на уловле́ніє челові́ков во світ і́стиннаго богові́дінія, вели́кий апо́столе, учениче́, дру́же і напе́рсниче Христо́в, моли́ єди́наго і́стиннаго Человіколю́бця, Єго́же ти приі́скренні возлюби́л єси́, да поми́луєть нас, і́щущих твоєго́ к Нему́ предста́тельства і зову́щих ті:","Ра́дуйся, Іоа́нне апо́столе, напе́рсниче Христо́в і Богосло́ве."]},{"h":"Молитва","ps":["О вели́кий апо́столе, євангели́сте громогла́сний, Богосло́ве ізя́щнійший, тайнови́дче неізрече́нних открове́ній, ді́вственниче і возлю́бленний напе́рсниче Христо́в Іоа́нне! Прийми́ нас, грі́шних, прибіга́ющих под твоє́ си́льноє заступле́ніє і покрови́тельство. Іспроси́ у Всеще́драго Человіколю́бця Христа́ Бо́га на́шего, І́же пред очеси́ твої́ми кров Свою́ за ни, непотре́бния раби́ Своя́, ізлія́л єсть, да не пом'яне́ть беззако́ній на́ших, но да поми́луєть нас і сотвори́ть с на́ми по ми́лості Своє́й: да да́руєть нам здра́віє душе́вноє і тіле́сноє, вся́коє благоде́нствіє і ізоби́ліє, наставля́я нас обраща́ти о́ная во сла́ву Єго́, Творця́, Спаси́теля і Бо́га на́шего, по кончи́ні же вре́менния жи́зні на́шея от немилосе́рдних істяза́телей на возду́шних мита́рствах да ізба́вить нас, і та́ко да дости́гнем, тобо́ю води́мії і покрива́ємії, Го́рняго о́наго Ієрусали́ма, єго́же сла́ву ти во открове́нії зрел єси́, ни́ні же несконча́ємия ра́дости наслажда́єшися. О вели́кий Іоа́нне! Сохрани́ вся гра́ди і страни́ христия́нськия і всіх, призива́ющих і́м'я твоє́, от гла́да, губи́тельства, тру́са і пото́па, огня́ і меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні; ізба́ви нас от вся́кия біди́ і напа́сти і моли́твами твої́ми отврати́ от нас пра́ведний гнів Бо́жий, і іспроси́ нам Єго́ милосе́рдіє. О вели́кий і непостижи́мий Бо́же! Се на умоле́ніє Тебі́ предлага́єм свята́го Іоа́нна, єго́же Ти сподо́бил єси́ неізрече́нних открове́ній, прийми́ о нас хода́тайство, да́руй нам ісполне́ніє проше́ній на́ших во сла́ву Твою́, па́че же соверши́ нас духо́вним соверше́нством к наслажде́нію, жи́зні несконча́ємия в Небе́сних Твої́х оби́телях! О Небе́сний О́тче, созда́вий вся Влади́ко, Всеси́льний Царю́! Косни́ся благода́тію серде́ць на́ших, да, раста́явше, я́ко воск, пролію́ться пред Тобо́ю і бре́нная твар духо́вна сотвори́ться в честь і сла́ву Твою́, і Си́на Твоєго́, і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Апо́столе, Христу́ Бо́гу возлю́бленне, / ускори́ ізба́вити лю́ди безотві́тни, / приє́млеть тя, припа́дающа, / І́же па́дша на пе́рси приє́мий. / Єго́же моли́, Богосло́ве, / і належа́щий о́блак язи́ков разгна́ти, // прося́ нам ми́ра і ве́лія ми́лости."]},{"h":"Кондак, глас 2","ps":["Вели́чія твоя́, ді́вственниче, кто пові́сть? / То́чиши бо чудеса́, і ізлива́єши ісціле́нія, / і мо́лишися о душа́х на́ших, // я́ко Богосло́в і друг Христо́в."]},{"h":"Величання","ps":["Велича́єм тя, апо́столе Христо́в і євангели́сте Іоа́нне Богосло́ве, і чтим болі́зні і труди́ твоя́, ї́миже труди́лся єси́ во благові́стії Христо́ві."]}],"notes":[]}];
export default D;
